  ui_story_5037_50370101_188_dialog_content = "Tapi aku masih belum mengerti apa yang seharusnya kita lakukan. Atau lebih tepatnya, apa yang harus saya lakukan.",
  ui_story_5037_50370101_189_dialog_content = "Misi kami adalah mengadakan tiga konser dalam jangka waktu tertentu.",
  ui_story_5037_50370101_190_dialog_content = "Dan ada banyak hal yang harus Anda lakukan, PlayerName!",
  ui_story_5037_50370101_191_dialog_content = "Seperti menjadwalkan sesi latihan tepat waktu, memilih aktivitas promosi, memproduksi lagu untuk saya, dan sebagainya.",
  ui_story_5037_50370101_192_dialog_content = "Semua itu terdengar benar-benar di luar wilayahku...",
  ui_story_5037_50370101_193_dialog_content = "Pengalaman langsung adalah pengalaman terbaik, PlayerName!",
  ui_story_5037_50370101_194_dialog_content = "Siapa mantan produser Anda, Goldie? Mungkin aku bisa belajar sesuatu dari mereka.",
  ui_story_5037_50370101_195_dialog_content = "Hee, saya adalah produser saya sendiri!",
  ui_story_5037_50370101_196_dialog_content = "Apa? Bukankah itu membuatmu lelah?",
  ui_story_5037_50370101_197_dialog_content = "Itu melelahkan, tapi itu semua di masa lalu.",
  ui_story_5037_50370101_198_dialog_content = "Sekarang saya seorang idola dengan produser eksklusif saya sendiri!",
  ui_story_5037_50370101_199_dialog_content = "Heh...",
  ui_story_5037_50370101_200_dialog_content = "Mengapa saya tidak menunjukkan kepada Anda apa yang seharusnya dilakukan seorang produser saat ini, PlayerName?",
  ui_story_5037_50370101_201_dialog_content = "Tentu!",
  ui_story_5037_50370201_1_dialog_content = "Konser akan segera dimulai...",
  ui_story_5037_50370201_2_dialog_content = "tapi aku lupa meninggalkan obat batuk untuk Goldie di belakang panggung!",
  ui_story_5037_50370201_3_dialog_content = "<color=#828282>*Menggeledah*</color>",
  ui_story_5037_50370201_4_dialog_content = "Aku tidak percaya aku meninggalkan mereka dengan buku referensi.",
  ui_story_5037_50370201_5_dialog_content = "Setidaknya aku menemukan mereka. Sebaiknya aku bawa mereka ke Goldie sekarang!",
  ui_story_5037_50370201_6_dialog_content = "Cepat, Guru!",
  ui_story_5037_50370201_7_dialog_content = "Kedengarannya seperti Fia.",
  ui_story_5037_50370201_8_dialog_content = "Bukankah mereka di belakang panggung?",
  ui_story_5037_50370201_9_dialog_content = "Apa yang kamu lakukan tidur di sini? Konser akan segera dimulai!",
  ui_story_5037_50370201_10_dialog_content = "Aku butuh waktu lama untuk menemukanmu!",
  ui_story_5037_50370201_11_dialog_content = "Bagaimana saya memiliki energi untuk tampil tanpa tidur kecantikan saya?",
  ui_story_5037_50370201_12_dialog_content = "Beri aku beberapa menit lagi, dan aku akan pergi.",
  ui_story_5037_50370201_13_dialog_content = "<size=45>Menguasai-!</size>",
  ui_story_5037_50370201_14_dialog_content = "Bagaimana bisa kau begitu santai di saat seperti ini?!",
  ui_story_5037_50370201_15_dialog_content = "Goldie dan PlayerName sudah berlatih banyak.",
  ui_story_5037_50370201_16_dialog_content = "Nah, jika mereka sudah melakukannya, saya rasa kita tidak perlu melakukannya.",
  ui_story_5037_50370201_17_dialog_content = "Buang-buang waktu bagi semua orang untuk melakukan hal yang sama.",
  ui_story_5037_50370201_18_dialog_content = "* Tarik napas * Apakah Anda memuntahkan omong kosong lagi?",
  ui_story_5037_50370201_19_dialog_content = "Itu satu hal saat latihan, tapi sekarang kita harus serius!",
  ui_story_5037_50370201_20_dialog_content = "Kami tidak akan mendapatkan bonus jika kami kalah PlayerName!",
  ui_story_5037_50370201_21_dialog_content = "Saya tahu! Ayo suruh Shira menggantikanku!",
  ui_story_5037_50370201_22_dialog_content = "TIDAK TIDAK!",
  ui_story_5037_50370201_23_dialog_content = "Saya tidak mengerti ... Mengapa Anda bersikeras mempersulit hidup tuan lama Anda?",
  ui_story_5037_50370201_24_dialog_content = "Hmm, kira-kira siapa yang sesumbar hampir jadi idol.",
  ui_story_5037_50370201_25_dialog_content = "Kapan saya membual, Fia? Itu fakta!",
  ui_story_5037_50370201_26_dialog_content = "Nah, begitulah.",
  ui_story_5037_50370201_27_dialog_content = "Anda memiliki kesempatan untuk menjadi idola hari ini! Bukankah seharusnya kamu senang?",
  ui_story_5037_50370201_28_dialog_content = "Namanya saja tidak apa-apa. Saya tidak ingin menjadi idola nyata.",
  ui_story_5037_50370201_29_dialog_content = "Jika saya melakukannya, itu akan menjadi pelatih idola untuk binatang buas yang menakjubkan!",
  ui_story_5037_50370201_30_dialog_content = "Semakin banyak alasan bagi Anda untuk menghasilkan uang sehingga Anda dapat merawat makhluk yang Anda miliki!",
  ui_story_5037_50370201_31_dialog_content = "Bayaran untuk tampil di acara itu hanya dapat menopang kebutuhan hidup Anda sendiri.",
  ui_story_5037_50370201_32_dialog_content = "Anda harus mengalahkan PlayerName jadi kami memiliki sarana untuk meningkatkan kehidupan binatang buas yang menakjubkan!",
  ui_story_5037_50370201_33_dialog_content = "Tapi saya bekerja keras dan mengambil pekerjaan sampingan...",
  ui_story_5037_50370201_34_dialog_content = "Gaji yang digabungkan dari pekerjaan itu bahkan tidak cocok dengan pertunjukan ini.",
  ui_story_5037_50370201_35_dialog_content = "Hewan malang akan mati kelaparan jika Anda tetap melakukan pekerjaan sampingan itu.",
  ui_story_5037_50370201_36_dialog_content = "Saya harus membuat Anda terikat kali ini dan menangkan bonus itu!",
  ui_story_5037_50370201_37_dialog_content = "(Saya tidak cukup mendengar apa yang mereka katakan ...)",
  ui_story_5037_50370201_38_dialog_content = "(Tapi Fia terdengar bertekad dan mengesankan. Sebagai perbandingan, saya merasa...)",
  ui_story_5037_50370201_39_dialog_content = "Wow, obat batuk ini benar-benar minty dan keren!",
  ui_story_5037_50370201_40_dialog_content = "Anda sangat bijaksana memikirkan hal ini, Produser PlayerName!",
  ui_story_5037_50370201_41_dialog_content = "...",
  ui_story_5037_50370201_42_dialog_content = "Apa yang sedang kaupikirkan?",
  ui_story_5037_50370201_43_dialog_content = "Tidak ada apa-apa. Aku hanya senang kamu menyukainya.",
  ui_story_5037_50370201_44_dialog_content = "Kedepannya saya akan menyiapkan rasa obat batuk yang lebih menenangkan dan enak untuk melegakan tenggorokan Anda!",
  ui_story_5037_50370201_45_dialog_content = "Hei, sepertinya kamu sudah siap untuk pergi.",
  ui_story_5037_50370201_46_dialog_content = "Ya! Saya akan memastikan Anda menyukai hasilnya!",
  ui_story_5037_50370201_47_dialog_content = "Cintai kepercayaan diri Anda, sayang. Saya menantikannya.",
  ui_story_5037_50370201_48_dialog_content = "Eh, Nona Sheol?",
  ui_story_5037_50370201_49_dialog_content = "Ya, PlayerName?",
  ui_story_5037_50370201_50_dialog_content = "Akankah Vic tampil bersama Goldie di atas panggung?",
  ui_story_5037_50370201_51_dialog_content = "Apa yang kau khawatirkan?",
  ui_story_5037_50370201_52_dialog_content = "Oh, aku hanya memeriksa.",
  ui_story_5037_50370201_53_dialog_content = "Lanjutkan saja apa yang telah Anda rencanakan.",
  ui_story_5037_50370201_54_dialog_content = "Konser Vic tidak ada di sini. Itu di panggung tetangga.",
  ui_story_5037_50370201_55_dialog_content = "Goldie dan Vic akan mengadakan pertunjukan mereka secara bersamaan.",
  ui_story_5037_50370201_56_dialog_content = "Tahap lain? Tidak heran saya tidak melihat Vic di belakang panggung.",
  ui_story_5037_50370201_57_dialog_content = "Saya mengerti. Jadi Anda mengantisipasi hal ini saat Anda membangun gedung konser, ya?",
  ui_story_5037_50370201_58_dialog_content = "Itu sebabnya Anda menyiapkan dua tahapan berdampingan.",
  ui_story_5037_50370201_59_dialog_content = "Dua tahap berdampingan?",
  ui_story_5037_50370201_60_dialog_content = "Anda harus terkejut, Sayang. Ini adalah salah satu karya terbaik saya.",
  ui_story_5037_50370201_61_dialog_content = "Hanya satu lorong yang memisahkan kedua etape tersebut.",
  ui_story_5037_50370201_62_dialog_content = "Setelah pertunjukan dimulai, penonton dapat mengikuti preferensi mereka dan bergerak bebas di antara panggung.",
  ui_story_5037_50370201_63_dialog_content = "Pada akhirnya, tahap mana pun yang berhasil menarik lebih banyak penonton akan dinyatakan sebagai pemenang.",
  ui_story_5037_50370201_64_dialog_content = "Pengalamannya akan belum pernah terjadi sebelumnya, dan mendapatkan publisitas untuk reality show juga.",
  ui_story_5037_50370201_65_dialog_content = "Pastikan Anda mengedit baris terakhir dari siaran itu, Lilica.",
  ui_story_5037_50370201_66_dialog_content = "Bukan masalah!",
  ui_story_5037_50370201_67_dialog_content = "(Saya sudah sangat terbiasa dengan Lilica dan kameranya sehingga saya lupa dia bersama kami!)",
  ui_story_5037_50370201_68_dialog_content = "Kalau begitu, semoga berhasil, sayang!",
  ui_story_5037_50370201_69_dialog_content = "Mengapa kami tidak diberitahu tentang ini?",
  ui_story_5037_50370201_70_dialog_content = "Sekarang saya perlu mengerjakan ulang program konser agar lebih memikat!",
  ui_story_5037_50370201_71_dialog_content = "Ah! Saya belum memeriksa suara dan pencahayaannya ...",
  ui_story_5037_50370201_72_dialog_content = "Anda melakukan pemeriksaan, PlayerName.",
  ui_story_5037_50370201_73_dialog_content = "Apa? Ya?",
  ui_story_5037_50370201_74_dialog_content = "Ada apa dengan ingatanku...",
  ui_story_5037_50370201_75_dialog_content = "Kamu gugup, PlayerName?",
  ui_story_5037_50370201_76_dialog_content = "Tenang, kami telah berusaha keras dalam persiapan kami!",
  ui_story_5037_50370201_77_dialog_content = "Kita tidak perlu memikirkan apa yang akan terjadi.",
  ui_story_5037_50370201_78_dialog_content = "Selama kami melakukan pertunjukan seperti yang kami latih dan membuat penonton senang, kami dapat menganggapnya sebagai kemenangan!",
  ui_story_5037_50370201_79_dialog_content = "Ya, ya, Anda benar, Goldie.",
  ui_story_5037_50370201_80_dialog_content = "Kita hanya perlu menunjukkan kepada mereka apa yang telah kita latih!",
  ui_story_5037_50370201_81_dialog_content = "<color=#793f76>Lima menit</color> ke pertunjukan!",
  ui_story_5037_50370201_82_dialog_content = "Ahhhh!",
  ui_story_5037_50370201_83_dialog_content = "Tidak tidak tidak! Rasanya seperti saya masih memiliki banyak hal yang harus dilakukan!",
  ui_story_5037_50370201_84_dialog_content = "Santai. Yang harus kita lakukan sekarang adalah menunggu pertunjukan dimulai!",
  ui_story_5037_50370201_85_dialog_content = "Yang benar?",
  ui_story_5037_50370201_86_dialog_content = "Maaf. Saya harap kecemasan saya tidak memengaruhi Anda.",
  ui_story_5037_50370201_87_dialog_content = "Saya benar-benar bukan produser yang kompeten.",
  ui_story_5037_50370201_88_dialog_content = "Itu tidak benar!",
  ui_story_5037_50370201_89_dialog_content = "Ini baru pertama kali!",
  ui_story_5037_50370201_90_dialog_content = "Anda menunjukkan ketenangan seribu kali lebih banyak sekarang daripada saat saya naik panggung untuk pertama kalinya.",
  ui_story_5037_50370201_91_dialog_content = "Pertama kali Anda di atas panggung?",
  ui_story_5037_50370201_92_dialog_content = "Ya. Tidak ada yang mau memberi saya kesempatan saat itu.",
  ui_story_5037_50370201_93_dialog_content = "Saya harus berjuang untuk mendapatkan kesempatan tampil di atas panggung.",
  ui_story_5037_50370201_94_dialog_content = "Selanjutnya, Goldie akan membawakan kita lagu bahagia!",
  ui_story_5037_50370201_95_dialog_content = "H...Hai semuanya!",
  ui_story_5037_50370201_96_dialog_content = "Siapa yang mengajari kalian?",
  ui_story_5037_50370201_97_dialog_content = "Tidak tahu, tidak peduli.",
  ui_story_5037_50370201_98_dialog_content = "Sudahlah. Ini saat yang tepat untuk lari ke kamar kecil.",
  ui_story_5037_50370201_99_dialog_content = "Huh...",
  ui_story_5037_50370201_100_dialog_content = "(Kenapa begitu banyak dari mereka yang pergi begitu saja?)",
  ui_story_5037_50370201_101_dialog_content = "(Semua orang hanya menatap.)",
  ui_story_5037_50370201_102_dialog_content = "(Ngomong-ngomong, kenapa aku ada di sini?)",
  ui_story_5037_50370201_103_dialog_content = "(Apa yang saya lakukan disini...?)",
  ui_story_5037_50370201_104_dialog_content = "Apakah Anda akan melakukan sesuatu atau hanya berdiri di sana?",
  ui_story_5037_50370201_105_dialog_content = "Turun dari panggung jika Anda tidak bisa bernyanyi!",
  ui_story_5037_50370201_106_dialog_content = "Eh, aku...",
  ui_story_5037_50370201_107_dialog_content = "Mereka mencemooh Anda dari panggung?",
  ui_story_5037_50370201_108_dialog_content = "Maaf, saya tidak bermaksud mengingatkan Anda tentang kenangan buruk seperti itu.",
  ui_story_5037_50370201_109_dialog_content = "Oh, jangan khawatir. Itu tidak mengganggu saya lagi.",
  ui_story_5037_50370201_110_dialog_content = "Hah?",
  ui_story_5037_50370201_111_dialog_content = "Saya berkata pada diri sendiri saat itu bahwa awal dari setiap perjalanan itu sulit.",
  ui_story_5037_50370201_112_dialog_content = "Tidak apa-apa membuat kesalahan, asal jangan membuat kesalahan yang sama dua kali!",
  ui_story_5037_50370201_113_dialog_content = "Setelah itu, saya tidak pernah begitu gugup sehingga saya lupa lirik saya lagi.",
  ui_story_5037_50370201_114_dialog_content = "Tetapi jika saya tidak mengatasi demam panggung saya pertama kali dan malah berkubang dalam kesengsaraan saya...",
  ui_story_5037_50370201_115_dialog_content = "Saya tidak akan menjadi seperti sekarang ini.",
  ui_story_5037_50370201_116_dialog_content = "Sangat menginspirasi!",
  ui_story_5037_50370201_117_dialog_content = "Sebenarnya, aku masih sedikit gugup sampai sekarang.",
  ui_story_5037_50370201_118_dialog_content = "Tetapi sedikit stres akan meningkatkan fokus Anda dan membuat Anda bekerja lebih baik.",
  ui_story_5037_50370201_119_dialog_content = "Saya tidak tahu Anda gugup sama sekali!",
  ui_story_5037_50370201_120_dialog_content = "Betulkah? Itu mungkin karena kamu terlalu gugup, jadi aku terlihat santai jika dibandingkan.",
  ui_story_5037_50370201_121_dialog_content = "Tapi bagaimanapun, poin saya adalah ...",
  ui_story_5037_50370201_122_dialog_content = "Percayalah padaku.",
  ui_story_5037_50370201_123_dialog_content = "Lagipula, aku adalah idola veteran yang tangguh di atas panggung.",
  ui_story_5037_50370201_124_dialog_content = "Belum lagi saya sekarang memiliki produser hebat yang memilihkan lagu, kostum, dan properti yang fantastis untuk saya.",
  ui_story_5037_50370201_125_dialog_content = "Oh ya, dan obat batuk terbaik yang pernah kumiliki juga!",
  ui_story_5037_50370201_126_dialog_content = "Jadi aku tidak akan mengecewakanmu!",
  ui_story_5037_50370201_127_dialog_content = "Goldie...",
  ui_story_5037_50370201_128_dialog_content = "Maka aku juga tidak boleh mengecewakanmu!",
  ui_story_5037_50370201_129_dialog_content = "Sepuluh detik sebelum konser dimulai!",
  ui_story_5037_50370201_130_dialog_content = "Sepuluh... sembilan... delapan... tujuh...",
  ui_story_5037_50370201_131_dialog_content = "Saatnya saya tampil di atas panggung, Produser!",
  ui_story_5037_50370201_132_dialog_content = "Patah kaki, Goldie!",
  ui_story_5037_50370201_133_dialog_content = "Terima kasih!",
  ui_story_5037_50370301_1_dialog_content = "Ke mana pun Goldie pergi, Goldilocks mengikuti!",
  ui_story_5037_50370301_2_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370301_3_dialog_content = "Kerumunan dipompa!",
  ui_story_5037_50370301_4_dialog_content = "Acaranya sudah selesai, tapi mereka masih meneriakkan nama Goldie.",
  ui_story_5037_50370301_5_dialog_content = "Saya kembali, PlayerName!",
  ui_story_5037_50370301_6_dialog_content = "Kerja bagus, Goldie!",
  ui_story_5037_50370301_7_dialog_content = "Hey apa yang salah? Mengapa Anda terlihat seperti Anda akan menangis?",
  ui_story_5037_50370301_8_dialog_content = "Kami berhasil... Kami berhasil!",
  ui_story_5037_50370301_9_dialog_content = "Itu berjalan sangat baik. Semua orang pindah ke setiap catatan Anda.",
  ui_story_5037_50370301_10_dialog_content = "Ya, saya juga merasakannya di luar sana, rasanya seperti menyatu dengan panggung!",
  ui_story_5037_50370301_11_dialog_content = "Balada Anda membuat banyak dari mereka menangis.",
  ui_story_5037_50370301_12_dialog_content = "Dan lagu-lagu cepat membuat semua orang melompat mengikuti irama!",
  ui_story_5037_50370301_13_dialog_content = "Anda mengeluarkan kinerja sempurna di luar sana hari ini!",
  ui_story_5037_50370301_14_dialog_content = "Semua berkat produser saya yang hebat, tentu saja.",
  ui_story_5037_50370301_15_dialog_content = "Saya tidak pernah menyadari bahwa saya bisa menguasai lagu seperti itu sebelumnya!",
  ui_story_5037_50370301_16_dialog_content = "Itu hanya mungkin karena pencahayaan dan desain panggung.",
  ui_story_5037_50370301_17_dialog_content = "Jangankan penonton, bahkan saya menikmati penampilannya.",
  ui_story_5037_50370301_18_dialog_content = "Anda sama sekali tidak terlihat seperti pemula, Anda tahu.",
  ui_story_5037_50370301_19_dialog_content = "Sebaliknya, Anda seperti produser idola serba bisa yang mampu menangani apa saja!",
  ui_story_5037_50370301_20_dialog_content = "Haha, Anda menyanjung saya... Saya masih memiliki banyak ruang untuk perbaikan.",
  ui_story_5037_50370301_21_dialog_content = "Saya hampir membuat kesalahan dan tidak mengeluarkan salah satu alat peraga tepat waktu.",
  ui_story_5037_50370301_22_dialog_content = "Butuh pengalaman Anda untuk mencegah bencana.",
  ui_story_5037_50370301_23_dialog_content = "Tetapi Anda tidak akan membuat kesalahan yang sama lain kali, bukan?",
  ui_story_5037_50370301_24_dialog_content = "A-Sama sekali tidak!",
  ui_story_5037_50370301_25_dialog_content = "Haha!",
  ui_story_5037_50370301_26_dialog_content = "Oh, Lady Sheol bilang dia akan mengumumkan hasilnya di agensi.",
  ui_story_5037_50370301_27_dialog_content = "Oke, ayo pergi.",
  ui_story_5037_50370301_28_dialog_content = "Ada apa denganmu, Guru? Anda tidak tampil habis-habisan di atas panggung!",
  ui_story_5037_50370301_29_dialog_content = "Tapi yang mengejutkan, mereka senang melihat Anda menjadi diri Anda yang malas.",
  ui_story_5037_50370301_30_dialog_content = "Mereka mengira itu adalah bagian yang disengaja dari tindakan Anda!",
  ui_story_5037_50370301_31_dialog_content = "Saya kira Anda memiliki bakat untuk menjadi idola ...",
  ui_story_5037_50370301_32_dialog_content = "Bukankah sudah kubilang aku hampir menjadi satu?",
  ui_story_5037_50370301_33_dialog_content = "Lalu mengapa Anda tidak berhasil debut sampai hari ini?",
  ui_story_5037_50370301_34_dialog_content = "Hmm? Aku penasaran...",
  ui_story_5037_50370301_35_dialog_content = "Karena aku terus mengawasi latihanmu!",
  ui_story_5037_50370301_36_dialog_content = "Vic dan Fia benar-benar bersenang-senang.",
  ui_story_5037_50370301_37_dialog_content = "Sepertinya konser mereka sukses juga.",
  ui_story_5037_50370301_38_dialog_content = "...",
  ui_story_5037_50370301_39_dialog_content = "Jangan terlihat begitu stres! Vic dan aku sama-sama idola Starlit Agency.",
  ui_story_5037_50370301_40_dialog_content = "Ini berita luar biasa bahwa kami berdua memiliki debut yang sukses!",
  ui_story_5037_50370301_41_dialog_content = "Ya, kau benar!",
  ui_story_5037_50370301_42_dialog_content = "Saya melihat bahwa semua orang telah tiba.",
  ui_story_5037_50370301_43_dialog_content = "Kerja bagus di sekitar. Sekarang izinkan saya langsung ke pengejaran.",
  ui_story_5037_50370301_44_dialog_content = "Hasil dari konser tersebut adalah sebagai berikut:",
  ui_story_5037_50370301_45_dialog_content = "...",
  ui_story_5037_50370301_46_dialog_content = "Lanjutkan...",
  ui_story_5037_50370301_47_dialog_content = "Dasi!",
  ui_story_5037_50370301_48_dialog_content = "Apa?",
  ui_story_5037_50370301_49_dialog_content = "Timer pertama kami berdiri sendiri melawan idola berpengalaman, menjadikannya seri.",
  ui_story_5037_50370301_50_dialog_content = "Acara ragam kami pasti penuh liku-liku.",
  ui_story_5037_50370301_51_dialog_content = "Saya tidak perlu khawatir tentang peringkat mulai sekarang!",
  ui_story_5037_50370301_52_dialog_content = "Izinkan saya untuk mengingatkan Anda, sayangku.",
  ui_story_5037_50370301_53_dialog_content = "Kedua idola menerima jumlah dukungan yang sama di konser ini...",
  ui_story_5037_50370301_54_dialog_content = "tapi kita masih punya <color=#793f76>dua</color> lebih banyak konser lagi.",
  ui_story_5037_50370301_55_dialog_content = "Ini adalah <color=#793f76>dukungan kipas kumulatif</color> Anda mendapatkan setelah ketiga konser yang saya pertimbangkan.",
  ui_story_5037_50370301_56_dialog_content = "Jadi terlepas dari bagaimana perasaan Anda tentang kinerja ini,",
  ui_story_5037_50370301_57_dialog_content = "bersiaplah untuk konser evaluasi selanjutnya!",
  ui_story_5037_50370301_58_dialog_content = "Saya harus benar-benar berbakat untuk membuat jalan buntu Nona Goldie!",
  ui_story_5037_50370301_59_dialog_content = "Tapi saya rasa tulang lama saya tidak bisa menahan lebih banyak latihan, jadi bisakah saya pulang sekarang—",
  ui_story_5037_50370301_60_dialog_content = "Apakah kamu bercanda?! Hasilnya membuktikan...",
  ui_story_5037_50370301_61_dialog_content = "bahwa jika Anda tidak menahan apa pun dan benar-benar menunjukkan potensi Anda, kami akan mengalahkan Goldie dan PlayerName!",
  ui_story_5037_50370301_62_dialog_content = "Sekarang kita harus mulai dari awal lagi.",
  ui_story_5037_50370301_63_dialog_content = "Jangan pernah berpikir untuk bermalas-malasan lain kali, Guru!",
  ui_story_5037_50370301_64_dialog_content = "Oi, Fia! Kemana kamu pergi?",
  ui_story_5037_50370301_65_dialog_content = "Ruang latihan untuk berlatih, duh!",
  ui_story_5037_50370301_66_dialog_content = "Oh astaga... Kapan aku bisa istirahat?",
  ui_story_5037_50370301_67_dialog_content = "Kylo! Seret dia ke sini!",
  ui_story_5037_50370301_68_dialog_content = "Lihat!",
  ui_story_5037_50370301_69_dialog_content = "Jadilah lembut! Kylo...",
  ui_story_5037_50370301_70_dialog_content = "Vic sangat mengesankan?",
  ui_story_5037_50370301_71_dialog_content = "Ya, aku tahu dia punya potensi untuk menjadi populer begitu aku melihatnya.",
  ui_story_5037_50370301_72_dialog_content = "Ditambah Fia benar-benar bekerja keras sebagai produsernya.",
  ui_story_5037_50370301_73_dialog_content = "Saya mendengar dia sendiri menonton latihan Vic sampai tengah malam setiap hari.",
  ui_story_5037_50370301_74_dialog_content = "Saya sendiri sebenarnya melihatnya beberapa kali.",
  ui_story_5037_50370301_75_dialog_content = "Setiap kali Vic mengendur, Fia akan menyuruh Kyllo menggigit pergelangan kakinya!",
  ui_story_5037_50370301_76_dialog_content = "Apakah makhluk itu benar-benar motivator yang ampuh?",
  ui_story_5037_50370301_77_dialog_content = "Haruskah saya menemukan Kyllo saya sendiri untuk menggigit pergelangan kaki saya?",
  ui_story_5037_50370301_78_dialog_content = "Aku tidak berpikir itu perlu.",
  ui_story_5037_50370301_79_dialog_content = "Anda sudah bekerja keras tanpa dorongan eksternal semacam itu!",
  ui_story_5037_50370301_80_dialog_content = "Akulah yang sangat membutuhkan Kyllo.",
  ui_story_5037_50370301_81_dialog_content = "Seorang pemula hanya mengejar idola luar biasa sepertimu karena aku tidak bekerja cukup keras.",
  ui_story_5037_50370301_82_dialog_content = "Anda tidak perlu melihatnya seperti itu, PlayerName.",
  ui_story_5037_50370301_83_dialog_content = "Popularitas tidak pernah menjadi ilmu pasti.",
  ui_story_5037_50370301_84_dialog_content = "Setidaknya saya menikmati pertunjukan hari ini dan tidak meninggalkan penyesalan. Itu cukup bagi saya!",
  ui_story_5037_50370301_85_dialog_content = "Terima kasih…",
  ui_story_5037_50370301_86_dialog_content = "Anda dapat menghibur saya, tetapi saya tidak dapat menghibur diri saya sendiri!",
  ui_story_5037_50370301_87_dialog_content = "Eh?",
  ui_story_5037_50370301_88_dialog_content = "Saya akan terus bekerja keras untuk memahami nuansa menjadi seorang produser",
  ui_story_5037_50370301_89_dialog_content = "jadi saya bisa merencanakan jadwal pelatihan yang lebih baik untuk Anda.",
  ui_story_5037_50370301_90_dialog_content = "Lalu kita akan mengadakan konser yang menggemparkan!",
  ui_story_5037_50370301_91_dialog_content = "PlayerName…",
  ui_story_5037_50370301_92_dialog_content = "Satu saja tidak akan berhasil. Kami masih memiliki dua pertunjukan lagi... Ditambah banyak lagi di masa depan!",
  ui_story_5037_50370301_93_dialog_content = "Benar, izinkan saya mengulanginya!",
  ui_story_5037_50370301_94_dialog_content = "Semua konser kami akan menggemparkan mulai sekarang!",
  ui_story_5037_50370301_95_dialog_content = "Ya!",
  ui_story_5037_50370301_96_dialog_content = "Saya berharap dapat bekerja sama dengan Anda!",
  ui_story_5037_50370301_97_dialog_content = "Wawancara teman setelah konser...",
  ui_story_5037_50370301_98_dialog_content = "Tindakan!",
  ui_story_5037_50370301_99_dialog_content = "Dari skala satu sampai sepuluh, bagaimana Anda menilai konser tersebut?",
  ui_story_5037_50370301_100_dialog_content = "Maks sepuluh, tentu saja!",
  ui_story_5037_50370301_101_dialog_content = "Saya akan mengatakan delapan. Masih ada ruang untuk perbaikan.",
  ui_story_5037_50370301_102_dialog_content = "Apa yang bisa dicapai keduanya bersama-sama?",
  ui_story_5037_50370301_103_dialog_content = "Apa? Oh ya, aku tidak menonton konsernya.",
  ui_story_5037_50370301_104_dialog_content = "Tanggapannya sangat positif, katamu?",
  ui_story_5037_50370301_105_dialog_content = "Bagaimana Anda menilai kinerja lawan?",
  ui_story_5037_50370301_106_dialog_content = "Uh... Mungkin sepuluh juga, karena kami melihat usaha keras Vic dan Fia.",
  ui_story_5037_50370301_107_dialog_content = "Delapan lagi. Masih ada ruang untuk perbaikan.",
  ui_story_5037_50370301_108_dialog_content = "Haruskah saya menjawab?",
  ui_story_5037_50370301_109_dialog_content = "Bagaimana teman Anda berubah baru-baru ini?",
  ui_story_5037_50370301_110_dialog_content = "PlayerName jauh lebih disiplin sekarang, dan tidak kesiangan lagi.",
  ui_story_5037_50370301_111_dialog_content = "Dia pembelajar yang jauh lebih cepat daripada yang saya perkirakan, dan benar-benar beradaptasi dengan peran sebagai produser dengan cukup cepat.",
  ui_story_5037_50370301_112_dialog_content = "Entahlah, mereka terlihat sama bagiku.",
  ui_story_5037_50370301_113_dialog_content = "Dan itu penutup untuk wawancara pasca-konser!",
  ui_story_5037_50370301_114_dialog_content = "Apa? Mereka sudah mulai berlatih?",
  ui_story_5037_50370301_115_dialog_content = "Saya harus memfilmkan ini!",
  ui_story_5037_50370401_1_dialog_content = "Ke mana prop yang lebih besar ini pergi, Produser?",
  ui_story_5037_50370401_2_dialog_content = "Tolong pindahkan ke panggung tengah, dan pastikan itu benar-benar terpusat.",
  ui_story_5037_50370401_3_dialog_content = "Bagaimana pencahayaan ini, Produser?",
  ui_story_5037_50370401_4_dialog_content = "Terlalu terang. Kecilkan sedikit, tolong.",
  ui_story_5037_50370401_5_dialog_content = "Keberatan memeriksa ini, Produser?",
  ui_story_5037_50370401_6_dialog_content = "Bagaimana dengan masalah ini di sini, Produser?",
  ui_story_5037_50370401_7_dialog_content = "Produsen! Produsen!",
  ui_story_5037_50370401_8_dialog_content = "Satu per satu, satu per satu ...!",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50370401_10_dialog_content = "Fiuh, senang itu sudah berakhir.",
  ui_story_5037_50370401_11_dialog_content = "Bagus.",
  ui_story_5037_50370401_12_dialog_content = "Anda sudah siap, Goldie?",
  ui_story_5037_50370401_13_dialog_content = "Siap!",
  ui_story_5037_50370401_14_dialog_content = "Sama tua, sama tua?",
  ui_story_5037_50370401_15_dialog_content = "Sama tua, sama tua!",
  ui_story_5037_50370401_16_dialog_content = "Ini.",
  ui_story_5037_50370401_17_dialog_content = "Trims!",
  ui_story_5037_50370401_18_dialog_content = "Tunggu, apa itu \"sama tua, sama tua\"? Apakah Anda berbicara dalam kode?",
  ui_story_5037_50370401_19_dialog_content = "Apa yang baru saja Anda berikan kepada Goldie, PlayerName? Kamera saya tidak menangkapnya.",
  ui_story_5037_50370401_20_dialog_content = "Oh, ini hal istimewa yang kita miliki.",
  ui_story_5037_50370401_21_dialog_content = "Mengetahui bahwa saya suka obat batuk mint, produser saya selalu membawanya sendiri.",
  ui_story_5037_50370401_22_dialog_content = "Dia hanya memberiku sepotong, itu saja.",
  ui_story_5037_50370401_23_dialog_content = "Kapan kalian berdua mengembangkan chemistry seperti itu?",
  ui_story_5037_50370401_24_dialog_content = "Hmm, beberapa hari terakhir ini.",
  ui_story_5037_50370401_25_dialog_content = "Kami telah bekerja sama cukup lama sekarang sehingga kami dapat mengetahui apa yang dipikirkan orang lain hanya dengan melihat.",
  ui_story_5037_50370401_26_dialog_content = "Sulit dipercaya...",
  ui_story_5037_50370401_27_dialog_content = "Tunggu!",
  ui_story_5037_50370401_28_dialog_content = "Apa yang harus saya filmkan jika kalian bahkan tidak berbicara?",
  ui_story_5037_50370401_29_dialog_content = "Apakah Anda er, ingin saya berbicara dengannya sekarang?",
  ui_story_5037_50370401_30_dialog_content = "Itu terlalu palsu.",
  ui_story_5037_50370401_31_dialog_content = "Aku tahu!",
  ui_story_5037_50370401_32_dialog_content = "Saya dapat mewawancarai Anda seperti yang saya lakukan dengan teman-teman Anda!",
  ui_story_5037_50370401_33_dialog_content = "Ehehe, aku sangat jenius!",
  ui_story_5037_50370401_34_dialog_content = "Anda mewawancarai teman-teman saya? Kapan?",
  ui_story_5037_50370401_35_dialog_content = "Anda akan tahu kapan acaranya keluar!",
  ui_story_5037_50370401_36_dialog_content = "Sekarang mari luangkan waktu untuk... wawancara eksklusif pra-konser!",
  ui_story_5037_50370401_37_dialog_content = "Tim Eksklusif PlayerName evaluasi konser wawancara...",
  ui_story_5037_50370401_38_dialog_content = "Tindakan!",
  ui_story_5037_50370401_39_dialog_content = "Apa perbedaan antara konser evaluasi dan konser debut?",
  ui_story_5037_50370401_40_dialog_content = "Konser debut hanya membuktikan bahwa saya bisa masuk sebagai idola dengan Starlit Agency.",
  ui_story_5037_50370401_41_dialog_content = "Bagi saya, konser debut seperti pintu gerbang menuju impian saya.",
  ui_story_5037_50370401_42_dialog_content = "Tapi apa yang bisa saya lakukan setelah saya mencapai impian saya?",
  ui_story_5037_50370401_43_dialog_content = "Lakukan yang terbaik dari kemampuan saya untuk membuktikan diri, secara alami.",
  ui_story_5037_50370401_44_dialog_content = "Konser evaluasi adalah ujian dari agensi, yang bertujuan untuk memverifikasi seberapa jauh kami telah berhasil dalam pelatihan kami.",
  ui_story_5037_50370401_45_dialog_content = "Tapi bagi kami, ini lebih seperti ujian kemampuan kami dari Goldilocks.",
  ui_story_5037_50370401_46_dialog_content = "Betul sekali. Saya ingin membuktikan kepada semua orang...",
  ui_story_5037_50370401_47_dialog_content = "bahwa di mana pun saya berada, saya tidak akan pernah lupa dari mana saya berasal!",
  ui_story_5037_50370401_48_dialog_content = "Apakah Anda merasakan tekanan saat mempersiapkan konser?",
  ui_story_5037_50370401_49_dialog_content = "Tidak sama sekali!",
  ui_story_5037_50370401_50_dialog_content = "Hanya bercanda! Itu normal untuk merasakan tekanan.",
  ui_story_5037_50370401_51_dialog_content = "Tapi saya benar-benar bersyukur bahwa produser saya di sini mengambil banyak beban dari pundak saya.",
  ui_story_5037_50370401_52_dialog_content = "Saya bisa fokus pada pelatihan, yang membuat segalanya jadi lebih mudah bagi saya.",
  ui_story_5037_50370401_53_dialog_content = "Adapun seberapa jauh pelatihan datang ... Anda akan melihat di atas panggung nanti!",
  ui_story_5037_50370401_54_dialog_content = "Apakah menurut Anda memproduksi adalah kerja keras?",
  ui_story_5037_50370401_55_dialog_content = "Sejujurnya, di periode tepat sebelum konser debut, saya mengalami masa-masa yang sangat sulit.",
  ui_story_5037_50370401_56_dialog_content = "Saya membuat banyak kesalahan dalam persiapan menjelang pertunjukan.",
  ui_story_5037_50370401_57_dialog_content = "Tapi sekarang saya sudah cukup terbiasa dengan pekerjaan itu dan terbiasa dengan semua seluk beluknya.",
  ui_story_5037_50370401_58_dialog_content = "Saya tidak akan pernah membuat kesalahan yang sama dua kali.",
  ui_story_5037_50370401_59_dialog_content = "Yup, saya bisa bersaksi untuk itu!",
  ui_story_5037_50370401_60_dialog_content = "PlayerName adalah produsen yang sangat profesional sekarang.",
  ui_story_5037_50370401_61_dialog_content = "Dan dia sangat sibuk. Hampir tidak ada waktu untuk tidur.",
  ui_story_5037_50370401_62_dialog_content = "Produsen PlayerName benar-benar bekerja sangat keras untuk mempersiapkan konser!",
  ui_story_5037_50370401_63_dialog_content = "Saya hanya melakukan pekerjaan saya.",
  ui_story_5037_50370401_64_dialog_content = "Mampu membantu Anda mempersiapkan panggung paling mewah untuk memberikan penampilan yang tak terlupakan bagi Goldilocks membuat semuanya berharga bagi saya.",
  ui_story_5037_50370401_65_dialog_content = "Sejujurnya, itu bahkan tidak terasa seperti pekerjaan bagiku!",
  ui_story_5037_50370401_66_dialog_content = "Bisakah Anda memberi kami sedikit petunjuk tentang apa yang telah Anda rencanakan untuk kami?",
  ui_story_5037_50370401_67_dialog_content = "Ini sebuah rahasia.",
  ui_story_5037_50370401_68_dialog_content = "Program kami kali ini benar-benar baru, belum pernah dilihat sebelumnya.",
  ui_story_5037_50370401_69_dialog_content = "Sebenarnya kami bisa membocorkan tema konser kami.",
  ui_story_5037_50370401_70_dialog_content = "Benar.",
  ui_story_5037_50370401_71_dialog_content = "PlayerName datang dengan tiga tema berbeda untuk tiga konser.",
  ui_story_5037_50370401_72_dialog_content = "Tema untuk konser debutnya adalah <color=#793f76>Awal baru</color>. Saya harap penonton menangkap makna di balik itu.",
  ui_story_5037_50370401_73_dialog_content = "Tema untuk acara mendatang adalah <color=#793f76>Bunga Tunas</color>!",
  ui_story_5037_50370401_74_dialog_content = "Untuk itu, saya membuat koreografi rutinitas baru dengan bantuan produser.",
  ui_story_5037_50370401_75_dialog_content = "Anda pasti tidak akan menghabiskan uang untuk melihat pertunjukan lama!",
  ui_story_5037_50370401_76_dialog_content = "Saya hanya menangani logistik. Goldie harus mendapatkan sebagian besar pujian.",
  ui_story_5037_50370401_77_dialog_content = "Pada awalnya, saya akan membuatnya mengulangi beberapa lagu lama.",
  ui_story_5037_50370401_78_dialog_content = "Tapi dia menulis beberapa lagu orisinal hanya untuk konser itu.",
  ui_story_5037_50370401_79_dialog_content = "Itu karena saya tiba-tiba terinspirasi saat latihan suatu hari.",
  ui_story_5037_50370401_80_dialog_content = "Sejak saya memutuskan untuk menjadi idola, hidup adalah perjuangan berat yang selalu saya perjuangkan sendiri.",
  ui_story_5037_50370401_81_dialog_content = "Sekarang, saya tidak hanya memiliki Produser PlayerName untuk membantu saya...",
  ui_story_5037_50370401_82_dialog_content = "tetapi juga, saya memiliki lawan yang meraih tujuan yang sama.",
  ui_story_5037_50370401_83_dialog_content = "Tidak, daripada lawan, saya pikir Vic lebih mirip dengan seorang kawan dalam perjalanan menuju ketenaran ini.",
  ui_story_5037_50370401_84_dialog_content = "Semua perasaan baru ini mengilhami saya untuk menulis banyak lagu baru.",
  ui_story_5037_50370401_85_dialog_content = "Aku mendengarnya berkali-kali selama latihan kami, tapi setiap kali aku mendengarnya...",
  ui_story_5037_50370401_86_dialog_content = "mereka masih memindahkan saya ke inti.",
  ui_story_5037_50370401_87_dialog_content = "Saya percaya semua orang akan menemukan program tulus kami memuaskan secara emosional!",
  ui_story_5037_50370401_88_dialog_content = "Kudengar produser membagikan selebaran setiap hari untuk membantu Goldie?",
  ui_story_5037_50370401_89_dialog_content = "Betulkah? Benarkah itu?",
  ui_story_5037_50370401_90_dialog_content = "Ini adalah pertama kalinya aku mendengarnya... Kenapa kau tidak pernah memberitahuku, PlayerName?",
  ui_story_5037_50370401_91_dialog_content = "Saya hanya melakukan pekerjaan saya.",
  ui_story_5037_50370401_92_dialog_content = "Aku ingat sekarang!",
  ui_story_5037_50370401_93_dialog_content = "Ada kalanya Anda mengatakan sedang mengambil makanan atau camilan ...",
  ui_story_5037_50370401_94_dialog_content = "Anda malah membagikan selebaran?",
  ui_story_5037_50370401_95_dialog_content = "Ya. Maaf, aku tidak ingin mengganggumu, Goldie. Itu sebabnya aku tidak memberitahumu.",
  ui_story_5037_50370401_96_dialog_content = "Anda selalu mengatakan bahwa hasil tidak penting, dan menjalani perjalanan tanpa penyesalan itulah yang penting...",
  ui_story_5037_50370401_97_dialog_content = "tetapi saya masih ingin membantu Anda mendapatkan lebih banyak dukungan.",
  ui_story_5037_50370401_98_dialog_content = "Itu cara terbaik untuk memastikan tidak ada penyesalan, menurut saya.",
  ui_story_5037_50370401_99_dialog_content = "PlayerName…",
  ui_story_5037_50370401_100_dialog_content = "Bawa aku bersamamu lain kali! Pertunjukan jalanan pasti akan lebih menarik!",
  ui_story_5037_50370401_101_dialog_content = "Jangan lupa kita satu tim!",
  ui_story_5037_50370401_102_dialog_content = "Sebuah tim... Ya, kami adalah sebuah tim!",
  ui_story_5037_50370401_103_dialog_content = "Apakah Anda merasa percaya diri tentang konser?",
  ui_story_5037_50370401_104_dialog_content = "Apakah Anda yakin pada saya, PlayerName?",
  ui_story_5037_50370401_105_dialog_content = "Saya telah melihat latihan Goldie. Mereka sempurna, hampir tanpa cela.",
  ui_story_5037_50370401_106_dialog_content = "Hari ini tidak lebih dari tempat baru, jadi saya sangat yakin dengan Goldie!",
  ui_story_5037_50370401_107_dialog_content = "Kebetulan sekali, saya juga sangat percaya diri pada Anda!",
  ui_story_5037_50370401_108_dialog_content = "Sama tua, sama tua?",
  ui_story_5037_50370401_109_dialog_content = "Sama tua, sama tua!",
  ui_story_5037_50370401_110_dialog_content = "Pergi! Pergi! Pergi!",
  ui_story_5037_50370401_111_dialog_content = "Kemana prop ini pergi, Produser?",
  ui_story_5037_50370401_112_dialog_content = "Dimana produsernya?",
  ui_story_5037_50370401_113_dialog_content = "Produsen! Produsen!",
  ui_story_5037_50370401_114_dialog_content = "Ah, aku harus mengurus semuanya!",
  ui_story_5037_50370401_115_dialog_content = "Fiuh…",
  ui_story_5037_50370401_116_dialog_content = "Konser tidak akan mungkin tanpa PlayerName.",
  ui_story_5037_50370401_117_dialog_content = "Sudah waktunya bagi saya untuk mempersiapkan panggung sekarang!",
  ui_story_5037_50370501_1_dialog_content = "Selanjutnya, saya akan mengumumkan hasil kami.",
  ui_story_5037_50370501_2_dialog_content = "Mereka sangat mengejutkan kali ini.",
  ui_story_5037_50370501_3_dialog_content = "(Apa yang bahkan mengejutkan Lady Sheol?)",
  ui_story_5037_50370501_4_dialog_content = "(Apakah Vic menang...?)",
  ui_story_5037_50370501_5_dialog_content = "Pemenang mengatasi tekanan yang dibawa oleh konser pertama untuk berhasil mendapatkan lebih banyak dukungan dari penonton kali ini.",
  ui_story_5037_50370501_6_dialog_content = "Ini adalah buah dari kerja keras sang idola.",
  ui_story_5037_50370501_7_dialog_content = "Begitu juga dengan produser tentunya.",
  ui_story_5037_50370501_8_dialog_content = "(Kerja keras di kedua bagian... Itu Guru dan aku, bukan?)",
  ui_story_5037_50370501_9_dialog_content = "(Ya, Guru akhirnya mengalahkan Goldie!)",
  ui_story_5037_50370501_10_dialog_content = "Dan pemenangnya adalah...",
  ui_story_5037_50370501_11_dialog_content = "...",
  ui_story_5037_50370501_12_dialog_content = "Hehe!",
  ui_story_5037_50370501_13_dialog_content = "<size=45>Goldie dan PlayerName!</size>",
  ui_story_5037_50370501_14_dialog_content = "Apakah kamu mendengar itu, PlayerName? Kami menang!",
  ui_story_5037_50370501_15_dialog_content = "K-Kita menang?",
  ui_story_5037_50370501_16_dialog_content = "Apa? Bagaimana ini bisa terjadi?",
  ui_story_5037_50370501_17_dialog_content = "Akhirnya, satu langkah lebih dekat ke rumah.",
  ui_story_5037_50370501_18_dialog_content = "Fakta memang keras, tetapi angka tidak berbohong, dan kali ini lebih banyak orang yang mendukung Goldie daripada Vic.",
  ui_story_5037_50370501_19_dialog_content = "Tapi penampilan Guru jelas lebih baik dari sebelumnya, jadi kenapa Goldie menang?",
  ui_story_5037_50370501_20_dialog_content = "Nah, Goldie benar-benar memberikan penampilan yang fantastis kali ini.",
  ui_story_5037_50370501_21_dialog_content = "Pertunjukannya sendiri kreatif, tetapi pencahayaan dan desain panggungnya juga rapi.",
  ui_story_5037_50370501_22_dialog_content = "Yang lebih penting adalah konsernya mengubah banyak penonton menjadi penggemarnya.",
  ui_story_5037_50370501_23_dialog_content = "Mereka bergegas ke Cloudrover Guild dan membeli barang dagangannya.",
  ui_story_5037_50370501_24_dialog_content = "Mereka bahkan membeli produk yang tidak ada hubungannya dengan Goldie.",
  ui_story_5037_50370501_25_dialog_content = "Dari mulut ke mulut Goldilocks...",
  ui_story_5037_50370501_26_dialog_content = "Menonton konser Goldie sekarang menjadi salah satu dari sepuluh hal yang harus dilakukan di Umbraton.",
  ui_story_5037_50370501_27_dialog_content = "Semua orang menantikan konser Starlit Agency berikutnya.",
  ui_story_5037_50370501_28_dialog_content = "Tiket sudah terjual habis! Bisakah Anda bayangkan itu?",
  ui_story_5037_50370501_29_dialog_content = "Maksud Anda saya tidak perlu mengemis orang untuk membeli tiket sekarang?",
  ui_story_5037_50370501_30_dialog_content = "Saya tidak pernah berpikir saya akan mendapatkan kembali investasi saya bahkan sebelum reality show ditayangkan.",
  ui_story_5037_50370501_31_dialog_content = "Anda tidak perlu lagi melakukan promosi tambahan untuk mendapatkan penggemar baru.",
  ui_story_5037_50370501_32_dialog_content = "Fokus pada penampilan Anda dan nikmati konser terakhir!",
  ui_story_5037_50370501_33_dialog_content = "Terima kasih, Nona Sheol.",
  ui_story_5037_50370501_34_dialog_content = "Kami akan berusaha untuk meningkatkan dan menghadiahi Anda dan para penggemar dengan penampilan yang lebih baik!",
  ui_story_5037_50370501_35_dialog_content = "Kurasa aku belum mendengar kabar darimu, Vic?",
  ui_story_5037_50370501_36_dialog_content = "Mengapa kita tidak melupakannya saja?",
  ui_story_5037_50370501_37_dialog_content = "Karena aku kalah, sebaiknya biarkan aku pulang sekarang!",
  ui_story_5037_50370501_38_dialog_content = "Saya tidak membelinya, saya hanya tidak membelinya.",
  ui_story_5037_50370501_39_dialog_content = "Saya pikir Anda semua bersekongkol melawan Guru dan saya.",
  ui_story_5037_50370501_40_dialog_content = "Katakan padaku, Nona Sheol!",
  ui_story_5037_50370501_41_dialog_content = "Ini adalah bagaimana Anda menulis naskahnya, bukan?",
  ui_story_5037_50370501_42_dialog_content = "Naskah untuk reality show?",
  ui_story_5037_50370501_43_dialog_content = "Kamu jenius, Fia.",
  ui_story_5037_50370501_44_dialog_content = "Tentu saja! Hehe.",
  ui_story_5037_50370501_45_dialog_content = "Tunggu sebentar, apa yang membuatmu mengatakan itu?",
  ui_story_5037_50370501_46_dialog_content = "Kenapa saya tidak memikirkan sesuatu yang sekreatif menulis naskah untuk reality show?",
  ui_story_5037_50370501_47_dialog_content = "Saya mungkin akan mengganti uang saya lebih cepat.",
  ui_story_5037_50370501_48_dialog_content = "Namun, Fia, hasil babak ini asli.",
  ui_story_5037_50370501_49_dialog_content = "Jika masih ragu, silakan saksikan tayangan ulang konsernya.",
  ui_story_5037_50370501_50_dialog_content = "Bicaralah dengan saya kapan saja jika Anda memiliki pertanyaan sesudahnya.",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50370501_52_dialog_content = "Bagaimana mereka melakukannya? Bagaimana mereka melakukan triknya?!",
  ui_story_5037_50370501_53_dialog_content = "Goldie mengganti pakaiannya hanya dalam sedetik!?",
  ui_story_5037_50370501_54_dialog_content = "Dan muncul begitu saja di antara penonton, lalu terbang kembali ke panggung?",
  ui_story_5037_50370501_55_dialog_content = "Sebaliknya, konser kami gagal.",
  ui_story_5037_50370501_56_dialog_content = "Tidak heran Anda tidak pernah bisa membuatnya sebelumnya ...",
  ui_story_5037_50370501_57_dialog_content = "Eh, ehem.",
  ui_story_5037_50370501_58_dialog_content = "Jadi Anda akhirnya mendapatkannya sekarang? Terlepas dari bakat saya yang luar biasa, saya tidak bisa menjadi idola profesional.",
  ui_story_5037_50370501_59_dialog_content = "Tidak terlalu dini untuk menyerah sekarang. Aku akan pergi berkemas.",
  ui_story_5037_50370501_60_dialog_content = "Tahan di sana!",
  ui_story_5037_50370501_61_dialog_content = "Aku tahu bahkan tanpa kau mengatakannya...",
  ui_story_5037_50370501_62_dialog_content = "bahwa bukan salahmu kami kalah.",
  ui_story_5037_50370501_63_dialog_content = "Saya adalah produsernya, tetapi saya begitu terpaku pada pelatihan Anda sehingga saya mengabaikan hampir semua aspek pertunjukan dan panggung lainnya.",
  ui_story_5037_50370501_64_dialog_content = "Saya pikir Anda adalah kunci kesuksesan selama ini ...",
  ui_story_5037_50370501_65_dialog_content = "Sampai saya baru saja menonton pertunjukan Goldie dan menyadari betapa banyak potensi lain yang bisa dimiliki sebuah konser!",
  ui_story_5037_50370501_66_dialog_content = "Performa Anda luar biasa.",
  ui_story_5037_50370501_67_dialog_content = "Tapi aku gagal memberimu panggung yang sempurna.",
  ui_story_5037_50370501_68_dialog_content = "Sejujurnya, menyelesaikan konser saja sudah cukup baik untukku, jadi jangan khawatir tentang itu dan ayo pulang...",
  ui_story_5037_50370501_69_dialog_content = "Tidak mungkin, aku belum bisa pergi!",
  ui_story_5037_50370501_70_dialog_content = "Kami memiliki satu pertunjukan terakhir yang harus dilakukan. Kita masih bisa membalikkan keadaan.",
  ui_story_5037_50370501_71_dialog_content = "Kali ini, saya berjanji Anda akan dapat mencapai impian idola Anda dan tidak akan menyesal!",
  ui_story_5037_50370501_72_dialog_content = "Apa...?",
  ui_story_5037_50370501_73_dialog_content = "Saya baru saja menonton tayangan ulang konser Vic.",
  ui_story_5037_50370501_74_dialog_content = "Penampilanmu seperti idola pro, Vic.",
  ui_story_5037_50370501_75_dialog_content = "Hanya ada beberapa tarian di dalamnya yang tidak menunjukkan pesonamu dengan baik.",
  ui_story_5037_50370501_76_dialog_content = "Betulkah? Yang mana?",
  ui_story_5037_50370501_77_dialog_content = "Nanti akan saya review dan tunjukkan ke kamu, Fia.",
  ui_story_5037_50370501_78_dialog_content = "Ngomong-ngomong, saya menulis balada baru yang menurut saya cocok untuk Vic.",
  ui_story_5037_50370501_79_dialog_content = "Saya akan memberikannya kepada Anda juga setelah saya selesai meninjau!",
  ui_story_5037_50370501_80_dialog_content = "Bagus!",
  ui_story_5037_50370501_81_dialog_content = "Tapi apakah... apakah ini pantas?",
  ui_story_5037_50370501_82_dialog_content = "Anda adalah pesaing kami, jadi mengapa Anda membantu kami?",
  ui_story_5037_50370501_83_dialog_content = "Berhala seharusnya membawa harapan dan kebaikan kepada orang-orang.",
  ui_story_5037_50370501_84_dialog_content = "Bagaimana saya bisa disebut idola jika saya bahkan tidak bisa membawa kebaikan kepada orang-orang di sekitar saya?",
  ui_story_5037_50370501_85_dialog_content = "Saya ingat apa yang Anda katakan sebelumnya dalam sebuah wawancara ...",
  ui_story_5037_50370501_86_dialog_content = "Daripada seorang lawan, saya pikir Vic lebih mirip dengan seorang kawan dalam perjalanan menuju ketenaran ini.",
  ui_story_5037_50370501_87_dialog_content = "Itu benar-benar brilian ...",
  ui_story_5037_50370501_88_dialog_content = "Luar biasa!!",
  ui_story_5037_50370501_89_dialog_content = "Jadi begitukah seharusnya seorang idola bersikap?",
  ui_story_5037_50370501_90_dialog_content = "Oh, tidak!",
  ui_story_5037_50370501_91_dialog_content = "Orang-orang akan berpikir Guru adalah lelucon karena mengatakan apa yang saya suruh dia katakan dalam wawancara!",
  ui_story_5037_50370501_92_dialog_content = "(Saya ingin tahu apa yang mereka katakan dalam wawancara ...)",
  ui_story_5037_50370501_93_dialog_content = "Maukah Anda menghapus wawancara yang kami lakukan dan merekam yang lain, Lilica?",
  ui_story_5037_50370501_94_dialog_content = "Saya khawatir itu tidak mungkin.",
  ui_story_5037_50370501_95_dialog_content = "Ini reality show, lho!",
  ui_story_5037_50370501_96_dialog_content = "Kemarilah, Kylo!",
  ui_story_5037_50370501_97_dialog_content = "Lihat!",
  ui_story_5037_50370501_98_dialog_content = "Hei, apa yang kamu pikir kamu lakukan?",
  ui_story_5037_50370501_99_dialog_content = "Jangan ulangi bahkan jika Anda membuat Kyllo menggigit pergelangan kaki saya!",
  ui_story_5037_50370501_100_dialog_content = "Tunggu, jangan lari!",
  ui_story_5037_50370501_101_dialog_content = "Jika Anda setuju, Anda bisa bermain dengan Kyllo!",
  ui_story_5037_50370501_102_dialog_content = "Hmm, sepertinya Fia sudah melupakanku...",
  ui_story_5037_50370501_103_dialog_content = "Saya akhirnya bisa mendapatkan kecantikan saya tidur!",
  ui_story_5037_50370501_104_dialog_content = "Sampai jumpa lagi!",
  ui_story_5037_50370501_105_dialog_content = "Konser evaluasi akhirnya selesai, Produser!",
  ui_story_5037_50370501_106_dialog_content = "Anda bekerja sangat keras untuk itu, Goldie.",
  ui_story_5037_50370501_107_dialog_content = "Dan sungguh pertunjukan yang spektakuler... Beranikah saya menyebutnya yang terhebat sepanjang masa?",
  ui_story_5037_50370501_108_dialog_content = "Biar tidak gegabah, PlayerName.",
  ui_story_5037_50370501_109_dialog_content = "Bukankah kita punya satu lagi untuk pergi?",
  ui_story_5037_50370501_110_dialog_content = "BENAR. Pertunjukan terbaik selalu yang berikutnya!",
  ui_story_5037_50370501_111_dialog_content = "Haha, itu garis yang bagus!",
  ui_story_5037_50370501_112_dialog_content = "Apakah Anda sudah memutuskan tema konser terakhir?",
  ui_story_5037_50370501_113_dialog_content = "Oh, benar, saya masih perlu menyempurnakannya.",
  ui_story_5037_50370501_114_dialog_content = "Jangan khawatirkan aku, istirahatlah!",
  ui_story_5037_50370501_115_dialog_content = "Baiklah! Kamu juga melakukan hal yang sama, PlayerName!",
  ui_story_5037_50370501_116_dialog_content = "Marshmallow.",
  ui_story_5037_50370501_117_dialog_content = "Guk!",
  ui_story_5037_50370501_118_dialog_content = "Ada seorang pencuri mencuri barang-barang di konser.",
  ui_story_5037_50370501_119_dialog_content = "Apakah Anda memperhatikan juga?",
  ui_story_5037_50370501_120_dialog_content = "Guk!",
  ui_story_5037_50370501_121_dialog_content = "Aku tidak percaya ada orang yang berani melakukan itu di acaraku...",
  ui_story_5037_50370501_122_dialog_content = "Apakah kamu siap, Marshmallow?",
  ui_story_5037_50370501_123_dialog_content = "Kami akan memberikan keadilan cepat malam ini!",
  ui_story_5037_50370501_124_dialog_content = "Guk!",
  ui_story_5037_50370501_125_dialog_content = "Wawancara teman setelah konser...",
  ui_story_5037_50370501_126_dialog_content = "Tindakan!",
  ui_story_5037_50370501_127_dialog_content = "Dari skala satu sampai sepuluh, bagaimana Anda menilai konser tersebut?",
  ui_story_5037_50370501_128_dialog_content = "Dua belas pasti!",
  ui_story_5037_50370501_129_dialog_content = "Mendekati sepuluh.",
  ui_story_5037_50370501_130_dialog_content = "Pfft, aku tidak percaya pria itu benar-benar bernyanyi dan menari di atas panggung...",
  ui_story_5037_50370501_131_dialog_content = "Tapi saya tidak mau memberikan skor.",
  ui_story_5037_50370501_132_dialog_content = "Mengapa? Karena saya tidak ingin mereka berdua berpikir terlalu tinggi tentang diri mereka sendiri.",
  ui_story_5037_50370501_133_dialog_content = "Bagaimana perasaan Anda tentang konser lawan?",
  ui_story_5037_50370501_134_dialog_content = "Sepuluh!",
  ui_story_5037_50370501_135_dialog_content = "Itu sempurna, tetapi pertunjukan Goldie jelas jauh lebih menarik.",
  ui_story_5037_50370501_136_dialog_content = "Sembilan.",
  ui_story_5037_50370501_137_dialog_content = "Saya tidak menontonnya, tapi mungkin tidak sebagus Fia dan Vic.",
  ui_story_5037_50370501_138_dialog_content = "Apakah ada sesuatu yang ingin Anda katakan kepada teman Anda?",
  ui_story_5037_50370501_139_dialog_content = "Jadilah dirimu sendiri dan dapatkan mereka, PlayerName!",
  ui_story_5037_50370501_140_dialog_content = "Upaya membuahkan hasil.",
  ui_story_5037_50370501_141_dialog_content = "Aku mendengar ada hadiah uang?",
  ui_story_5037_50370501_142_dialog_content = "Kalian lebih baik membawanya pulang!",
  ui_story_5037_50370501_143_dialog_content = "Atau...!",
  ui_story_5037_50370501_144_dialog_content = "Tolong jangan membungkus tentakel di sekitar kamera!",
  ui_story_5037_50370601_1_dialog_content = "Tim Eksklusif PlayerName wawancara konser pra-final...",
  ui_story_5037_50370601_2_dialog_content = "Tindakan!",
  ui_story_5037_50370601_3_dialog_content = "Apa tema yang Anda pilih untuk konser terakhir?",
  ui_story_5037_50370601_4_dialog_content = "Tema kita kali ini adalah \"Pemuda Tak Terkendali\".",
  ui_story_5037_50370601_5_dialog_content = "Oh ngomong - ngomong...",
  ui_story_5037_50370601_6_dialog_content = "Konser ini final dalam nama saja. Goldie tidak akan meninggalkan Starlit Agency.",
  ui_story_5037_50370601_7_dialog_content = "Benar, dari \"Awal Baru\" hingga \"Bunga Tunas\" hingga \"Pemuda Tak Terkendali\"...",
  ui_story_5037_50370601_8_dialog_content = "Ketiga penampilan tersebut dimaksudkan untuk menghadirkan mikrokosmos metamorfosis seorang idola melalui acara reality show.",
  ui_story_5037_50370601_9_dialog_content = "Goldie akan tetap aktif bahkan setelah program selesai.",
  ui_story_5037_50370601_10_dialog_content = "Itu benar. Saya akan memiliki lebih banyak pertunjukan yang akan datang!",
  ui_story_5037_50370601_11_dialog_content = "Meskipun saya mungkin bukan produser Goldie lagi saat itu...",
  ui_story_5037_50370601_12_dialog_content = "...",
  ui_story_5037_50370601_13_dialog_content = "Yah, sangat sulit menjadi produser untuk Starlit Agency.",
  ui_story_5037_50370601_14_dialog_content = "Anda harus mengirimkan resume dan lulus semua jenis tes.",
  ui_story_5037_50370601_15_dialog_content = "Bahkan produser yang luar biasa seperti PlayerName akan memiliki keraguan.",
  ui_story_5037_50370601_16_dialog_content = "Jika bukan karena reality show, saya mungkin akan tersesat di antara talenta di Umbraton.",
  ui_story_5037_50370601_17_dialog_content = "Setelah program selesai, saya rasa saya tidak akan bisa mengalahkan orang lain untuk menjadi produser sungguhan.",
  ui_story_5037_50370601_18_dialog_content = "Tapi saya puas dengan kesempatan untuk melihat Goldie melalui bagian karirnya ini.",
  ui_story_5037_50370601_19_dialog_content = "PlayerName…",
  ui_story_5037_50370601_20_dialog_content = "Terlalu dini untuk mendapatkan semua sentimental!",
  ui_story_5037_50370601_21_dialog_content = "Apakah Anda menulis lagu baru untuk konser ini, Goldie?",
  ui_story_5037_50370601_22_dialog_content = "Tentu saja.",
  ui_story_5037_50370601_23_dialog_content = "Setelah belajar PlayerName memilih \"Pemuda Tak Terkendali\" untuk tema...",
  ui_story_5037_50370601_24_dialog_content = "Saya bertanya pada diri sendiri, \"Apa sebenarnya masa muda itu??\"",
  ui_story_5037_50370601_25_dialog_content = "Segera, gambar memenuhi kepalaku.",
  ui_story_5037_50370601_26_dialog_content = "Apakah itu saling mengejar, tanpa beban, melalui jalanan Umbraton?",
  ui_story_5037_50370601_27_dialog_content = "Apakah itu mendengarkan ceramah di ruang kelas dengan mata mengantuk?",
  ui_story_5037_50370601_28_dialog_content = "Atau apakah pekerjaan Anda berkeringat untuk mencari nafkah?",
  ui_story_5037_50370601_29_dialog_content = "Kemudian saya mengingatkan diri sendiri, masa muda tidak kaku dan kaku.",
  ui_story_5037_50370601_30_dialog_content = "Setiap bentuk masa muda layak untuk dirayakan!",
  ui_story_5037_50370601_31_dialog_content = "Dari gambar-gambar itu, saya menyusun lagu-lagu yang ingin saya bawakan.",
  ui_story_5037_50370601_32_dialog_content = "Bagaimana perasaan Anda tentang lagu baru Goldie kali ini, PlayerName?",
  ui_story_5037_50370601_33_dialog_content = "Oh, Anda tidak akan pernah salah dengan lagu-lagunya!",
  ui_story_5037_50370601_34_dialog_content = "Yang dia tulis untuk \"Unbridled Youth\" sangat menawan.",
  ui_story_5037_50370601_35_dialog_content = "Terutama lagu tentang perpisahan...",
  ui_story_5037_50370601_36_dialog_content = "Lady Sheol sudah mengambilnya untuk lagu tema penutup reality show.",
  ui_story_5037_50370601_37_dialog_content = "Memang benar tidak ada yang abadi dan perpisahan tidak bisa dihindari...",
  ui_story_5037_50370601_38_dialog_content = "tapi saya akan terus bekerja keras, tetap relevan, dan tumbuh bersama semua orang.",
  ui_story_5037_50370601_39_dialog_content = "Jadi perhatikan perkembangan karir saya!",
  ui_story_5037_50370601_40_dialog_content = "Apa pun yang ingin Anda katakan kepada produser Anda, Goldie?",
  ui_story_5037_50370601_41_dialog_content = "Apa? Anda menanyakan itu sebelum konser?",
  ui_story_5037_50370601_42_dialog_content = "Tidak apa-apa.",
  ui_story_5037_50370601_43_dialog_content = "Saya mungkin terlalu tersendat untuk berbicara setelah konser!",
  ui_story_5037_50370601_44_dialog_content = "Hah?",
  ui_story_5037_50370601_45_dialog_content = "Ahem, yang ingin saya katakan kepada produser saya adalah:",
  ui_story_5037_50370601_46_dialog_content = "Terima kasih telah bertahan denganku selama ini.",
  ui_story_5037_50370601_47_dialog_content = "Sejujurnya, saya selalu solo dalam bisnis ini, jadi saya tidak terbiasa memiliki produser.",
  ui_story_5037_50370601_48_dialog_content = "Hanya untuk reality show saya setuju untuk menjadikan Anda sebagai produser saya.",
  ui_story_5037_50370601_49_dialog_content = "Namun sejak saat itu, Anda telah berubah dari pemula total menjadi profesional yang sempurna.",
  ui_story_5037_50370601_50_dialog_content = "Anda tidak hanya menangani jadwal saya tetapi juga menangani paparazzi dan mengatur detail konser ...",
  ui_story_5037_50370601_51_dialog_content = "Kehadiran Anda memungkinkan saya untuk berkreasi dan berlatih dengan mudah.",
  ui_story_5037_50370601_52_dialog_content = "Nyatanya, saya merasa semakin sulit membayangkan melakukan ini tanpa Anda.",
  ui_story_5037_50370601_53_dialog_content = "Mungkin Anda tidak akan pernah menjadi produser lagi, tapi saya masih ingin Anda tahu...",
  ui_story_5037_50370601_54_dialog_content = "Anda adalah produser terbaik bagi saya...",
  ui_story_5037_50370601_55_dialog_content = "... sejauh ini.",
  ui_story_5037_50370601_56_dialog_content = "Tapi saya satu-satunya produser yang pernah Anda miliki.",
  ui_story_5037_50370601_57_dialog_content = "Saya belum selesai. Anda mendapat dukungan saya di masa depan ke mana pun Anda pergi atau apa pun yang Anda lakukan!",
  ui_story_5037_50370601_58_dialog_content = "Saya yakin Anda akan unggul dalam apa pun yang Anda pilih untuk dilakukan.",
  ui_story_5037_50370601_59_dialog_content = "Dan ketika saat itu tiba...",
  ui_story_5037_50370601_60_dialog_content = "saya juga akan...",
  ui_story_5037_50370601_61_dialog_content = "Goldie?",
  ui_story_5037_50370601_62_dialog_content = "*Batuk-batuk*",
  ui_story_5037_50370601_63_dialog_content = "<size=30>Harap edit itu, Lilica, dan biarkan saya memulai dari awal!</size>",
  ui_story_5037_50370601_64_dialog_content = "Anda mendapatkan dukungan saya di masa depan ke mana pun Anda pergi atau apa pun yang Anda lakukan!",
  ui_story_5037_50370601_65_dialog_content = "Saya yakin Anda akan unggul dalam apa pun yang Anda pilih untuk dilakukan.",
  ui_story_5037_50370601_66_dialog_content = "Saat Anda melakukan itu, saya masih akan berjuang di jalan yang saya pilih, membangun di atas dasar yang telah Anda letakkan untuk saya!",
  ui_story_5037_50370601_67_dialog_content = "Adakah yang ingin Anda katakan kepada Goldie, Produser?",
  ui_story_5037_50370601_68_dialog_content = "Saya ingin berterima kasih kepada Goldie juga.",
  ui_story_5037_50370601_69_dialog_content = "Karena dorongan Anda, saya melakukan begitu banyak hal yang tidak berani saya impikan.",
  ui_story_5037_50370601_70_dialog_content = "Kami berhasil sejauh ini hanya karena Anda sudah menjadi bintang yang bersinar!",
  ui_story_5037_50370601_71_dialog_content = "Semua keterampilan yang telah saya pelajari dan kembangkan selama ini...",
  ui_story_5037_50370601_72_dialog_content = "Setiap bit adalah cerminan dari kecemerlangan Goldie!",
  ui_story_5037_50370601_73_dialog_content = "Kamu sendiri juga brilian, PlayerName!",
  ui_story_5037_50370601_74_dialog_content = "Bahkan saat aku tidak lagi di sisimu, Goldie...",
  ui_story_5037_50370601_75_dialog_content = "Kamu akan selalu menjadi bintang yang bersinar.",
  ui_story_5037_50370601_76_dialog_content = "Suatu hari, Anda akan menjadi idola legendaris di Astra!",
  ui_story_5037_50370601_77_dialog_content = "Dan Anda akan selalu memiliki salam dan berkat saya.",
  ui_story_5037_50370601_78_dialog_content = "Tim Eksklusif PlayerName wawancara konser pra-final...",
  ui_story_5037_50370601_79_dialog_content = "adalah bungkus!",
  ui_story_5037_50370601_80_dialog_content = "...",
  ui_story_5037_50370601_81_dialog_content = "...",
  ui_story_5037_50370601_82_dialog_content = "Uh, ada apa dengan kesunyian yang canggung?",
  ui_story_5037_50370601_83_dialog_content = "Haruskah saya tidak menanyakan pertanyaan-pertanyaan itu?",
  ui_story_5037_50370601_84_dialog_content = "Apakah jenis wawancara ini meredam suasana acara?",
  ui_story_5037_50370601_85_dialog_content = "Tolong beritahu saya itu tidak akan memengaruhi kinerja Anda yang akan datang...",
  ui_story_5037_50370601_86_dialog_content = "Tidak apa-apa, Lilica.",
  ui_story_5037_50370601_87_dialog_content = "Lihat, aku baik-baik saja!",
  ui_story_5037_50370601_88_dialog_content = "Luar biasa, itulah senyum Goldie yang kita kenal!",
  ui_story_5037_50370601_89_dialog_content = "Produsen PlayerName!",
  ui_story_5037_50370601_90_dialog_content = "Ya, ini.",
  ui_story_5037_50370601_91_dialog_content = "Trims!",
  ui_story_5037_50370601_92_dialog_content = "Tunggu, apa aku melewatkan sesuatu lagi?",
  ui_story_5037_50370601_93_dialog_content = "Ah!",
  ui_story_5037_50370601_94_dialog_content = "Mint ini benar-benar menenangkan saya.",
  ui_story_5037_50370601_95_dialog_content = "Permisi, ke arah mana ke konser Goldie?",
  ui_story_5037_50370601_96_dialog_content = "Bagaimana seorang penonton bisa berada di belakang panggung?",
  ui_story_5037_50370601_97_dialog_content = "Cukup ikuti bagian ini dan belok kiri!",
  ui_story_5037_50370601_98_dialog_content = "Wow, aku tidak percaya keberuntungan ini! Bukankah ini Goldie sendiri?",
  ui_story_5037_50370601_99_dialog_content = "Ya itu dia! Bisakah kamu menandatangani bajuku, Goldie?!",
  ui_story_5037_50370601_100_dialog_content = "Saya datang jauh-jauh dari Northland!",
  ui_story_5037_50370601_101_dialog_content = "Saya juga penggemar! Saya dari Rediesel Wrench!",
  ui_story_5037_50370601_102_dialog_content = "Saya dari Pulau Awan!",
  ui_story_5037_50370601_103_dialog_content = "Saya dari Euforia!",
  ui_story_5037_50370601_104_dialog_content = "Semuanya, semuanya!",
  ui_story_5037_50370601_105_dialog_content = "Goldie akan meluangkan waktu untuk memberi tanda tangan dan berfoto dengan semua orang setelah pertunjukan.",
  ui_story_5037_50370601_106_dialog_content = "Anda harus menuju ke venue sekarang karena konser akan segera dimulai.",
  ui_story_5037_50370601_107_dialog_content = "Tanda tangan dan gambar setelah pertunjukan?",
  ui_story_5037_50370601_108_dialog_content = "Aku akan pergi ke konser dulu, kalau begitu!",
  ui_story_5037_50370601_109_dialog_content = "Buru-buru! Saya yakin orang yang sampai di sana lebih dulu akan menjadi yang pertama dalam antrean untuk tanda tangan!",
  ui_story_5037_50370601_110_dialog_content = "Tidak perlu terburu-buru. Semua orang akan mendapat kesempatan!",
  ui_story_5037_50370601_111_dialog_content = "Mereka lari begitu cepat, saya tidak berpikir mereka menangkap apa pun yang saya katakan.",
  ui_story_5037_50370601_112_dialog_content = "Ada begitu banyak orang saat ini, dari segala penjuru!",
  ui_story_5037_50370601_113_dialog_content = "Ini pertanda baik untuk tur Astra Goldie di masa depan!",
  ui_story_5037_50370601_114_dialog_content = "Ada apa, Goldie?",
  ui_story_5037_50370601_115_dialog_content = "Aku tiba-tiba sangat gugup.",
  ui_story_5037_50370601_116_dialog_content = "Rasanya seperti aku naik panggung untuk pertama kalinya...",
  ui_story_5037_50370601_117_dialog_content = "Lihatlah penonton di luar sana, Goldie.",
  ui_story_5037_50370601_118_dialog_content = "Mereka datang karena mereka mencintaimu!",
  ui_story_5037_50370601_119_dialog_content = "Dan kamu pantas untuk dicintai.",
  ui_story_5037_50370601_120_dialog_content = "PlayerName…",
  ui_story_5037_50370601_121_dialog_content = "Kau benar!",
  ui_story_5037_50370601_122_dialog_content = "Aku bukanlah aku yang dulu.",
  ui_story_5037_50370601_123_dialog_content = "Anda hanya menonton!",
  ui_story_5037_50370601_124_dialog_content = "aku akan tampil...",
  ui_story_5037_50370601_125_dialog_content = "dengan kemampuan terbaik saya!",
  ui_story_5037_50370701_1_dialog_content = "Konser kelulusan sukses.",
  ui_story_5037_50370701_2_dialog_content = "Pencahayaan dan properti semuanya sempurna, dan penampilan Goldie juga demikian.",
  ui_story_5037_50370701_3_dialog_content = "Kami menyajikan semua yang kami inginkan hingga ke detail yang sempurna.",
  ui_story_5037_50370701_4_dialog_content = "Kerumunan meneriakkan nama Goldie dan bertahan lama.",
  ui_story_5037_50370701_5_dialog_content = "Tidak ada yang lain selain kegembiraan dan kegembiraan di sekitar panggung.",
  ui_story_5037_50370701_6_dialog_content = "Tapi kemudian...",
  ui_story_5037_50370701_7_dialog_content = "kenapa aku tiba-tiba merasa sedih?",
  ui_story_5037_50370701_8_dialog_content = "Oh!",
  ui_story_5037_50370701_9_dialog_content = "Aku hampir lupa, Lady Sheol seharusnya mengumumkan hasil akhirnya sekarang juga!",
  ui_story_5037_50370701_10_dialog_content = "Aku terlambat!",
  ui_story_5037_50370701_11_dialog_content = "Hosh... Hosh...",
  ui_story_5037_50370701_12_dialog_content = "Maaf saya telat!",
  ui_story_5037_50370701_13_dialog_content = "Lebih lama lagi dan saya pikir Anda memutuskan untuk menyerah, Produser PlayerName.",
  ui_story_5037_50370701_14_dialog_content = "Di mana Goldie? Kenapa kamu datang sendiri?",
  ui_story_5037_50370701_15_dialog_content = "Goldie terikat, berbaur dengan para penggemar.",
  ui_story_5037_50370701_16_dialog_content = "Hmph! Tuanku saat ini sedang dikerumuni oleh penggemar yang ingin berfoto juga!",
  ui_story_5037_50370701_17_dialog_content = "Idola kesayanganku benar-benar populer.",
  ui_story_5037_50370701_18_dialog_content = "Bagus. Pertanda yang sangat bagus!",
  ui_story_5037_50370701_19_dialog_content = "Saya ingin menunggu mereka selesai sehingga saya bisa memberi selamat kepada mereka berdua secara langsung.",
  ui_story_5037_50370701_20_dialog_content = "Tapi saya punya janji dengan eksekutif studio film nanti.",
  ui_story_5037_50370701_21_dialog_content = "Sepertinya kamu lebih sibuk dari kami.",
  ui_story_5037_50370701_22_dialog_content = "Tidak apa-apa, beri tahu kami hasilnya, Lady Sheol.",
  ui_story_5037_50370701_23_dialog_content = "Nggak sabar kan, Fia?",
  ui_story_5037_50370701_24_dialog_content = "Tapi itu bukan hal yang buruk. Itu terbukti dari konser Vic...",
  ui_story_5037_50370701_25_dialog_content = "bahwa Anda belajar bagaimana merencanakan pertunjukan dalam waktu yang sangat singkat.",
  ui_story_5037_50370701_26_dialog_content = "Konser kelulusan Vic menunjukkan peningkatan signifikan dalam presentasi.",
  ui_story_5037_50370701_27_dialog_content = "Tentu saja, saya berusaha keras!",
  ui_story_5037_50370701_28_dialog_content = "Adapun Goldie, acaranya sudah hampir tak tertandingi.",
  ui_story_5037_50370701_29_dialog_content = "Tetapi PlayerName tetap berhasil menyisipkan kejutan di atas panggung untuk dinikmati penonton.",
  ui_story_5037_50370701_30_dialog_content = "Ditambah dengan lagu-lagu baru Goldie, itu menyentuh dan mengharukan.",
  ui_story_5037_50370701_31_dialog_content = "Apa? Saya pikir hanya saya yang akan mendapatkan semua pujian.",
  ui_story_5037_50370701_32_dialog_content = "Sekarang untuk hasilnya, Tim Fia—",
  ui_story_5037_50370701_33_dialog_content = "Apa apa apa?",
  ui_story_5037_50370701_34_dialog_content = "Saya menang?!",
  ui_story_5037_50370701_35_dialog_content = "Biarkan aku menyelesaikannya, sayang.",
  ui_story_5037_50370701_36_dialog_content = "Sayangnya, Tim Fia kalah dari Tim PlayerName dengan margin yang sangat tipis.",
  ui_story_5037_50370701_37_dialog_content = "Mereka menang hanya dengan 10 tiket.",
  ui_story_5037_50370701_38_dialog_content = "Hah?",
  ui_story_5037_50370701_39_dialog_content = "Setelah menghitung hasil dari ketiga konser, kemenangan jatuh ke...",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerName dan Goldie!</size>",
  ui_story_5037_50370701_41_dialog_content = "...",
  ui_story_5037_50370701_42_dialog_content = "Waah...!",
  ui_story_5037_50370701_43_dialog_content = "Aku b-bekerja sangat keras...",
  ui_story_5037_50370701_44_dialog_content = "Saya menghabiskan begitu banyak waktu untuk menjaga master saya yang tidak disiplin, tetapi saya juga harus begadang semalaman untuk belajar bagaimana mengadakan konser ...",
  ui_story_5037_50370701_45_dialog_content = "Fia, kamu akan ketinggalan pengumuman selanjutnya kalau kamu tidak tenang.",
  ui_story_5037_50370701_46_dialog_content = "Apa?",
  ui_story_5037_50370701_47_dialog_content = "Fia dan Vic berhasil mengumpulkan banyak penggemar selama periode ini melalui upaya mereka dan berkontribusi pada banyak penjualan merchandise Cloudrover Guild.",
  ui_story_5037_50370701_48_dialog_content = "Mengingat kinerja Anda yang luar biasa ...",
  ui_story_5037_50370701_49_dialog_content = "Anda akan mendapatkan bonus juga!",
  ui_story_5037_50370701_50_dialog_content = "Sebuah bonus...",
  ui_story_5037_50370701_51_dialog_content = "Hadiah uang?!",
  ui_story_5037_50370701_52_dialog_content = "Aku tahu itu. Guru dan saya tidak menderita sia-sia! Kerja keras benar-benar dapat menghasilkan hasil yang baik! *Menangis*",
  ui_story_5037_50370701_53_dialog_content = "Ehem, masih ada lagi!",
  ui_story_5037_50370701_54_dialog_content = "Pemenang Hardest Working Idol di reality show kami adalah...",
  ui_story_5037_50370701_55_dialog_content = "Vic!",
  ui_story_5037_50370701_56_dialog_content = "Menguasai? Guru memenangkan sesuatu?",
  ui_story_5037_50370701_57_dialog_content = "Dan Idola yang Bekerja Paling Keras dari semua hal?",
  ui_story_5037_50370701_58_dialog_content = "Guru mengalahkan Goldie dan menerima dukungan semua orang!",
  ui_story_5037_50370701_59_dialog_content = "Aku sangat bangga dengan tuanku!",
  ui_story_5037_50370701_60_dialog_content = "Hehe, ini juga anggukan untuk Kyllo dan usahaku!",
  ui_story_5037_50370701_61_dialog_content = "Lihat!",
  ui_story_5037_50370701_62_dialog_content = "Maafkan kami, PlayerName, tapi yang ini milik kita!",
  ui_story_5037_50370701_63_dialog_content = "Vic bekerja sangat keras, jadi saya merasa dia pantas mendapatkannya.",
  ui_story_5037_50370701_64_dialog_content = "Selanjutnya, Produser Terbaik jatuh kepada...",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_66_dialog_content = "Apa?",
  ui_story_5037_50370701_67_dialog_content = "Saya, produser terbaik?",
  ui_story_5037_50370701_68_dialog_content = "…!",
  ui_story_5037_50370701_69_dialog_content = "Hmph, baiklah.",
  ui_story_5037_50370701_70_dialog_content = "aku akui PlayerName menguasai keterampilan produser lebih cepat dan lebih baik daripada saya.",
  ui_story_5037_50370701_71_dialog_content = "Tapi dia juga lebih tua dariku!",
  ui_story_5037_50370701_72_dialog_content = "Tunggu sampai aku seusianya. Aku pasti akan lebih hebat!",
  ui_story_5037_50370701_73_dialog_content = "Fi?",
  ui_story_5037_50370701_74_dialog_content = "Dia baru saja pergi seperti itu.",
  ui_story_5037_50370701_75_dialog_content = "Tidak apa-apa, dia kemungkinan akan kembali ke tuannya.",
  ui_story_5037_50370701_76_dialog_content = "Dia mungkin memiliki lidah yang tajam, tetapi hatinya ada di tempat yang tepat.",
  ui_story_5037_50370701_77_dialog_content = "Bagaimana Anda memiliki wawasan seperti itu tentang Fia?",
  ui_story_5037_50370701_78_dialog_content = "Meskipun aku bukan Caelestite dan tidak memiliki kemampuan psikis...",
  ui_story_5037_50370701_79_dialog_content = "Aku lebih tanggap terhadap orang daripada kamu.",
  ui_story_5037_50370701_80_dialog_content = "Menurut Anda, bagaimana lagi saya memulai dari awal dan membangun Cloudrover Guild hingga seperti sekarang?",
  ui_story_5037_50370701_81_dialog_content = "...",
  ui_story_5037_50370701_82_dialog_content = "Lilik.",
  ui_story_5037_50370701_83_dialog_content = "Aku di sini, Nona Sheol!",
  ui_story_5037_50370701_84_dialog_content = "Saya suka semua rekaman B-roll yang Anda ambil untuk pertunjukan itu.",
  ui_story_5037_50370701_85_dialog_content = "Dengan editing yang tepat, itu akan menjadi reality show yang berkualitas.",
  ui_story_5037_50370701_86_dialog_content = "Saat itu, banyak peluang penyutradaraan baru akan menunggu Anda.",
  ui_story_5037_50370701_87_dialog_content = "Saya pasti akan mengedit acara terbaik yang pernah ada!",
  ui_story_5037_50370701_88_dialog_content = "Dan jangan ragu untuk meminta apa pun dari saya di masa depan, Lady Sheol!",
  ui_story_5037_50370701_89_dialog_content = "Tentu. Saya berharap cerita menarik juga muncul setelah konser.",
  ui_story_5037_50370701_90_dialog_content = "Awasi mereka agar Anda tidak melewatkan apa pun.",
  ui_story_5037_50370701_91_dialog_content = "Oke!",
  ui_story_5037_50370701_92_dialog_content = "Bisa!",
  ui_story_5037_50370701_93_dialog_content = "Anda dipersilakan untuk tinggal dan menjadi produser, PlayerName.",
  ui_story_5037_50370701_94_dialog_content = "Ingatlah untuk mengirimkan resume Anda ke kantor saya.",
  ui_story_5037_50370701_95_dialog_content = "Oke!",
  ui_story_5037_50370701_96_dialog_content = "Dan aku kehabisan waktu. Saya harus berurusan dengan masalah bisnis sekarang.",
  ui_story_5037_50370701_97_dialog_content = "Nantikan kabar baik dari kalian semua!",
  ui_story_5037_50370701_98_dialog_content = "Sampai jumpa, Nona Sheol!",
  ui_story_5037_50370701_99_dialog_content = "Hmm, apakah ini akhir dari karir produser saya?",
  ui_story_5037_50370701_100_dialog_content = "...",
  ui_story_5037_50370701_101_dialog_content = "Apa... Apa yang kau lakukan dengan kamera di wajahku, Lilica?",
  ui_story_5037_50370701_102_dialog_content = "Pertunjukan realitas belum berakhir.",
  ui_story_5037_50370701_103_dialog_content = "Saya harus tetap bekerja.",
  ui_story_5037_50370701_104_dialog_content = "Tapi konsernya sudah selesai, dan tidak ada lagi yang bisa dilakukan...",
  ui_story_5037_50370701_105_dialog_content = "Apa lagi yang bisa Anda filmkan?",
  ui_story_5037_50370701_106_dialog_content = "Anda, tentu saja.",
  ui_story_5037_50370701_107_dialog_content = "Produser Terbaik!",
  ui_story_5037_50370701_108_dialog_content = "Eh, apakah ada sesuatu yang harus saya lakukan?",
  ui_story_5037_50370701_109_dialog_content = "Bertanya pada diri sendiri.",
  ui_story_5037_50370701_110_dialog_content = "Tanyakan pada diriku sendiri?",
  ui_story_5037_50370701_111_dialog_content = "Ya, misalnya... siapa yang paling ingin kamu temui saat ini?",
  ui_story_5037_50370701_112_dialog_content = "Siapa yang ingin saya lihat?",
  ui_story_5037_50370701_113_dialog_content = "Benar, hari ini belum berakhir!",
  ui_story_5037_50370701_114_dialog_content = "aku ingin pergi melihat...",
  ui_story_5037_50370701_115_option_content = "Goldie",
  ui_story_5037_50370701_116_dialog_content = "Aku harus memberitahunya bahwa kita menang!",
  ui_story_5037_50370701_117_option_content = "Vic dan Fia",
  ui_story_5037_50370701_118_dialog_content = "Aku harus pergi memberi selamat Vic!",
  ui_story_5037_50370701_119_option_content = "Wakil dan Carleen",
  ui_story_5037_50370701_120_dialog_content = "Saya ingin berterima kasih kepada mereka berdua...",
  ui_story_5037_50370701_121_dialog_content = "Saya ingin memberi tahu Goldie bahwa kami menang secepat mungkin!",
  ui_story_5037_50370701_122_dialog_content = "Lalu aku akan memberitahunya apa yang ingin kukatakan padanya...",
  ui_story_5037_50370701_123_dialog_content = "Tunggu!",
  ui_story_5037_50370701_124_dialog_content = "Tapi aku sudah mengatakan hal-hal itu!",
  ui_story_5037_50370701_125_dialog_content = "Saya kira saya harus berbicara tentang hadiah uang?",
  ui_story_5037_50370701_126_dialog_content = "\"Goldie, dengan uang ini, kamu akan bisa membeli lebih banyak gaun!\"",
  ui_story_5037_50370701_127_dialog_content = "Kedengarannya canggung...",
  ui_story_5037_50370701_128_dialog_content = "\"Kami memenangkan uang semua berkat Anda, Goldie!\"",
  ui_story_5037_50370701_129_dialog_content = "Tidak, itu membuatku terdengar seperti sedang menjilatnya.",
  ui_story_5037_50370701_130_dialog_content = "\"Kerja bagus, Goldie!\"",
  ui_story_5037_50370701_131_dialog_content = "Kedengarannya seperti pernyataan yang terlalu meremehkan...",
  ui_story_5037_50370701_132_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370701_133_dialog_content = "Terima kasih atas dukungan kalian semua!",
  ui_story_5037_50370701_134_dialog_content = "Tolong berbaris satu per satu, jangan tersandung!",
  ui_story_5037_50370701_135_dialog_content = "Konsernya sudah lama berakhir, tapi dia masih punya begitu banyak penggemar yang berdengung di sekitarnya!",
  ui_story_5037_50370701_136_dialog_content = "Dia tampaknya bersenang-senang dengan mereka.",
  ui_story_5037_50370701_137_dialog_content = "Aku seharusnya tidak menerobos masuk.",
  ui_story_5037_50370701_138_dialog_content = "Saya dapat menggunakan waktu ini untuk mencari tahu apa yang akan saya katakan padanya nanti!",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_140_dialog_content = "Apakah itu Goldie yang memanggilku?",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName, cepat kemari!</size>",
  ui_story_5037_50370701_142_dialog_content = "Apakah dia ingin aku berbicara dengan para penggemar juga?",
  ui_story_5037_50370701_143_dialog_content = "Saya tidak berpikir saya harus pergi. Mereka semua adalah penggemarnya dan tidak akan tertarik padaku.",
  ui_story_5037_50370701_144_dialog_content = "Tolong beri saya waktu sebentar, saya akan segera kembali!",
  ui_story_5037_50370701_145_dialog_content = "Ke mana pun Goldie pergi, Goldilocks mengikuti!",
  ui_story_5037_50370701_146_dialog_content = "Tunggu...",
  ui_story_5037_50370701_147_dialog_content = "Kenapa dia datang dengan cara ini?",
  ui_story_5037_50370701_148_dialog_content = "Apa yang kamu lakukan hanya berdiri di sini, Produser?",
  ui_story_5037_50370701_149_dialog_content = "Oh, aku hanya datang untuk memberitahumu...",
  ui_story_5037_50370701_150_dialog_content = "Kita menang!",
  ui_story_5037_50370701_151_dialog_content = "Sudah waktunya Anda tahu, PlayerName.",
  ui_story_5037_50370701_152_dialog_content = "Anda sudah tahu?",
  ui_story_5037_50370701_153_dialog_content = "Yeah, tepat setelah aku menyelesaikan lagu terakhir.",
  ui_story_5037_50370701_154_dialog_content = "Kami melakukan yang terbaik di setiap penampilan dan tidak meninggalkan penyesalan di atas panggung.",
  ui_story_5037_50370701_155_dialog_content = "Kita sudah menang ketika kita menaklukkan diri kita sendiri.",
  ui_story_5037_50370701_156_dialog_content = "Jadi begitulah cara Anda melihat ini.",
  ui_story_5037_50370701_157_dialog_content = "Banyak penggemar yang memuji desain panggung. Mengapa Anda tidak bergaul dengan mereka?",
  ui_story_5037_50370701_158_dialog_content = "Anu, aku...",
  ui_story_5037_50370701_159_dialog_content = "Tidak sopan bagi idola atau produser idola untuk membuat penggemar menunggu!",
  ui_story_5037_50370701_160_dialog_content = "Maaf membuat Anda menunggu, Goldilocks tersayang!",
  ui_story_5037_50370701_161_dialog_content = "Saya ingin memperkenalkan seseorang kepada Anda semua.",
  ui_story_5037_50370701_162_dialog_content = "Drum roll, tolong!",
  ui_story_5037_50370701_163_dialog_content = "H-Hai, semuanya!",
  ui_story_5037_50370701_164_dialog_content = "Itu benar, orang pemalu di sebelahku adalah Caelestite yang legendaris, PlayerName!",
  ui_story_5037_50370701_165_dialog_content = "Juga, PlayerName adalah produser yang telah membantuku selama ini!",
  ui_story_5037_50370701_166_dialog_content = "Pertunjukannya berjalan sangat baik berkat dia!",
  ui_story_5037_50370701_167_dialog_content = "Aku tersanjung. Sebenarnya, saya sangat baru dalam peran itu.",
  ui_story_5037_50370701_168_dialog_content = "Produser Goldie adalah noob? Saya tidak akan menduga.",
  ui_story_5037_50370701_169_dialog_content = "Anda tahu apa yang mereka katakan, jangan pernah menilai buku dari sampulnya!",
  ui_story_5037_50370701_170_dialog_content = "Saya akan menyebut diri saya seorang diehard Goldie penggemar yang sudah ada sejak hari pertama.",
  ui_story_5037_50370701_171_dialog_content = "Goldie sudah luar biasa dalam setiap aspek, tapi mendapatkan seorang produser...",
  ui_story_5037_50370701_172_dialog_content = "benar-benar membantunya berkembang pesat dan membantunya menemukan gayanya sendiri!",
  ui_story_5037_50370701_173_dialog_content = "Saya tidak mengerti semua jargon itu.",
  ui_story_5037_50370701_174_dialog_content = "Yang saya tahu adalah saya belum pernah ke pertunjukan yang begitu menyenangkan dan menyenangkan!",
  ui_story_5037_50370701_175_dialog_content = "Ini semua berkat Produser PlayerName!",
  ui_story_5037_50370701_176_dialog_content = "Produsen PlayerName! Produsen PlayerName! Produsen PlayerName!",
  ui_story_5037_50370701_177_dialog_content = "...",
  ui_story_5037_50370701_178_dialog_content = "(Agak memalukan mendengar begitu banyak orang memanggil namaku...)",
  ui_story_5037_50370701_179_dialog_content = "(Yang saya lakukan hanyalah beberapa hal di belakang panggung. Apakah itu membutuhkan sorakan?)",
  ui_story_5037_50370701_180_dialog_content = "Produsen PlayerName...",
  ui_story_5037_50370701_181_dialog_content = "Tentu saja Anda pantas mendapatkan sorak-sorai.",
  ui_story_5037_50370701_182_dialog_content = "Anda telah bekerja sangat keras akhir-akhir ini!",
  ui_story_5037_50370701_183_dialog_content = "(Bagaimana Goldie tahu apa yang saya pikirkan?)",
  ui_story_5037_50370701_184_dialog_content = "(Dan dia bahkan mencuri dialogku!)",
  ui_story_5037_50370701_185_dialog_content = "Saya pikir semua orang ingin berbicara dengan Anda, PlayerName!",
  ui_story_5037_50370701_186_dialog_content = "Hah?",
  ui_story_5037_50370701_187_dialog_content = "Tanda tangan, tolong, Produser!",
  ui_story_5037_50370701_188_dialog_content = "Saya bukan Lovegator, tapi saya juga ingin tanda tangan PlayerName!",
  ui_story_5037_50370701_189_dialog_content = "Iya, aku juga!",
  ui_story_5037_50370701_190_dialog_content = "Dan saya!",
  ui_story_5037_50370701_191_dialog_content = "Apa yang sedang terjadi...?!",
  ui_story_5037_50370701_192_dialog_content = "Saya akan melatih tanda tangan saya jika saya tahu ini akan terjadi...",
  ui_story_5037_50370701_193_dialog_content = "Wow!",
  ui_story_5037_50370701_194_dialog_content = "Saya tidak pernah menghitung begitu banyak Nightium sebelumnya!",
  ui_story_5037_50370701_195_dialog_content = "Jadi begini rasanya menjadi kaya?",
  ui_story_5037_50370701_196_dialog_content = "Lady Sheol terlalu murah hati!",
  ui_story_5037_50370701_197_dialog_content = "Dengan siapa kamu berbicara, Fia?",
  ui_story_5037_50370701_198_dialog_content = "Saya tidak melihat orang lain di sekitar.",
  ui_story_5037_50370701_199_dialog_content = "Siapa lagi yang bisa saya ajak bicara selain tuan saya?",
  ui_story_5037_50370701_200_dialog_content = "tuanmu?",
  ui_story_5037_50370701_201_dialog_content = "Apa... Aku bahkan tidak akan menyadarinya jika kamu tidak membesarkannya...",
  ui_story_5037_50370701_202_dialog_content = "Tuanku yang pemalas itu tertidur di bawah meja lagi!",
  ui_story_5037_50370701_203_dialog_content = "Seret Guru keluar sekarang, Kyllo!",
  ui_story_5037_50370701_204_dialog_content = "Lihat!",
  ui_story_5037_50370701_205_dialog_content = "Hah?",
  ui_story_5037_50370701_206_dialog_content = "Ngomong-ngomong, dari mana asalmu, PlayerName?",
  ui_story_5037_50370701_207_dialog_content = "Yah, pintunya terbuka, jadi aku masuk.",
  ui_story_5037_50370701_208_dialog_content = "Apa?! Bagaimana saya bisa lupa menutup pintu sebelum menghitung uang?!",
  ui_story_5037_50370701_209_dialog_content = "I-Tidak apa-apa, Fia. Aku menutupnya untukmu.",
  ui_story_5037_50370701_210_dialog_content = "Tetapi bagaimana jika seorang pencuri menyelinap masuk ?!",
  ui_story_5037_50370701_211_dialog_content = "Ugh, tidak, saya harus menghitung semua Nightium lagi!",
  ui_story_5037_50370701_212_dialog_content = "Lo-lo!",
  ui_story_5037_50370701_213_dialog_content = "Nnng... Tidak ada lagi pelatihan, kumohon...",
  ui_story_5037_50370701_214_dialog_content = "Vic?",
  ui_story_5037_50370701_215_dialog_content = "Ayo lari, Bola Bulu Kecil! Ruuuun!",
  ui_story_5037_50370701_216_dialog_content = "Apakah dia ... berbicara dalam tidurnya?",
  ui_story_5037_50370701_217_dialog_content = "Delapan puluh tiga, delapan puluh empat, delapan puluh lima ...",
  ui_story_5037_50370701_218_dialog_content = "Fia, tidak akan lebih, tidak peduli berapa kali Anda menghitungnya.",
  ui_story_5037_50370701_219_dialog_content = "Selain itu, bukankah menurutmu kamu harus memeriksa tuanmu? Lihat saja dia.",
  ui_story_5037_50370701_220_dialog_content = "Kyllo menyeretnya keluar dari bawah meja, tapi dia masih belum bangun!",
  ui_story_5037_50370701_221_dialog_content = "Sebentar! Aku akan menghubungimu setelah aku menghitung sampai seratus...",
  ui_story_5037_50370701_222_dialog_content = "Sembilan puluh delapan, sembilan puluh sembilan... Seratus!",
  ui_story_5037_50370701_223_dialog_content = "Baiklah, sekarang, apa yang baru saja kamu katakan?",
  ui_story_5037_50370701_224_dialog_content = "Uh, mungkin kau harus memeriksa tuanmu.",
  ui_story_5037_50370701_225_dialog_content = "Dia benar-benar tidak responsif.",
  ui_story_5037_50370701_226_dialog_content = "Oh, dia hanya tidur siang, itu saja.",
  ui_story_5037_50370701_227_dialog_content = "Beberapa hari terakhir ini benar-benar telah melakukan beberapa hal padanya...",
  ui_story_5037_50370701_228_dialog_content = "Meskipun saya kira itu cukup normal untuk seseorang yang tidak pernah bekerja sehari pun dalam hidup mereka!",
  ui_story_5037_50370701_229_dialog_content = "Ruuuuuuuuun!!!",
  ui_story_5037_50370701_230_dialog_content = "Hei, Vik? Apakah kamu sudah bangun sekarang?",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? Apa yang kamu lakukan di sini?!",
  ui_story_5037_50370701_232_dialog_content = "L-Lari! Kyllo menjadi gila! Itu terus memaksa saya untuk berlatih!",
  ui_story_5037_50370701_233_dialog_content = "Uh, apa kau yakin kau tidak hanya bermimpi?",
  ui_story_5037_50370701_234_dialog_content = "Hah? Eh, Fia juga ada di sini...?",
  ui_story_5037_50370701_235_dialog_content = "Tunggu, dari mana semua Nightium itu berasal?!",
  ui_story_5037_50370701_236_dialog_content = "Aku benar-benar bermimpi sekarang!",
  ui_story_5037_50370701_237_dialog_content = "Meski harus kukatakan, mimpi ini terasa jauh lebih menyenangkan daripada yang terakhir.",
  ui_story_5037_50370701_238_dialog_content = "Eh, Fia? Bagaimana kita meyakinkan Vic bahwa dia tidak bermimpi?",
  ui_story_5037_50370701_239_dialog_content = "Heheheh. Sepertinya sudah waktunya Kyllo untuk bersinar lagi! Dapatkan dia!",
  ui_story_5037_50370701_240_dialog_content = "!!!",
  ui_story_5037_50370701_241_dialog_content = "T-Tunggu sebentar, Fia! Tuanmu sudah bangun sekarang, sumpah!",
  ui_story_5037_50370701_242_dialog_content = "Vic yang malang. Bayangkan menjadi takut pada Kyllo.",
  ui_story_5037_50370701_243_dialog_content = "Hmm, sepertinya Nightium ini asli.",
  ui_story_5037_50370701_244_dialog_content = "Lady Sheol benar-benar orang yang murah hati, ya?",
  ui_story_5037_50370701_245_dialog_content = "Yang kami lakukan hanyalah berpartisipasi dalam reality show-nya selama beberapa hari, dan dia membayar kami Nightium sebanyak ini sebagai imbalan...",
  ui_story_5037_50370701_246_dialog_content = "Aku bertanya-tanya berapa banyak yang dihasilkan oleh idola sejati?",
  ui_story_5037_50370701_247_dialog_content = "Kenapa kamu peduli berapa penghasilan orang lain, Fia? Kita harus puas dengan apa yang sudah kita miliki, bukan begitu?",
  ui_story_5037_50370701_248_dialog_content = "Sigh ... Saya kira Anda benar.",
  ui_story_5037_50370701_249_dialog_content = "Jarang sekali Anda mendengar Anda mengatakan sesuatu yang serius...",
  ui_story_5037_50370701_250_dialog_content = "Omong kosong, aku selalu seperti ini! Sekarang, permisi, ada meja di prasmanan Umbraton baru dengan nama saya di atasnya!",
  ui_story_5037_50370701_251_dialog_content = "... Dalam mimpimu!",
  ui_story_5037_50370701_252_dialog_content = "Apa? Kenapa tidak?!",
  ui_story_5037_50370701_253_dialog_content = "Selama beberapa hari terakhir, saya tidak melakukan apa-apa selain mendengarkan permintaan konyol Anda!",
  ui_story_5037_50370701_254_dialog_content = "Jika saya tidak berlatih, saya memperhatikan berat badan saya. Aku bahkan tidak ingat kapan terakhir kali aku makan enak!",
  ui_story_5037_50370701_255_dialog_content = "Kami tidak mendapatkan uang sebanyak ini setiap hari, Anda tahu? Kita harus memperlakukan diri kita sendiri ketika kita memiliki kesempatan!",
  ui_story_5037_50370701_256_dialog_content = "Sepertinya Anda masih belum memahami situasi kami dengan baik, Guru.",
  ui_story_5037_50370701_257_dialog_content = "Ini mungkin terlihat seperti banyak uang pada pandangan pertama.",
  ui_story_5037_50370701_258_dialog_content = "Tapi begitu Anda memperhitungkan camilan drakolion Anda, pengeluaran makanan biasa kami, perbaikan rumah, dan upah kerja saya...",
  ui_story_5037_50370701_259_dialog_content = "Itu menghabiskan lebih dari setengah uang!",
  ui_story_5037_50370701_260_dialog_content = "Dan ketika kami mempertimbangkan betapa tidak dapat diandalkannya Anda sebagai sumber pendapatan...",
  ui_story_5037_50370701_261_dialog_content = "Aku tidak tahu berapa lama uang ini akan bertahan untuk kita!",
  ui_story_5037_50370701_262_dialog_content = "Tunggu, apa maksudmu tentang penghasilannya?",
  ui_story_5037_50370701_263_dialog_content = "Vic memiliki begitu banyak potensi sebagai idola! Kenapa dia tidak terus melakukannya?",
  ui_story_5037_50370701_264_dialog_content = "Ampuni aku, PlayerName.",
  ui_story_5037_50370701_265_dialog_content = "Bagi saya untuk bertahan selama beberapa hari ini adalah keajaiban, dan Anda ingin saya melakukannya selama sisa hidup saya?",
  ui_story_5037_50370701_266_dialog_content = "Memikirkannya saja membuatku mimpi buruk.",
  ui_story_5037_50370701_267_dialog_content = "PlayerName benar sekali, Guru!",
  ui_story_5037_50370701_268_dialog_content = "Anda menghabiskan seluruh waktu Anda di rumah alih-alih mencari pekerjaan, dan Anda bahkan tidak merawat binatang buas yang menakjubkan ...",
  ui_story_5037_50370701_269_dialog_content = "Anda mungkin juga memanfaatkan diri Anda sebagai idola.",
  ui_story_5037_50370701_270_dialog_content = "Dan siapa yang tahu? Setelah reality show ditayangkan, Anda mungkin memiliki lebih banyak penggemar daripada sebelumnya, Guru!",
  ui_story_5037_50370701_271_dialog_content = "Oh, sayangku, Fia kecil...",
  ui_story_5037_50370701_272_dialog_content = "Potong tuanmu sedikit kendur, ya ?!",
  ui_story_5037_50370701_273_dialog_content = "Tidak! Anda akan menjadi idola yang besar dan sukses, dan Anda akan menyukainya!",
  ui_story_5037_50370701_274_dialog_content = "Apa-?!",
  ui_story_5037_50370701_275_dialog_content = "Oh, lihat, kita masih punya cukup waktu untuk mengikuti beberapa pelatihan lagi! Ayo pergi, Guru!",
  ui_story_5037_50370701_276_dialog_content = "T-Tapi aku tidak ingin terus berlatih... Aku benar-benar kelelahan...",
  ui_story_5037_50370701_277_dialog_content = "Oh, Kylo? Saya pikir tuan kita membutuhkan sedikit motivasi.",
  ui_story_5037_50370701_278_dialog_content = "Tidaaaak—!",
  ui_story_5037_50370701_279_dialog_content = "Sigh ... Saya belum pernah melihat Guru berlari begitu cepat dalam hidup saya.",
  ui_story_5037_50370701_280_dialog_content = "Begitu banyak untuk menjadi \"benar-benar kelelahan,\" ya? Hai! Jika Anda memiliki cukup energi untuk melarikan diri, maka Anda masih memiliki cukup energi untuk berlatih!",
  ui_story_5037_50370701_281_dialog_content = "Vik...",
  ui_story_5037_50370701_282_dialog_content = "Tetap bertahan!",
  ui_story_5037_50370701_283_dialog_content = "\"Produser Terbaik,\" eh...?",
  ui_story_5037_50370701_284_dialog_content = "Heehee... Aku tahu aku seharusnya tidak membiarkan penghargaan Lady Sheol masuk ke kepalaku.",
  ui_story_5037_50370701_285_dialog_content = "Memikirkan kembali hari saya pertama kali tiba di Starlit Agency, saya benar-benar tidak tahu apa yang saya lakukan. Saya khawatir membuat hidup Goldie lebih sulit dari sebelumnya.",
  ui_story_5037_50370701_286_dialog_content = "Tapi saya berhasil membantu Goldie dengan ketiga konsernya dan bahkan membuat Lady Sheol mengakui saya!",
  ui_story_5037_50370701_287_dialog_content = "Sobat, aku tidak sabar untuk mengejutkan Vice dan Carleen dengan ini.",
  ui_story_5037_50370701_288_dialog_content = "Mereka seharusnya berada di suatu tempat di dekatnya, bukan?",
  ui_story_5037_50370701_289_dialog_content = "Aku ingin tahu apakah mereka ada di ruangan ini?",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>Ketuk, ketuk!</color>",
  ui_story_5037_50370701_291_dialog_content = "Maafkan intrusi!",
  ui_story_5037_50370701_292_dialog_content = "Lucu... Lampu di ruangan ini biasanya menyala. Mengapa begitu gelap di sini hari ini?",
  ui_story_5037_50370701_293_dialog_content = "Keburukan? Carleen? Huh, sepertinya mereka tidak ada di sini.",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5037_50370701_295_dialog_content = "Hah?!",
  ui_story_5037_50370701_296_dialog_content = "Kejutan!!!",
  ui_story_5037_50370701_297_dialog_content = "Selamat telah menyelenggarakan konser kelulusan yang sempurna!",
  ui_story_5037_50370701_298_dialog_content = "Dan selamat telah menyelesaikan misi Anda, PlayerName.",
  ui_story_5037_50370701_299_dialog_content = "A-Apa semua ini...?",
  ui_story_5037_50370701_300_dialog_content = "Pilihan makanan dan minuman terbaik dari prasmanan baru kelas atas yang baru saja dibuka di Umbraton.",
  ui_story_5037_50370701_301_dialog_content = "Dan juga—kue yang sangat besar ini! Terlihat enak, ya?",
  ui_story_5037_50370701_302_dialog_content = "Sejak Anda mulai pelatihan untuk menjadi produser, Anda belum makan dengan baik.",
  ui_story_5037_50370701_303_dialog_content = "Soooo... Kami memutuskan untuk mengadakan pesta perayaan kecil hanya untukmu, PlayerName! Melihat? Ia memiliki semua favorit Anda!",
  ui_story_5037_50370701_304_dialog_content = "Wakil, Carleen...",
  ui_story_5037_50370701_305_dialog_content = "Sudah berapa lama kalian berdua merencanakan ini?",
  ui_story_5037_50370701_306_dialog_content = "Saya tidak tahu sama sekali!",
  ui_story_5037_50370701_307_dialog_content = "Heehee! Kami datang dengan ide itu beberapa waktu lalu, sebenarnya.",
  ui_story_5037_50370701_308_dialog_content = "Dan dengan betapa sibuknya Anda hari ini, kami punya banyak waktu untuk bersiap.",
  ui_story_5037_50370701_309_dialog_content = "Apakah itu berarti kalian berdua tahu hasil konser hari ini?",
  ui_story_5037_50370701_310_dialog_content = "Tidak! Kami berharap Anda akan memberi tahu kami.",
  ui_story_5037_50370701_311_dialog_content = "Er... Apa yang akan kamu lakukan jika kita kalah? Apakah kita masih punya alasan untuk merayakannya?",
  ui_story_5037_50370701_312_dialog_content = "Vice dan saya sudah setuju bahwa apapun hasilnya hari ini,",
  ui_story_5037_50370701_313_dialog_content = "semua kerja keras Anda adalah alasan yang cukup untuk dirayakan.",
  ui_story_5037_50370701_314_dialog_content = "Anda tidak hanya mempelajari hati Anda, PlayerName. Anda terjebak dengan itu sampai akhir! Itu pencapaian besar di mata saya!",
  ui_story_5037_50370701_315_dialog_content = "Itu sebabnya kita akan berpesta apapun yang terjadi!",
  ui_story_5037_50370701_316_dialog_content = "K-Kalian... Arrrgh, kenapa harus begitu baik?!",
  ui_story_5037_50370701_317_dialog_content = "Melihat? Sekarang saya memiliki sesuatu di mata saya, terima kasih!",
  ui_story_5037_50370701_318_dialog_content = "Jadi ngomong-ngomong, siapa yang menang hari ini?",
  ui_story_5037_50370701_319_dialog_content = "Saya pikir Anda mengatakan itu tidak masalah ?!",
  ui_story_5037_50370701_320_dialog_content = "Ha ha ha! Itu karena kami mempercayai Anda, PlayerName!",
  ui_story_5037_50370701_321_dialog_content = "Selain itu, Anda menggumamkan sesuatu tentang sesuatu yang ingin Anda sampaikan kepada kami saat Anda berada di luar. Jadi apa itu?",
  ui_story_5037_50370701_322_dialog_content = "Heheheh. Tebak apa? Goldie dan saya menang hari ini!",
  ui_story_5037_50370701_323_dialog_content = "Dan tidak hanya itu, Lady Sheol memberi saya penghargaan Produser Terbaik!",
  ui_story_5037_50370701_324_dialog_content = "Wow! Saya tidak tahu mereka bahkan mendapat penghargaan untuk itu!",
  ui_story_5037_50370701_325_dialog_content = "Tampaknya Lady Sheol memiliki mata yang tajam. Saya tidak berpikir kemajuan luar biasa Anda hilang sama sekali, PlayerName.",
  ui_story_5037_50370701_326_dialog_content = "Jadi apakah penghargaan itu datang dengan hadiah uang? Hah? Hah?!",
  ui_story_5037_50370701_327_dialog_content = "Aku, uh... Kurasa tidak.",
  ui_story_5037_50370701_328_dialog_content = "Hehehe, itu masuk akal. Lagi pula, tidak ada jumlah uang yang bisa dibandingkan dengan kehormatan mendapatkan penghargaan itu, bukan?",
  ui_story_5037_50370701_329_dialog_content = "Sepakat. Anda akan lebih mudah mencari pekerjaan di masa depan dengannya.",
  ui_story_5037_50370701_330_dialog_content = "Itu benar! Anda pada dasarnya berada di level yang sama dengan produser profesional lainnya sekarang!",
  ui_story_5037_50370701_331_dialog_content = "Tapi jika bukan karena kalian membantu saya sepanjang waktu, saya tidak akan pernah memiliki kepercayaan diri untuk sampai sejauh ini.",
  ui_story_5037_50370701_332_dialog_content = "Carleen, Vice, terima kasih karena selalu berada di sisiku dan mengajariku banyak hal beberapa hari terakhir ini.",
  ui_story_5037_50370701_333_dialog_content = "Jangan sebutkan itu! Hanya ada satu hal kecil yang salah dengan pernyataan Anda.",
  ui_story_5037_50370701_334_dialog_content = "Hah?",
  ui_story_5037_50370701_335_dialog_content = "Kami tidak hanya membantu Anda selama beberapa hari terakhir, kan?",
  ui_story_5037_50370701_336_dialog_content = "Dia benar. Kita sudah bersama selama ini, bukan?",
  ui_story_5037_50370701_337_dialog_content = "Ya, kau benar.",
  ui_story_5037_50370701_338_dialog_content = "Biarkan saya mencoba lagi!",
  ui_story_5037_50370701_339_dialog_content = "Oh, santai saja, ya? Kita semua berteman di sini, jadi tidak perlu terlalu formal!",
  ui_story_5037_50370701_340_dialog_content = "Lagi pula, coba tebak?",
  ui_story_5037_50370701_341_dialog_content = "Pada perjalanan terakhir saya kembali ke Illumina, saya perhatikan bahwa seluruh wilayah telah menjadi idola!",
  ui_story_5037_50370701_342_dialog_content = "Saya pikir Petugas Vivian bahkan merencanakan semacam acara besar untuk memilih sekelompok idola untuk mewakili seluruh Federasi Illumina!",
  ui_story_5037_50370701_343_dialog_content = "Apa? Idola Illumina?!",
  ui_story_5037_50370701_344_dialog_content = "Mari kita bergemuruh dan memeriahkan acara!",
  ui_story_5037_50370701_345_dialog_content = "Hmm? Ada apa dengan kerumunan yang sangat sunyi itu?",
  ui_story_5037_50370701_346_dialog_content = "Apakah Anda semua begitu tercengang dengan penampilan spektakuler saya sehingga Anda lupa bertepuk tangan?",
  ui_story_5037_50370701_347_dialog_content = "Hahahaha hahahaha!",
  ui_story_5037_50370701_348_dialog_content = "*Menghirup*",
  ui_story_5037_50370701_349_dialog_content = "Hmm? Apakah ada yang salah, PlayerName? Anda terlihat sedikit pucat.",
  ui_story_5037_50370701_350_dialog_content = "I-itu bukan apa-apa!",
  ui_story_5037_50370701_351_dialog_content = "Saya yakin pencarian top idol Illumina akan menjadi pengalaman yang tak terlupakan!",
  ui_story_5037_50370701_352_dialog_content = "Kontes idola ini memang layak dipertimbangkan secara serius. Mungkin saya harus menyarankan acara serupa untuk Lumopolis kepada ayah saya?",
  ui_story_5037_50370701_353_dialog_content = "Er, apakah menurutmu para bangsawan Lumopolis akan menyetujui hal semacam ini?",
  ui_story_5037_50370701_354_dialog_content = "Saya menduga itu tidak akan mudah.",
  ui_story_5037_50370701_355_dialog_content = "Namun tidak dipungkiri kekayaan ilmu yang saya peroleh dari pengalaman ini.",
  ui_story_5037_50370701_356_dialog_content = "Nyatanya, saya percaya akhirnya saya melihat nilai sebenarnya dari menampilkan pesona seseorang untuk dilihat dunia.",
  ui_story_5037_50370701_357_dialog_content = "Anehnya, rasanya seolah-olah ada beban yang tiba-tiba terangkat dari pundak saya.",
  ui_story_5037_50370701_358_dialog_content = "Oh, aku mengerti!",
  ui_story_5037_50370701_359_dialog_content = "Saya pikir Anda sudah selangkah lebih dekat dalam perjalanan Anda untuk menggantikan ayah Anda, Carleen!",
  ui_story_5037_50370701_360_dialog_content = "Anda benar-benar berpikir ini ada hubungannya dengan itu?",
  ui_story_5037_50370701_361_dialog_content = "Itu benar jika Anda benar-benar memikirkannya.",
  ui_story_5037_50370701_362_dialog_content = "Kok bisa?",
  ui_story_5037_50370701_363_dialog_content = "Makanannya mulai dingin! Mari menggali!",
  ui_story_5037_50370701_364_dialog_content = "Kamu benar. Mari rayakan kemenangan kita selagi makanan masih hangat.",
  ui_story_5037_50370701_365_dialog_content = "Ke PlayerName, Produser Terbaik!",
  ui_story_5037_50370701_366_dialog_content = "Bersulang!",
  ui_story_5037_50370701_367_option_content = "Bersulang!",
  ui_story_5037_50370801_1_dialog_content = "Latihan koreografi, latihan vokal, sesi tanya jawab, menghubungi pemilik tempat fanmeeting...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "Saya harus menghubungi pemilik antara makan siang dan makan malam, tetapi reporter akan berada di sini siang ini...",
  ui_story_5037_50370801_4_dialog_content = "...",
  ui_story_5037_50370801_5_dialog_content = "Saya juga perlu menyisihkan cukup waktu bagi Goldie untuk beristirahat, juga untuk mengganti dan merias wajahnya. Dengan semua ini terjadi dalam satu hari...",
  ui_story_5037_50370801_6_dialog_content = "…?",
  ui_story_5037_50370801_7_dialog_content = "Saya harus menghabiskan sepanjang hari bekerja lagi!",
  ui_story_5037_50370801_8_dialog_content = "PlayerName?",
  ui_story_5037_50370801_9_dialog_content = "Bwaaaaa!!!",
  ui_story_5037_50370801_10_dialog_content = "Oh, itu kamu saja, Goldie. Jantungku hampir melompat keluar dari dadaku barusan.",
  ui_story_5037_50370801_11_dialog_content = "Bisakah saya bertanya apa yang Anda gumamkan di sini?",
  ui_story_5037_50370801_12_dialog_content = "Sebenarnya, sepertinya Anda kekurangan energi. Ingin pergi berlatih beberapa gerakan dansa dengan saya untuk membangkitkan semangat Anda?",
  ui_story_5037_50370801_13_dialog_content = "Sedikit olahraga bisa sangat bermanfaat untuk tetap sehat!",
  ui_story_5037_50370801_14_dialog_content = "Produser yang sehat sangat penting untuk kesuksesan seorang idola! Bagaimana lagi Anda akan mengikuti semua konser dan acara saya?",
  ui_story_5037_50370801_15_dialog_content = "Ya, tapi aku masih merencanakan jadwalnya...",
  ui_story_5037_50370801_16_dialog_content = "Ada begitu banyak hal yang harus dilakukan setiap hari sehingga begitu saya selesai dengan satu hal, saya sudah terlambat untuk hal berikutnya...",
  ui_story_5037_50370801_17_dialog_content = "Bahkan mencoba menyesuaikan diri dengan istirahat beberapa menit hampir tidak mungkin sekarang!",
  ui_story_5037_50370801_18_dialog_content = "Kurasa aku benar-benar bukan produser yang hebat, lagipula...",
  ui_story_5037_50370801_19_dialog_content = "Mustahil! Anda seorang produser yang fantastis!",
  ui_story_5037_50370801_20_dialog_content = "Anda baru menjadi satu selama beberapa hari, namun Anda benar-benar akrab dengan persyaratan pekerjaan sehari-hari! Itu bukan sesuatu yang bisa dilakukan sembarang orang, lho!",
  ui_story_5037_50370801_21_dialog_content = "Jadi jangan terlalu keras pada dirimu sendiri, oke? Di sini, ingin mengelus Marshmallow?",
  ui_story_5037_50370801_22_dialog_content = "Saya selalu merasa lebih baik setelah mengelus bulunya yang lembut dan halus!",
  ui_story_5037_50370801_23_dialog_content = "Guk!",
  ui_story_5037_50370801_24_dialog_content = "Tentu, mengapa tidak-",
  ui_story_5037_50370801_25_dialog_content = "Tunggu!",
  ui_story_5037_50370801_26_dialog_content = "Ada apa?",
  ui_story_5037_50370801_27_dialog_content = "Saya lupa menelepon surat kabar tentang wawancara besok! Saya masih belum mengatur waktu untuk itu!",
  ui_story_5037_50370801_28_dialog_content = "Maaf, Goldie! Aku harus pergi!",
  ui_story_5037_50370801_29_dialog_content = "...",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>Tidak lama kemudian...</color>",
  ui_story_5037_50370801_31_dialog_content = "Fiuh... Syukurlah aku berhasil tepat waktu.",
  ui_story_5037_50370801_32_dialog_content = "Mereka salah satu surat kabar terbesar di sekitar. Jika saya membiarkan mereka menggantung, itu akan merusak reputasi Goldie.",
  ui_story_5037_50370801_33_dialog_content = "Selamat datang kembali, PlayerName!",
  ui_story_5037_50370801_34_dialog_content = "hai, Goldie! Maaf, saya terlalu terburu-buru sehingga saya lupa mengucapkan selamat tinggal ...",
  ui_story_5037_50370801_35_dialog_content = "Tidak apa-apa. Aku tahu itu karena kamu sangat sibuk dengan pekerjaan akhir-akhir ini.",
  ui_story_5037_50370801_36_dialog_content = "Menjadi produser bisa sangat sulit. Meskipun saya perlahan-lahan beradaptasi dengan pekerjaan selama beberapa hari terakhir,",
  ui_story_5037_50370801_37_dialog_content = "pekerjaan masih sangat menuntut!",
  ui_story_5037_50370801_38_dialog_content = "Jika yang harus saya lakukan hanyalah merencanakan jadwal, itu tidak akan sulit sama sekali.",
  ui_story_5037_50370801_39_dialog_content = "Tapi di atas semua perencanaan, saya harus melawan paparazzi di setiap kesempatan, dan memikirkan hal yang tepat untuk dikatakan setiap saat...",
  ui_story_5037_50370801_40_dialog_content = "Ini melelahkan...",
  ui_story_5037_50370801_41_dialog_content = "Saya tahu ini pekerjaan yang sulit.",
  ui_story_5037_50370801_42_dialog_content = "Tapi tidak peduli seberapa lelah Anda, Anda selalu menemukan cara untuk menyelesaikan pekerjaan, PlayerName!",
  ui_story_5037_50370801_43_dialog_content = "Itulah yang menurut saya sangat luar biasa tentang Anda!",
  ui_story_5037_50370801_44_dialog_content = "Terima kasih, Goldie! Hanya mendengar Anda mengatakan itu membuat saya merasa jauh lebih lelah!",
  ui_story_5037_50370801_45_dialog_content = "Melihat? Setiap orang membutuhkan dorongan dari waktu ke waktu, tidak peduli siapa mereka!",
  ui_story_5037_50370801_46_dialog_content = "Sekarang setelah Anda menyebutkannya... Apakah Anda menangani semua ini sendiri sebelumnya, Goldie?",
  ui_story_5037_50370801_47_dialog_content = "Tidak hanya menjadi idola, tapi juga menjadi produser diri sendiri...",
  ui_story_5037_50370801_48_dialog_content = "Melatih, merencanakan, menghindari paparazzi...",
  ui_story_5037_50370801_49_option_content = "Anda pasti sangat luar biasa telah melakukan semua itu sendiri!",
  ui_story_5037_50370801_50_dialog_content = "Haha... Bukan apa-apa, sungguh.",
  ui_story_5037_50370801_51_option_content = "Menangani semuanya sendiri pasti sulit...",
  ui_story_5037_50370801_52_dialog_content = "Memang begitu, tapi pada akhirnya aku berhasil melewatinya.",
  ui_story_5037_50370801_53_dialog_content = "Bahkan untuk orang sepertiku, menangani dua pekerjaan yang sama sekali berbeda tidaklah mudah.",
  ui_story_5037_50370801_54_dialog_content = "Saya mengalami segala macam rintangan di masa lalu. Bahkan ada saat-saat ketika saya ingin menyerah dan berhenti.",
  ui_story_5037_50370801_55_dialog_content = "Anda benar-benar merasa ingin berhenti sebelumnya? Aku bahkan tidak bisa membayangkan itu.",
  ui_story_5037_50370801_56_dialog_content = "Itu salah satu rahasia terbesar saya, jadi jangan sembarangan memberi tahu orang lain!",
  ui_story_5037_50370801_57_dialog_content = "Saya tidak akan memimpikannya! Sebagai produser Anda, saya tidak akan pernah mengatakan atau melakukan apa pun untuk menyakiti Anda atau reputasi Anda!",
  ui_story_5037_50370801_58_dialog_content = "Heehee! Senang mendengarnya!",
  ui_story_5037_50370801_59_dialog_content = "Tapi untuk menjawab pertanyaanmu... Ya, aku harus menangani semua pekerjaanku sendiri saat pertama kali menjadi idola.",
  ui_story_5037_50370801_60_dialog_content = "Melatih, merencanakan, dan menghindari paparazzi... semuanya.",
  ui_story_5037_50370801_61_dialog_content = "Saat itu, saya hanya tidur sekitar satu atau dua jam setiap hari!",
  ui_story_5037_50370801_62_dialog_content = "Saya harus bangun pagi setiap pagi hanya untuk mengganti latihan yang saya lewatkan sehari sebelumnya.",
  ui_story_5037_50370801_63_dialog_content = "Itu gila!",
  ui_story_5037_50370801_64_dialog_content = "Saya terbiasa begadang, tetapi hanya tidur satu hingga dua jam? Saya bahkan tidak akan bisa bangun dari tempat tidur keesokan harinya, apalagi melakukannya setiap hari ...",
  ui_story_5037_50370801_65_dialog_content = "Itu pada dasarnya saya.",
  ui_story_5037_50370801_66_dialog_content = "Satu atau dua hari dapat dikelola bagi kebanyakan orang, tetapi selama beberapa tahun? Selamanya?",
  ui_story_5037_50370801_67_dialog_content = "Setiap kali saya menyelesaikan pelatihan saya, saya akan berbaring di tempat tidur dan pikiran saya yang lelah akan memikirkan masa depan yang tak ada habisnya dari gaya hidup semacam itu.",
  ui_story_5037_50370801_68_dialog_content = "Namun pada akhirnya, kamu mampu melewati masa-masa sulit dan menjadi idola terkenal seperti sekarang ini!",
  ui_story_5037_50370801_69_dialog_content = "Benar sekali!",
  ui_story_5037_50370801_70_dialog_content = "Setiap kali saya merasa ingin menyerah, saya melemparkan peluru keberuntungan saya ke udara. Jika mendarat mengarah ke bawah, berarti sesuatu yang baik akan terjadi!",
  ui_story_5037_50370801_71_dialog_content = "Saat itu, peluru keberuntungan saya selalu mengarah ke bawah, jadi saya tahu bahwa jika saya terus berjalan... saya akan menjadi idola yang selalu saya impikan!",
  ui_story_5037_50370801_72_dialog_content = "Anda benar-benar memiliki semangat yang gigih ...",
  ui_story_5037_50370801_73_dialog_content = "Heehee!",
  ui_story_5037_50370801_74_dialog_content = "Tapi hal-hal yang sedikit berbeda sekarang, Anda tahu?",
  ui_story_5037_50370801_75_dialog_content = "Aku memilikimu bersamaku. Produser terbaik yang pernah saya minta!",
  ui_story_5037_50370801_76_dialog_content = "Terima kasih kepada Anda, saya bisa fokus pada pelatihan saya tanpa khawatir tentang hal-hal lain!",
  ui_story_5037_50370801_77_dialog_content = "Kemajuan saya tidak pernah lebih cepat!",
  ui_story_5037_50370801_78_dialog_content = "B-Apakah aku... benar-benar sangat membantu?",
  ui_story_5037_50370801_79_dialog_content = "Oh, tentu saja!",
  ui_story_5037_50370801_80_dialog_content = "Saya senang mendengarnya!",
  ui_story_5037_50370801_81_dialog_content = "Aku merasa sangat tidak berguna sebelumnya... Seolah-olah aku hanya membuat lebih banyak masalah untukmu.",
  ui_story_5037_50370801_82_dialog_content = "Tapi mendengarmu mengatakan itu membuatku merasa jauh lebih percaya diri.",
  ui_story_5037_50370801_83_dialog_content = "Sebagai produser Anda, saya akan terus melakukan yang terbaik untuk Anda, Goldie! Serahkan saja padaku!",
  ui_story_5037_50370801_84_dialog_content = "Aku akan menahanmu untuk itu!",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>Setelah latihan pagi</color>",
  ui_story_5037_50370901_2_dialog_content = "Sekali lagi terima kasih atas bantuan Anda, PlayerName!",
  ui_story_5037_50370901_3_dialog_content = "Saya selesai dengan latihan pagi saya, jadi sekarang saya punya waktu untuk istirahat.",
  ui_story_5037_50370901_4_dialog_content = "Jangan sebut itu, Goldie. Nikmati istirahat Anda!",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>Ketuk, ketuk!</color>",
  ui_story_5037_50370901_6_dialog_content = "Masuk!",
  ui_story_5037_50370901_7_dialog_content = "PlayerName! Oh, dan Goldie juga!",
  ui_story_5037_50370901_8_dialog_content = "Hai, Gronru!",
  ui_story_5037_50370901_9_dialog_content = "Gronru? Apa yang kamu lakukan di sini?",
  ui_story_5037_50370901_10_dialog_content = "Oh, hanya membeli beberapa bahan, itu saja. Saya mendengar Anda adalah produser besar di Umbraton sekarang, jadi saya pikir saya akan mampir dan memeriksa semuanya!",
  ui_story_5037_50370901_11_dialog_content = "Saya juga membawa game terbaru yang saya rancang! Apa yang kamu katakan? Ingin bermain beberapa putaran?",
  ui_story_5037_50370901_12_dialog_content = "Tentu saja saya-",
  ui_story_5037_50370901_13_dialog_content = "Er, maksudku... Tidak sekarang, maaf.",
  ui_story_5037_50370901_14_dialog_content = "Hah? Anda tidak ingin menantang saya hari ini? Saya harus mengatakan, itu tidak seperti Anda sama sekali ...",
  ui_story_5037_50370901_15_dialog_content = "Karena masih banyak pekerjaan yang harus saya lakukan sore ini. Sangat mudah bagi saya untuk lupa waktu ketika saya bermain video game...",
  ui_story_5037_50370901_16_dialog_content = "Anda ada benarnya, ya .... Baiklah, mungkin lain kali! Aku tidak akan mengganggu kalian lagi.",
  ui_story_5037_50370901_17_dialog_content = "Teruslah bekerja dengan baik, PlayerName! Kamu juga, Goldie!",
  ui_story_5037_50370901_18_dialog_content = "Saya menantikan konser Anda!",
  ui_story_5037_50370901_19_dialog_content = "Terima kasih! Berharap untuk melihat Anda di sana, juga!",
  ui_story_5037_50370901_20_dialog_content = "Sampai jumpa!",
  ui_story_5037_50370901_21_dialog_content = "Sampai jumpa!",
  ui_story_5037_50370901_22_dialog_content = "Baiklah, saatnya bersiap-siap untuk tugas sore ini...",
  ui_story_5037_50370901_23_dialog_content = "Tunggu, sekarang jam istirahat, bukan? Lebih baik beristirahat, sehingga Anda memiliki energi untuk melakukan sisa pekerjaan hari itu.",
  ui_story_5037_50370901_24_dialog_content = "Aku tahu, aku tahu... Tapi konsernya sudah dekat.",
  ui_story_5037_50370901_25_dialog_content = "Kami kehabisan waktu, tetapi pekerjaan terus menumpuk. Terkadang, tidak ada pilihan selain memberikan sedikit waktu luang kita...",
  ui_story_5037_50370901_26_dialog_content = "... Apakah Anda menggunakan waktu istirahat Anda untuk mengerjakan konser beberapa hari terakhir ini?",
  ui_story_5037_50370901_27_dialog_content = "Uh...K-Jenis...?",
  ui_story_5037_50370901_28_dialog_content = "Itu tidak akan berhasil!",
  ui_story_5037_50370901_29_dialog_content = "Tanpa istirahat yang cukup, kualitas kerja Anda hanya akan menurun! Anda tidak akan bisa menyelesaikan apa pun dengan kecepatan ini!",
  ui_story_5037_50370901_30_dialog_content = "Untuk menebus semua istirahat yang Anda habiskan untuk bekerja, Anda akan mengambil cuti sepanjang sore!",
  ui_story_5037_50370901_31_dialog_content = "Jalan-jalan, hirup udara segar, dan jangan kembali sampai Anda merasa baik dan istirahat!",
  ui_story_5037_50370901_32_dialog_content = "I-Itu benar-benar tidak perlu...",
  ui_story_5037_50370901_33_dialog_content = "Saya tidak akan menerima jawaban tidak! Ini menyangkut kesehatan dan efisiensi kerja Anda.",
  ui_story_5037_50370901_34_dialog_content = "T-Tapi jika saya produser Anda, apa yang akan Anda lakukan jika saya tidak ada?",
  ui_story_5037_50370901_35_dialog_content = "Anda tidak perlu khawatir tentang itu. Sudah kubilang, aku adalah produserku sendiri untuk waktu yang lama. Ini bukan masalah besar.",
  ui_story_5037_50370901_36_dialog_content = "Sekarang istirahatlah, dan jangan kembali ke kantor sampai besok pagi!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>Membanting!</color>",
  ui_story_5037_50370901_38_dialog_content = "(Dia baru saja mendorongku keluar dari pintu...)",
  ui_story_5037_50370901_39_dialog_content = "(Hmm... Kurasa aku akan jalan-jalan kalau begitu.)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>Beberapa menit kemudian di sebuah kafe</color>",
  ui_story_5037_50370901_41_dialog_content = "Apa yang dapat saya bantu?",
  ui_story_5037_50370901_42_dialog_content = "Coba saya lihat menunya...",
  ui_story_5037_50370901_43_dialog_content = "\"Kue Tiga Warna\"?",
  ui_story_5037_50370901_44_dialog_content = "Misi kami adalah mengadakan tiga konser dalam jangka waktu tertentu.",
  ui_story_5037_50370901_45_dialog_content = "Masih ada dua konser lagi...",
  ui_story_5037_50370901_46_dialog_content = "Kenapa aku tiba-tiba memikirkan itu?! Kembali ke menu!",
  ui_story_5037_50370901_47_dialog_content = "Mari kita lihat... Kue Kembar?",
  ui_story_5037_50370901_48_dialog_content = "Setelah pertunjukan dimulai, penonton dapat mengikuti preferensi mereka dan bergerak bebas di antara panggung.",
  ui_story_5037_50370901_49_dialog_content = "Pada akhirnya, tahap mana pun yang berhasil menarik lebih banyak penonton akan dinyatakan sebagai pemenang.",
  ui_story_5037_50370901_50_dialog_content = "Sigh... Aku ingin tahu apa yang bisa kita lakukan untuk menjaga perhatian orang?",
  ui_story_5037_50370901_51_dialog_content = "Apakah Kyllo benar-benar motivator yang kuat?",
  ui_story_5037_50370901_52_dialog_content = "Haruskah saya menemukan Kyllo saya sendiri untuk menggigit pergelangan kaki saya?",
  ui_story_5037_50370901_53_dialog_content = "Kenapa aku tidak bisa berhenti khawatir?!",
  ui_story_5037_50370901_54_dialog_content = "Maaf, saya rasa saya masih perlu lebih banyak waktu untuk melihat menu.",
  ui_story_5037_50370901_55_dialog_content = "Bukan masalah. Hubungi saja aku saat kau siap.",
  ui_story_5037_50370901_56_dialog_content = "Meskipun aku sedang tidak bekerja, aku tidak bisa berhenti memikirkan konser evaluasi. Ini hanya beberapa hari lagi ...",
  ui_story_5037_50370901_57_dialog_content = "Aku juga belum merencanakan jadwal Goldie untuk besok. Saya tidak bisa menahan perasaan tidak nyaman setiap kali saya memikirkannya ...",
  ui_story_5037_50370901_58_dialog_content = "Sigh... Kopi dan kue rasanya tidak enak saat aku stres begini.",
  ui_story_5037_50370901_59_dialog_content = "Aku bertanya-tanya bagaimana pelatihan Goldie berlangsung...?",
  ui_story_5037_50370901_60_dialog_content = "Tidak apa-apa jika aku mengintip untuk memastikan dia baik-baik saja. Benar?",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>Di luar agensi</color>",
  ui_story_5037_50370901_62_dialog_content = "Seharusnya ini ruang latihan. Aku harus bisa melihat ke dalam melalui jendela.",
  ui_story_5037_50370901_63_dialog_content = "saya dapat melihat Goldie... Tapi orang di sebelahnya ...",
  ui_story_5037_50370901_64_dialog_content = "Halo, Goldie? Saya dengan Daily Drivel, sumber gosip terpanas di seluruh Umbraton!",
  ui_story_5037_50370901_65_dialog_content = "Saya perhatikan bahwa Anda membanting pintu pada produser Anda hari ini.",
  ui_story_5037_50370901_66_dialog_content = "Kabar di jalan adalah Anda tidak pernah berhubungan baik dengannya, dan Anda langsung memecatnya! Benarkah itu?",
  ui_story_5037_50370901_67_dialog_content = "PlayerName dan saya dalam kondisi terbaik, terima kasih banyak. Kami selalu berteman baik.",
  ui_story_5037_50370901_68_dialog_content = "Lalu bagaimana Anda menjelaskan adegan sebelumnya?",
  ui_story_5037_50370901_69_dialog_content = "Membuang produsermu dan membiarkannya berdiri di jalan... Aku belum pernah melihat pemandangan yang menyedihkan ini!",
  ui_story_5037_50370901_70_dialog_content = "Itu karena—",
  ui_story_5037_50370901_71_dialog_content = "Omong kosong... Ini adalah paparazzi menjengkelkan dari sebelumnya!",
  ui_story_5037_50370901_72_dialog_content = "Goldie belum pernah bertemu atau berurusan dengannya sebelumnya... Jika dia tidak dihentikan, dia akan mengada-ada lagi!",
  ui_story_5037_50370901_73_dialog_content = "Aku harus membantunya!",
  ui_story_5037_50370901_74_dialog_content = "Produser kecil yang menyedihkan... Dilempar ke dunia yang dingin seperti anjing yang tidak diinginkan, tanpa—",
  ui_story_5037_50370901_75_dialog_content = "Hai! Apa yang terjadi di sini?",
  ui_story_5037_50370901_76_dialog_content = "PlayerName?!",
  ui_story_5037_50370901_77_dialog_content = "I-Ini kamu!",
  ui_story_5037_50370901_78_dialog_content = "Apakah saya mendengar Anda mengatakan sesuatu tentang Goldie dan aku tidak akur?",
  ui_story_5037_50370901_79_option_content = "Menolak keras rumor tersebut",
  ui_story_5037_50370901_80_dialog_content = "Itu konyol! Goldie dan saya adalah duo profesional terbaik yang pernah ada.",
  ui_story_5037_50370901_81_option_content = "Sabar menjelaskan situasinya",
  ui_story_5037_50370901_82_dialog_content = "Hubungan kami baik-baik saja. Faktanya, kami bekerja sama dengan sangat baik.",
  ui_story_5037_50370901_83_dialog_content = "*Mencemooh*",
  ui_story_5037_50370901_84_dialog_content = "Itu benar, kok!",
  ui_story_5037_50370901_85_dialog_content = "Dan bahkan jangan berpikir untuk memutarbalikkan kata-kata kita, atau...",
  ui_story_5037_50370901_86_dialog_content = "Baiklah, baiklah!",
  ui_story_5037_50370901_87_dialog_content = "Maaf, tapi aku harus pergi!",
  ui_story_5037_50370901_88_dialog_content = "Wah... Syukurlah kau kembali, PlayerName.",
  ui_story_5037_50370901_89_dialog_content = "Kalau tidak, saya tidak tahu apa yang akan saya lakukan untuk membuat orang itu pergi.",
  ui_story_5037_50370901_90_dialog_content = "Saya tidak pernah tahu paparazzi bisa berdedikasi untuk pekerjaan mereka ...",
  ui_story_5037_50370901_91_dialog_content = "Dia menukik ke bawah praktis begitu aku pergi.",
  ui_story_5037_50370901_92_dialog_content = "Itu mengingatkanku... Bukankah seharusnya kau cuti?",
  ui_story_5037_50370901_93_dialog_content = "Apa yang kamu lakukan di belakang kantor?",
  ui_story_5037_50370901_94_dialog_content = "Aku, uh... Yah, karena...",
  ui_story_5037_50370901_95_dialog_content = "Mendesah. Dengar, aku tahu kau menyuruhku istirahat, tapi aku tidak bisa melakukannya sekarang.",
  ui_story_5037_50370901_96_dialog_content = "Sejujurnya... Aku tidak bisa berhenti mencemaskan konser evaluasi.",
  ui_story_5037_50370901_97_dialog_content = "Begitu saya mulai memikirkannya, saya kehilangan nafsu makan, dan saya tidak bisa beristirahat.",
  ui_story_5037_50370901_98_dialog_content = "Oh, begitu…",
  ui_story_5037_50370901_99_dialog_content = "Yeah... Itu sebabnya aku hanya ingin menyelesaikannya, kau tahu? Saya tidak berpikir saya akan dapat beristirahat dengan baik sampai konser selesai.",
  ui_story_5037_50370901_100_dialog_content = "Hmm…",
  ui_story_5037_50370901_101_dialog_content = "Sejujurnya, saya merasakan hal yang sama.",
  ui_story_5037_50370901_102_dialog_content = "Dulu saya sangat mampu menghadapi reporter gosip ini... Tidak ada yang mereka katakan atau tulis yang benar-benar mengganggu saya sebelumnya.",
  ui_story_5037_50370901_103_dialog_content = "Tapi sejak kita mulai bekerja sama... Aku semakin mengandalkanmu untuk menangani hal-hal seperti ini.",
  ui_story_5037_50370901_104_dialog_content = "Sekarang saya dapat mengatakan bahwa saya menjadi sedikit berkarat ketika harus menyuruh orang-orang itu pergi.",
  ui_story_5037_50370901_105_dialog_content = "Apakah saya membuat Anda kehilangan keunggulan?",
  ui_story_5037_50370901_106_dialog_content = "Tidak mungkin! Jika ada, melihatmu muncul barusan membuatku merasa lebih kuat, PlayerName!",
  ui_story_5037_50370901_107_dialog_content = "Sejak Anda menjadi produser saya, saya dapat mendedikasikan diri saya untuk pelatihan, meningkatkan semua keterampilan saya secara keseluruhan.",
  ui_story_5037_50370901_108_dialog_content = "Aku bukan Goldie yang sama seperti dulu. Saya adalah Super Goldie yang baru dan lebih baik!",
  ui_story_5037_50370901_109_dialog_content = "Ha ha ha ha! Yah, aku lega kau tidak berpikir aku menahanmu.",
  ui_story_5037_50370901_110_dialog_content = "Produser hebat seperti Anda tidak akan pernah bisa melakukan hal seperti itu, PlayerName!",
  ui_story_5037_50370901_111_dialog_content = "Tapi pas mau istirahat...",
  ui_story_5037_50370901_112_dialog_content = "Anda tidak perlu khawatir tentang saya lagi, Goldie. Saya tahu kami sangat sibuk sekarang, tetapi saya berjanji akan mendapatkan istirahat dan olahraga yang cukup mulai sekarang!",
  ui_story_5037_50370901_113_dialog_content = "Maka saya juga akan memastikan untuk mengikuti semua keputusan Anda juga.",
  ui_story_5037_50370901_114_dialog_content = "Aku percaya padamu!",
  ui_story_5037_50371001_1_dialog_content = "Konser evaluasi akhirnya berakhir!",
  ui_story_5037_50371001_2_dialog_content = "Kami akhirnya menyelesaikan tantangan terbesar kami! Untunglah.",
  ui_story_5037_50371001_3_dialog_content = "Segera setelah saya memiliki waktu untuk bersantai, tiba-tiba saya mulai merasa sangat lelah ...",
  ui_story_5037_50371001_4_dialog_content = "Maka Anda harus merayakannya dengan banyak istirahat hari ini!",
  ui_story_5037_50371001_5_dialog_content = "Ya, sudah waktunya.",
  ui_story_5037_50371001_6_dialog_content = "Jadi apa yang harus kita lakukan?",
  ui_story_5037_50371001_7_dialog_content = "Tunggu, saya mengerti! Ingin mendengar saya bernyanyi?",
  ui_story_5037_50371001_8_dialog_content = "Saya sedang mempersiapkan lagu baru untuk konser kelulusan!",
  ui_story_5037_50371001_9_dialog_content = "Memang masih ada beberapa bagian yang hilang, tapi sisa lagunya sudah selesai.",
  ui_story_5037_50371001_10_dialog_content = "Tentu! Saya yakin itu sudah terdengar luar biasa!",
  ui_story_5037_50371001_11_dialog_content = "Lalu tanpa basa-basi lagi...",
  ui_story_5037_50371001_12_dialog_content = "♪ Meskipun kita harus berpisah, aku tahu kita akan baik-baik saja ♪",
  ui_story_5037_50371001_13_dialog_content = "♪ Terpisah seribu mil, namun bintang kita akan selalu bersinar ♪",
  ui_story_5037_50371001_14_dialog_content = "♪ Jadi tolong jangan menangis; masa depan kita masih ada di depan ♪",
  ui_story_5037_50371001_15_dialog_content = "♪ Melalui lagu ini, aku mengucapkan selamat tinggal, meski aku tahu kita akan bertemu lagi ♪",
  ui_story_5037_50371001_16_dialog_content = "(Menakjubkan...)",
  ui_story_5037_50371001_17_dialog_content = "(Tapi kali ini, liriknya menyebutkan perpisahan... Dan melodinya terdengar lebih lembut dari lagu sebelumnya.)",
  ui_story_5037_50371001_18_dialog_content = "Sehat, PlayerName? Bagaimana menurutmu?",
  ui_story_5037_50371001_19_option_content = "Itu cantik!",
  ui_story_5037_50371001_20_dialog_content = "Wah terima kasih!",
  ui_story_5037_50371001_21_option_content = "Ini berbeda dari lagu-lagu Anda sebelumnya.",
  ui_story_5037_50371001_22_dialog_content = "Ah, jadi kamu menyadarinya.",
  ui_story_5037_50371001_23_dialog_content = "Lagipula itu adalah lagu untuk konser kelulusan... Jadi wajar saja, aku menulisnya dengan segala rasa syukur di hatiku!",
  ui_story_5037_50371001_24_dialog_content = "Tapi rasanya ada yang lebih dari sekedar rasa terima kasih.",
  ui_story_5037_50371001_25_dialog_content = "Kedengarannya agak sedih, dan sedih ... Saya tidak tahu.",
  ui_story_5037_50371001_26_dialog_content = "Karena itu lagu perpisahan.",
  ui_story_5037_50371001_27_dialog_content = "Tapi kepada siapa kamu mengucapkan selamat tinggal, Goldie?",
  ui_story_5037_50371001_28_dialog_content = "Ada sesuatu yang masih belum kumengerti... Apa sebenarnya konser kelulusan itu?",
  ui_story_5037_50371001_29_dialog_content = "Konser kelulusan digelar untuk para idol yang mengundurkan diri dan hengkang.",
  ui_story_5037_50371001_30_dialog_content = "Ini adalah kesempatan bagi sang idola untuk mengucapkan selamat tinggal kepada penggemarnya.",
  ui_story_5037_50371001_31_dialog_content = "Apa-?!",
  ui_story_5037_50371001_32_dialog_content = "Apakah kalian tidak akan menjadi idola lagi setelah konser ini???",
  ui_story_5037_50371001_33_dialog_content = "Apa yang kamu bicarakan? Saya masih memiliki banyak tahun menjadi idola dalam diri saya.",
  ui_story_5037_50371001_34_dialog_content = "Konser ini hanya untuk video promosi! Konser kelulusanku yang sebenarnya tidak akan lama lagi!",
  ui_story_5037_50371001_35_dialog_content = "Juga... Sebagai produser saya, saya ingin Anda merasakan bagaimana rasanya bekerja dengan seorang idola hingga akhir kariernya!",
  ui_story_5037_50371001_36_dialog_content = "Aku masih berencana untuk menjadi idola setelahnya, bodoh!",
  ui_story_5037_50371001_37_dialog_content = "Kau membuatku takut...",
  ui_story_5037_50371001_38_dialog_content = "Untuk sesaat, saya pikir Anda sudah selesai menjadi idola.",
  ui_story_5037_50371001_39_dialog_content = "Tentu saja tidak!",
  ui_story_5037_50371001_40_dialog_content = "Bagi saya, konser berikutnya hanyalah akhir dari satu babak dalam karir saya.",
  ui_story_5037_50371001_41_dialog_content = "Itu akan berfungsi sebagai penutup untuk semua waktu yang kita habiskan bersama, dan semua kesulitan dan kemenangan yang kita bagi!",
  ui_story_5037_50371001_42_dialog_content = "Aku tahu.",
  ui_story_5037_50371001_43_dialog_content = "Sejujurnya, saya tidak bisa membayangkan Anda melakukan hal lain dalam hidup ...",
  ui_story_5037_50371001_44_dialog_content = "Dalam pikiran saya, Anda adalah lambang idola.",
  ui_story_5037_50371001_45_dialog_content = "Saya tidak bisa memberi tahu Anda betapa berartinya itu bagi saya!",
  ui_story_5037_50371001_46_dialog_content = "Jika itu kesan yang saya berikan kepada Anda, maka itu berarti saya melakukan pekerjaan saya dengan benar!",
  ui_story_5037_50371001_47_dialog_content = "Tapi pada akhirnya... Saya hanya orang biasa, seperti orang lain.",
  ui_story_5037_50371001_48_dialog_content = "Suatu hari nanti, saya harus mengadakan konser kelulusan sungguhan, dan mengucapkan selamat tinggal kepada penggemar saya.",
  ui_story_5037_50371001_49_dialog_content = "Mari kita bicara tentang sesuatu yang kurang menyedihkan...",
  ui_story_5037_50371001_50_dialog_content = "Apakah itu? Saya tidak benar-benar berpikir begitu.",
  ui_story_5037_50371001_51_dialog_content = "Tidak?",
  ui_story_5037_50371001_52_dialog_content = "Wisuda hanyalah bagian lain dari kehidupan seorang idola, dan itu pasti datang kepada kita semua apakah kita menyambutnya atau tidak.",
  ui_story_5037_50371001_53_dialog_content = "Daripada mencoba menghindarinya, saya ingin melakukan semua yang saya bisa untuk memastikan konser kelulusan saya sendiri adalah yang terbaik!",
  ui_story_5037_50371001_54_dialog_content = "Apa pun yang terjadi, saya tidak ingin menyesal, untuk saya atau penggemar saya.",
  ui_story_5037_50371001_55_dialog_content = "Apa pun yang terjadi, saya ingin memastikan bahwa saya bersinar terang di hati mereka selama sisa hidup mereka.",
  ui_story_5037_50371001_56_dialog_content = "Itu sebabnya saya akan terus melakukan yang terbaik sampai hari kelulusan tiba!",
  ui_story_5037_50371001_57_dialog_content = "Kedengarannya sangat mirip dengan Anda!",
  ui_story_5037_50371001_58_dialog_content = "Jadi, saat tiba waktunya untuk berhenti menjadi idola... Lalu apa yang akan kamu lakukan?",
  ui_story_5037_50371001_59_dialog_content = "Hmm... Aku belum benar-benar memutuskan!",
  ui_story_5037_50371001_60_dialog_content = "Saya punya banyak ide, tapi saat ini... Favorit saya adalah membuka kafe hewan peliharaan saya sendiri!",
  ui_story_5037_50371001_61_dialog_content = "Dengan begitu, saya bisa bekerja dan menemani Marshmallow pada saat yang bersamaan!",
  ui_story_5037_50371001_62_dialog_content = "Kedengarannya seperti ide bagus!",
  ui_story_5037_50371001_63_dialog_content = "Minum kopi dan bermain dengan binatang kecil yang lucu... terdengar seperti mimpi.",
  ui_story_5037_50371001_64_dialog_content = "Aku di sana bersamamu!",
  ui_story_5037_50371001_65_dialog_content = "Setiap kali saya merasa lelah, mengelus bulu lembut dan halus Marshmallow selalu membantu saya rileks.",
  ui_story_5037_50371001_66_dialog_content = "Sebagai idola, tugasku adalah menghibur semua orang dengan kekuatan lagu dan tarian.",
  ui_story_5037_50371001_67_dialog_content = "Sebuah kafe hewan peliharaan akan membantu saya terus membawa kebahagiaan bagi kehidupan semua orang setelah saya pensiun!",
  ui_story_5037_50371001_68_dialog_content = "Apa pun yang terjadi dalam hidup, saya tahu saya akan baik-baik saja.",
  ui_story_5037_50371101_1_dialog_content = "(Saya menemukan surat dari Vic di kantor hari ini. Itu ditujukan kepada saya.)",
  ui_story_5037_50371101_2_dialog_content = "(Dikatakan untuk menunggunya di ruang dansa hari ini...Bahwa dia ingin bertanya padaku tentang beberapa hal secara pribadi.)",
  ui_story_5037_50371101_3_dialog_content = "Kau datang!",
  ui_story_5037_50371101_4_dialog_content = "Hm? Apakah itu kamu, Fia?",
  ui_story_5037_50371101_5_dialog_content = "Aduh, aduh, aduh... Pelan-pelan, Fia! Kau akan merobek telinga tuanmu yang malang!",
  ui_story_5037_50371101_6_dialog_content = "Bagaimana kalian bisa masuk ke sini?",
  ui_story_5037_50371101_7_dialog_content = "Sudah kubilang tidak ada alasan untuk repot dengan ini, Fia!",
  ui_story_5037_50371101_8_dialog_content = "Bahkan jika PlayerName adalah teman kita, dia masih perlu meluruskan semuanya!",
  ui_story_5037_50371101_9_dialog_content = "... Bisakah seseorang tolong jelaskan apa yang terjadi?",
  ui_story_5037_50371101_10_dialog_content = "Baiklah, biarkan aku terus terang. Apa masalahnya dengan paparazzi yang berkeliaran di sini setiap hari?",
  ui_story_5037_50371101_11_dialog_content = "Paparazi?",
  ui_story_5037_50371101_12_dialog_content = "Oh, maksudmu pria berpenampilan samar dengan janggut itu?",
  ui_story_5037_50371101_13_dialog_content = "Ya, itu dia! Jadi, Anda benar-benar mengenalnya!",
  ui_story_5037_50371101_14_dialog_content = "Si brengsek itu terus menerobos masuk dan mengganggu latihan Guruku yang tidak berguna!",
  ui_story_5037_50371101_15_dialog_content = "Yang lebih buruk adalah setiap kali saya mengusirnya... Keesokan harinya, dia mengeluarkan artikel jahat yang memfitnah Guru dan malah memuji Goldie!",
  ui_story_5037_50371101_16_dialog_content = "Katakan yang sebenarnya! Apakah dia bekerja untuk kalian?",
  ui_story_5037_50371101_17_dialog_content = "... Anda benar-benar berpikir saya akan melakukan hal seperti itu?",
  ui_story_5037_50371101_18_dialog_content = "Kami juga dilecehkan olehnya setiap hari!",
  ui_story_5037_50371101_19_dialog_content = "Sungguh?",
  ui_story_5037_50371101_20_dialog_content = "Melihat? Aku bilang itu bukan mereka!",
  ui_story_5037_50371101_21_dialog_content = "Surat kabar yang sama yang memfitnah saya juga pernah melakukan hal yang sama pada Goldie di masa lalu.",
  ui_story_5037_50371101_22_dialog_content = "B-benarkah?",
  ui_story_5037_50371101_23_dialog_content = "Saya kira saya hanya membaca hal-hal tentang Guru saya yang tidak berguna...",
  ui_story_5037_50371101_24_dialog_content = "Sekarang setelah Anda menyebutkannya, saya rasa saya ingat pernah melihat artikel fitnah tentang Vic juga.",
  ui_story_5037_50371101_25_dialog_content = "Tapi kalau bukan kalian yang mengirimnya ke sini, siapa lagi?",
  ui_story_5037_50371101_26_dialog_content = "Saya pikir dia terus datang kembali karena menurutnya tempat ini penuh dengan gosip untuk ditulis.",
  ui_story_5037_50371101_27_dialog_content = "Meskipun saya memastikan untuk mengunci pintu setiap hari sebelum saya pergi, dia selalu berhasil masuk ke dalam ...",
  ui_story_5037_50371101_28_dialog_content = "Aku bersumpah, tidak ada cara untuk menyingkirkannya!",
  ui_story_5037_50371101_29_dialog_content = "Aku tahu, ya! Dia merugikan kita banyak penggemar juga!",
  ui_story_5037_50371101_30_dialog_content = "Jadi saya kira ini semua hanya kesalahpahaman ...",
  ui_story_5037_50371101_31_dialog_content = "Maaf telah mencurigaimu.",
  ui_story_5037_50371101_32_dialog_content = "Jangan khawatir tentang itu, Fia. Apakah kalian butuh yang lain?",
  ui_story_5037_50371101_33_dialog_content = "Tidak! Guru masih memiliki banyak pelatihan yang harus dilakukan, jadi sampai jumpa lagi!",
  ui_story_5037_50371101_34_dialog_content = "Mari kita semua melakukan yang terbaik, oke?",
  ui_story_5037_50371101_35_dialog_content = "Tentu, lalu—",
  ui_story_5037_50371101_36_dialog_content = "<size=45>Tunggu!</size>",
  ui_story_5037_50371101_37_dialog_content = "Hah? Apa sekarang?",
  ui_story_5037_50371101_38_dialog_content = "Saya punya permintaan kecil, PlayerName.",
  ui_story_5037_50371101_39_dialog_content = "Y-Ya...?",
  ui_story_5037_50371101_40_dialog_content = "Bisakah Anda... Bisakah Anda mengajari saya cara menghadapi paparazzi? Aku memohon Anda!",
  ui_story_5037_50371101_41_dialog_content = "Hah?! M-Pikirkan ruang pribadi saya!",
  ui_story_5037_50371101_42_dialog_content = "Berhenti menggunakan ikat kepala saya untuk menghapus air mata Anda !!",
  ui_story_5037_50371101_43_dialog_content = "*Mencium* Oke...",
  ui_story_5037_50371101_44_dialog_content = "Berkat reporter bodoh itu, dan semua kebohongannya... Aku kehilangan lebih banyak penggemar daripada yang bisa kutanggung!",
  ui_story_5037_50371101_45_dialog_content = "Satu-satunya cara untuk menggantikan penggemarku yang hilang adalah dengan berlatih lebih keras dari sebelumnya dan mengikuti sebanyak mungkin acara idola.",
  ui_story_5037_50371101_46_dialog_content = "Fia juga tidak akan membiarkanku keluar... Dia memelototiku seperti elang selama latihan, jadi aku tidak bisa mengendur sedetik pun!",
  ui_story_5037_50371101_47_dialog_content = "Wah, baru saja sesi latihan terakhir, saya mencoba mengatur napas untuk beberapa saat... Dan dia membuat Kyllo menggigit kaki saya!",
  ui_story_5037_50371101_48_dialog_content = "Lihat saja ini, PlayerName! Kakiku memiliki lebih banyak bekas gigitan daripada mainan kunyah! Anda harus menyelamatkan saya ...",
  ui_story_5037_50371101_49_dialog_content = "Baiklah, baiklah! Saya akan mengajari Anda apa yang saya tahu!",
  ui_story_5037_50371101_50_dialog_content = "Aku tahu aku bisa mengandalkanmu!",
  ui_story_5037_50371101_51_dialog_content = "Sekarang, dari mana kita harus mulai...",
  ui_story_5037_50371101_52_dialog_content = "Mengapa kita tidak melihat Daily Drivel edisi hari ini terlebih dahulu? Mari kita lihat...",
  ui_story_5037_50371101_53_dialog_content = "\"Vic pernah menggambarkan dirinya sebagai anak berusia 18 tahun yang abadi, tetapi usia sebenarnya jauh lebih besar dari itu\"?!",
  ui_story_5037_50371101_54_dialog_content = "Maksudku, ini terdengar seperti pernyataan yang benar.",
  ui_story_5037_50371101_55_dialog_content = "Oh, saya ingat! Saya kira saya memang mengatakan itu tentang diri saya sendiri, ya ...",
  ui_story_5037_50371101_56_dialog_content = "Bagaimana ini bohong, kalau begitu ?!",
  ui_story_5037_50371101_57_dialog_content = "Usia saya yang sebenarnya adalah rahasia!",
  ui_story_5037_50371101_58_dialog_content = "Baik... Saya kira tidak apa-apa, ingatlah untuk merahasiakannya.",
  ui_story_5037_50371101_59_dialog_content = "Apa lagi yang dikatakannya? \"Vic percaya bahwa dia jauh lebih muda dan energik daripada Goldie yang selalu populer\"?!",
  ui_story_5037_50371101_60_dialog_content = "Hah? Itu kata-katanya, bukan kata-kataku! Dia mengatakan itu sambil memuji penampilanku!",
  ui_story_5037_50371101_61_dialog_content = "Jadi... Bagaimana tanggapan Anda?",
  ui_story_5037_50371101_62_dialog_content = "Yah, pujian adalah pujian! Mengapa saya menyangkalnya?",
  ui_story_5037_50371101_63_dialog_content = "Jika Anda setuju dengan apa pun yang dia katakan, itu hanya membuat Anda menjadi target yang lebih mudah, Vic!",
  ui_story_5037_50371101_64_dialog_content = "L-Lalu bagaimana aku harus menjawab?!",
  ui_story_5037_50371101_65_dialog_content = "Ungkapannya dimaksudkan untuk menipu Anda agar mengakui bahwa Anda pikir Anda lebih baik daripada idola lainnya.",
  ui_story_5037_50371101_66_dialog_content = "Jadi jika Anda menemukan diri Anda dalam situasi yang sama, cobalah menjadi lebih rendah hati dan katakan bahwa orang lain lebih baik dari Anda. Dengan begitu, dia tidak akan punya apa-apa untuk dikerjakan!",
  ui_story_5037_50371101_67_dialog_content = "Oke oke. Saya akan mencobanya lain kali!",
  ui_story_5037_50371101_68_dialog_content = "Mari terus membaca...",
  ui_story_5037_50371101_69_dialog_content = "\"Produser Vic diketahui mengancam reporter yang tidak bersalah dengan kekerasan, binatang buas\"?!",
  ui_story_5037_50371101_70_dialog_content = "Fia... Apa yang kamu lakukan?",
  ui_story_5037_50371101_71_dialog_content = "J-Jangan lihat aku!",
  ui_story_5037_50371101_72_dialog_content = "Dia terlalu menyebalkan, jadi aku menyuruh Kyllo mengusirnya ke jalan!",
  ui_story_5037_50371101_73_dialog_content = "A-aku mengerti... Jangan lakukan itu lagi, oke?",
  ui_story_5037_50371101_74_dialog_content = "Betapapun menjengkelkannya para reporter ini, menggunakan kekerasan bukanlah cara yang tepat untuk menghadapi mereka.",
  ui_story_5037_50371101_75_dialog_content = "Anda hanya memberi mereka lebih banyak alasan untuk menargetkan Anda dengan fitnah mereka.",
  ui_story_5037_50371101_76_dialog_content = "Jadi, bagaimana saya harus berurusan dengan mereka ?!",
  ui_story_5037_50371101_77_dialog_content = "Saya tidak bisa menghentikan mereka masuk, dan saya tidak bisa membuat mereka pergi ... Mereka seperti segerombolan nyamuk tetapi bahkan lebih ganas!",
  ui_story_5037_50371101_78_dialog_content = "Ketika mereka mengganggu Anda seperti itu, Anda hanya bisa dengan sopan bersikeras bahwa Anda tidak menerima wawancara dan menolaknya.",
  ui_story_5037_50371101_79_dialog_content = "Dengan begitu, meski mereka memfitnah Vic dalam artikel mereka, klaim mereka tidak akan memiliki bukti nyata untuk mendukungnya, yang akan diperhatikan orang.",
  ui_story_5037_50371101_80_dialog_content = "Juga, selama Vic terus meningkat, tidak ada gosip yang dapat merusak reputasinya.",
  ui_story_5037_50371101_81_dialog_content = "Oke, saya pikir saya mengerti sekarang.",
  ui_story_5037_50371101_82_dialog_content = "Terima kasih, PlayerName. Anda benar-benar penyelamat!",
  ui_story_5037_50371101_83_dialog_content = "Jangan sebutkan itu. Kami mungkin saingan untuk saat ini, tapi kami akan selalu berteman terlebih dahulu.",
  ui_story_5037_50371101_84_dialog_content = "Saya tidak akan pernah membiarkan sesuatu yang sepele seperti kontes menghalangi saya untuk membantu teman-teman saya!",
  ui_story_5037_50371101_85_dialog_content = "*Menangis* Kamu benar-benar pahlawanku!",
  ui_story_5037_50371101_86_dialog_content = "Terima kasih banyak, PlayerName!",
  ui_story_5037_50371101_87_dialog_content = "Saya bersumpah demi kehormatan saya sebagai ahli ekstrozoologi dan idola bahwa saya tidak akan mengecewakan Anda!",
  ui_story_5037_50371101_88_dialog_content = "Ketika Fia sedang melakukan penelitian tentang bagaimana menjadi seorang produser, dia menemukan sepasang buku yang mungkin berguna bagi Anda.",
  ui_story_5037_50371101_89_dialog_content = "Silakan dan pilih salah satu di antara mereka. Anggap saja sebagai tanda terima kasih kami.",
  ui_story_5037_50371101_90_dialog_content = "Tunggu... Bukankah ini buku-bukuku? Pantas saja aku tidak bisa menemukannya selama ini... Kau menyembunyikannya di pakaianmu!",
  ui_story_5037_50371101_91_dialog_content = "T-Bagaimanapun, aku sudah membaca keduanya, jadi pilih mana yang kau mau, PlayerName.",
  ui_story_5037_50371101_92_dialog_content = "Terima kasih... Saya hanya akan mengambil yang ini untuk saat ini—",
  ui_story_5037_50371101_93_option_content = "\"Kursus Singkat untuk Idola Baru\"",
  ui_story_5037_50371101_94_option_content = "\"Pengembangan Profesional untuk Produser Profesional\"",
  ui_story_5037_50371101_95_dialog_content = "Benar! Kita harus kembali ke pelatihan kita sekarang!",
  ui_story_5037_50371101_96_dialog_content = "Ayo pergi, tuan yang tidak berguna! Hari ini belum berakhir!",
  ui_story_5037_50371101_97_dialog_content = "H-Hah?! Tetap?!",
  ui_story_5037_50371101_98_dialog_content = "Betul sekali! Kami membuang banyak waktu berharga untuk berbicara PlayerName, jadi sekarang kamu akan membuat semuanya!",
  ui_story_5037_50371101_99_dialog_content = "Seseorang selamatkan aku... Tolong...",
  ui_story_5037_50371201_1_dialog_content = "Vic memintaku untuk menunggunya di sini... Apa dia tidak tahu kontes konser sebentar lagi?",
  ui_story_5037_50371201_2_dialog_content = "Dia bahkan menyuruhku datang ke sini sendirian, dan merahasiakannya dari Fia...",
  ui_story_5037_50371201_3_dialog_content = "Apa yang dia rencanakan sekarang?",
  ui_story_5037_50371201_4_dialog_content = "Oho? Tepat waktu, seperti yang saya harapkan! Senang melihatmu, PlayerName!",
  ui_story_5037_50371201_5_dialog_content = "Baiklah Vic, katakan padaku apa yang terjadi...",
  ui_story_5037_50371201_6_dialog_content = "Oh, tidak ada yang terlalu penting, sungguh! Aku hanya ingin bertanya...",
  ui_story_5037_50371201_7_dialog_content = "Bisakah Anda membiarkan saya bersembunyi di sini selama sehari? Silakan?!",
  ui_story_5037_50371201_8_dialog_content = "Hah...?!",
  ui_story_5037_50371201_9_dialog_content = "Ini hampir waktunya untuk konser, mengapa Anda ingin bersembunyi di sini daripada berlatih?",
  ui_story_5037_50371201_10_dialog_content = "Justru karena pelatihan saya! Dengarkan saja, seperti inilah hari-hari biasa bagiku...",
  ui_story_5037_50371201_11_dialog_content = "Fia membangunkan saya setiap pagi untuk latihan bahkan sebelum matahari terbit.",
  ui_story_5037_50371201_12_dialog_content = "Bangunlah, Tuan yang malas! Saatnya latihan!",
  ui_story_5037_50371201_13_dialog_content = "Mari kita mulai dengan membentuk tubuh lembek itu! Sepuluh putaran mengelilingi hutan, ayo!",
  ui_story_5037_50371201_14_dialog_content = "Hrnnng... Tapi ngantuk banget...",
  ui_story_5037_50371201_15_dialog_content = "Lima menit lagi...",
  ui_story_5037_50371201_16_dialog_content = "Tidak bekerja sama? Baiklah olehku... Tangkap dia, Kyllo!",
  ui_story_5037_50371201_17_dialog_content = "Lo—!",
  ui_story_5037_50371201_18_dialog_content = "Aduh!!!",
  ui_story_5037_50371201_19_dialog_content = "S-Berhenti menggigit! aku bangun, aku bangun!!!",
  ui_story_5037_50371201_20_dialog_content = "Setelah berlari, saya segera mandi dan sarapan.",
  ui_story_5037_50371201_21_dialog_content = "Sarapan hari ini adalah roti serbuk gergaji dengan wortel rebus dan segelas susu!",
  ui_story_5037_50371201_22_dialog_content = "T-Tapi aku sudah merebus wortel selama tiga hari berturut-turut sekarang... Tidak bisakah kita mengubahnya sedikit?",
  ui_story_5037_50371201_23_dialog_content = "Seperti mungkin tusuk sate cacing pasir yang mendesis, pedas, dan panggang?",
  ui_story_5037_50371201_24_dialog_content = "Anda seorang idola sekarang, Guru, dan idola harus memperhatikan sosok mereka setiap saat! Jika Anda tidak ingin wortel rebus, maka Anda kurang beruntung... Karena coba tebak untuk makan siang dan makan malam?",
  ui_story_5037_50371201_25_dialog_content = "Tidaaaak!",
  ui_story_5037_50371201_26_dialog_content = "Dan—",
  ui_story_5037_50371201_27_dialog_content = "Urgh... Kurasa aku sudah cukup mendengar, Vic...",
  ui_story_5037_50371201_28_dialog_content = "Karena itu, demi kesehatan dan kewarasanku, aku mohon padamu, PlayerName... Biarkan aku bersembunyi di sini selama sehari dan istirahat!",
  ui_story_5037_50371201_29_dialog_content = "Satu hari saja sudah lebih dari cukup! Tidak ada Aurorian yang harus melewati neraka seperti ini!",
  ui_story_5037_50371201_30_dialog_content = "Jika ini terus berlanjut, dunia akan kehilangan ahli ekstrozoologi terhebatnya dalam waktu singkat!",
  ui_story_5037_50371201_31_dialog_content = "Kamu... Aku... Huh...",
  ui_story_5037_50371201_32_dialog_content = "Aku tahu Fia melakukan ini hanya untuk membantumu lulus kontes konser, tapi aturan latihannya sepertinya sedikit... ketat.",
  ui_story_5037_50371201_33_dialog_content = "Anda dapat tinggal di sini dan beristirahat sebentar, tetapi hanya dengan dua syarat—",
  ui_story_5037_50371201_34_dialog_content = "Satu, kamu harus kembali ke Fia segera setelah kamu istirahat, jadi dia tidak mengkhawatirkanmu.",
  ui_story_5037_50371201_35_dialog_content = "Dan dua... Anda harus berbicara serius dengannya Fia tentang perasaan Anda pada rejimen pelatihannya.",
  ui_story_5037_50371201_36_dialog_content = "Bukan masalah! Selama aku bisa kalah, eh... Maksudku, hilangkan sebagian dari rasa lelah ini. Aku akan melakukan apa pun yang Anda inginkan!",
  ui_story_5037_50371201_37_dialog_content = "Baiklah, kalau begitu istirahatlah, Vic. Aku masih harus menyusun jadwal Goldie untuk hari ini, jadi aku akan meninggalkanmu sendirian.",
  ui_story_5037_50371201_38_dialog_content = "Ya, ya, silakan! Aku akan baik-baik saja sendiri!",
  ui_story_5037_50371201_39_dialog_content = "Sofa ini terlihat sangat nyaman... Cocok untuk tidur siang yang panjang!",
  ui_story_5037_50371201_40_dialog_content = "Baiklah, Bola Bulu Kecilku, kemarilah dan biarkan aku memelukmu saat aku tidur!",
  ui_story_5037_50371201_41_dialog_content = "Cuit!",
  ui_story_5037_50371201_42_dialog_content = "Mendengkur... Mendengkur...",
  ui_story_5037_50371201_43_dialog_content = "(Dia sudah tidur? Itu Vic untukmu, kurasa...)",
  ui_story_5037_50371201_44_dialog_content = "(Yah, aku harus kembali bekerja sekarang.)",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371201_46_dialog_content = "(Baiklah, itu harus sesuai dengan jadwal! Saya pikir saya mulai memahami hal ini!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>Ketuk, ketuk!</color>",
  ui_story_5037_50371201_48_dialog_content = "(Hmm? Seseorang di pintu...)",
  ui_story_5037_50371201_49_dialog_content = "Halo?",
  ui_story_5037_50371201_50_dialog_content = "Hai, PlayerName! Ini aku, Fia!",
  ui_story_5037_50371201_51_dialog_content = "(F-Fia?!)",
  ui_story_5037_50371201_52_dialog_content = "(Oh tidak... Vic masih di sini!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>Ketuk, ketuk!</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "J-Tunggu sebentar!",
  ui_story_5037_50371201_56_dialog_content = "Vic! Bangun, Vic!",
  ui_story_5037_50371201_57_dialog_content = "Nnng... Haha... Hentikan itu, kamu Little Furball... Hahaha...",
  ui_story_5037_50371201_58_dialog_content = "Dia tidur lebih nyenyak daripada aku!",
  ui_story_5037_50371201_59_dialog_content = "(Sepertinya apa boleh buat... Aku harus menyembunyikannya untuk saat ini.)",
  ui_story_5037_50371201_60_dialog_content = "(Coba kulihat... Tumpukan majalah ini terlihat bagus. Aku akan menyembunyikannya di baliknya!)",
  ui_story_5037_50371201_61_dialog_content = "Datang, Fia!",
  ui_story_5037_50371201_62_dialog_content = "Apa yang membuatmu begitu lama?",
  ui_story_5037_50371201_63_dialog_content = "M-Maaf, aku hanya, uh... Membersihkan kamar!",
  ui_story_5037_50371201_64_dialog_content = "Yah, sepertinya tempat ini perlu dirapikan... Tumpukan majalah itu sebesar gunung!",
  ui_story_5037_50371201_65_dialog_content = "Aha...ha... Ngomong-ngomong, apa kau butuh sesuatu, Fia?",
  ui_story_5037_50371201_66_dialog_content = "Ya, sebenarnya... Apa kau melihat Tuan Vic di sekitar sini akhir-akhir ini?",
  ui_story_5037_50371201_67_dialog_content = "Eh, V-Vic? Tidak, tidak bisa mengatakan saya punya!",
  ui_story_5037_50371201_68_dialog_content = "Anda tidak mengatakan...?",
  ui_story_5037_50371201_69_dialog_content = "Saya telah membersihkan sepanjang hari hari ini, serta mengerjakan jadwal Goldie... Jadi tidak, saya belum melihat Vic sama sekali hari ini!",
  ui_story_5037_50371201_70_dialog_content = "Sigh ... Jika Anda mengatakan begitu. Sejujurnya aku terkejut dia tidak berlari ke arahmu lebih dulu...",
  ui_story_5037_50371201_71_dialog_content = "Kemana perginya tuanku yang tidak berguna itu...?",
  ui_story_5037_50371201_72_dialog_content = "Mungkin dia pergi ke suatu tempat untuk bersantai sebentar? Aku yakin dia akan segera kembali.",
  ui_story_5037_50371201_73_dialog_content = "Konsernya tinggal beberapa hari lagi... Aku tidak percaya pria itu masih berpikir dia bisa mengacau seperti ini.",
  ui_story_5037_50371201_74_dialog_content = "Saya akan memastikan untuk melatihnya ekstra keras ketika dia kembali ...",
  ui_story_5037_50371201_75_dialog_content = "A-Apa mungkin latihanmu jadi alasan dia kabur, Fia?",
  ui_story_5037_50371201_76_dialog_content = "Tidak apa-apa untuk mengikuti pelatihan dengan serius dan sebagainya... Tapi Anda harus ingat untuk menyeimbangkannya dengan istirahat juga.",
  ui_story_5037_50371201_77_dialog_content = "Kamu pikir?",
  ui_story_5037_50371201_78_dialog_content = "Kau tahu, aku berpikir untuk memberinya hari libur, agar dia bisa beristirahat...",
  ui_story_5037_50371201_79_dialog_content = "Tapi kemudian dia tiba-tiba menghilang padaku! Aku sudah mencari di seluruh Umbraton, tapi masih belum ada tanda-tanda keberadaannya.",
  ui_story_5037_50371201_80_dialog_content = "(Fia berencana untuk memberikan Vic hari libur selama ini? Jadi dia telah mengatur jadwalnya dengan benar.)",
  ui_story_5037_50371201_81_dialog_content = "Jangan khawatir, Fia. Saya akan meminta semua orang untuk membantu Anda mencarinya.",
  ui_story_5037_50371201_82_dialog_content = "Tentu, terima kasih. Aku akan terus mencari, kalau begitu.",
  ui_story_5037_50371201_83_dialog_content = "Tunggu sebentar... Bukankah itu...?",
  ui_story_5037_50371201_84_dialog_content = "(Sial! Dia melihat tumpukan majalah tempat Vic bersembunyi!)",
  ui_story_5037_50371201_85_dialog_content = "Oh! M-Maaf, itu hanya beberapa majalah yang aku buka-buka tadi! Aku akan membersihkannya sebentar—",
  ui_story_5037_50371201_86_dialog_content = "Itu terlihat agak lucu, bukan? Seolah-olah ada sesuatu yang terkubur di bawahnya ...",
  ui_story_5037_50371201_87_dialog_content = "Tidak, tunggu—!",
  ui_story_5037_50371201_88_dialog_content = "M-Master?!",
  ui_story_5037_50371201_89_dialog_content = "Mendengkur... Mendengkur...",
  ui_story_5037_50371201_90_dialog_content = "A-apa yang dia lakukan tidur di sini?!",
  ui_story_5037_50371201_91_dialog_content = "PlayerName... Apakah Anda berbohong kepada saya?",
  ui_story_5037_50371201_92_dialog_content = "aku, eh...",
  ui_story_5037_50371201_93_option_content = "Mengakui",
  ui_story_5037_50371201_94_dialog_content = "Baiklah, saya akui... Saya berbohong kepada Anda sebelumnya.",
  ui_story_5037_50371201_95_dialog_content = "Maaf…",
  ui_story_5037_50371201_96_dialog_content = "Tidak masalah, PlayerName. Saya tahu Anda tidak akan berbohong kepada saya dengan sengaja.",
  ui_story_5037_50371201_97_option_content = "Membuat sesuatu",
  ui_story_5037_50371201_98_dialog_content = "D-Dia pasti menyelinap ke sini sebelum aku tiba! Ya, pasti itu...",
  ui_story_5037_50371201_99_dialog_content = "Saya tahu Anda berbohong, PlayerName... Itu tertulis di seluruh wajahmu.",
  ui_story_5037_50371201_100_dialog_content = "Tapi saya pikir saya tahu apa yang terjadi di sini.",
  ui_story_5037_50371201_101_dialog_content = "Tuanku yang tidak berguna memohon padamu untuk membiarkan dia tinggal di sini, bukan?",
  ui_story_5037_50371201_102_dialog_content = "Nah, kebenarannya adalah ...",
  ui_story_5037_50371201_103_dialog_content = "Vic datang menemui saya pagi ini dan bertanya apakah dia bisa bersembunyi di sini dan beristirahat untuk hari itu.",
  ui_story_5037_50371201_104_dialog_content = "Dia mengatakan bahwa pelatihan idolanya telah membuatnya benar-benar kelelahan, dan dia pingsan tidak lama setelah tiba di sini.",
  ui_story_5037_50371201_105_dialog_content = "Tapi saya tidak mengerti! Mengapa dia melarikan diri dan menemukan Anda daripada berbicara dengan saya?",
  ui_story_5037_50371201_106_dialog_content = "Saya berencana untuk memberinya hari libur dan segalanya!",
  ui_story_5037_50371201_107_dialog_content = "Mengapa Anda tidak berbicara dengannya begitu dia bangun?",
  ui_story_5037_50371201_108_dialog_content = "Huh... Lupakan saja. Aku akan membiarkan dia beristirahat di sini untuk saat ini.",
  ui_story_5037_50371201_109_dialog_content = "Ingatkan dia untuk kembali berlatih begitu dia bangun, oke?",
  ui_story_5037_50371201_110_dialog_content = "Saya akan mengumpulkan beberapa tip dan trik untuk pelatihan idola untuk dibagikan kepada Anda nanti. Anggap itu sebagai caraku mengucapkan terima kasih karena telah mengawasi tuanku yang tidak berguna.",
  ui_story_5037_50371201_111_dialog_content = "Tentu, terima kasih!",
  ui_story_5037_50371201_112_dialog_content = "Oh, dan satu hal lagi... Jangan katakan padanya aku datang ke sini, mengerti?",
  ui_story_5037_50371201_113_dialog_content = "Tentu, tapi kenapa?",
  ui_story_5037_50371201_114_dialog_content = "Karena…",
  ui_story_5037_50371201_115_dialog_content = "<size=45>Guru benar-benar tidak dapat dipercaya!</size>",
  ui_story_5037_50371201_116_dialog_content = "Hah?!",
  ui_story_5037_50371201_117_dialog_content = "Jika Anda memberinya satu inci, dia akan mengambil satu mil sebelum Anda menyadarinya!",
  ui_story_5037_50371201_118_dialog_content = "Apakah itu latihan atau bahkan hanya melakukan hal-hal di sekitar rumah, dia akan menemukan lebih banyak alasan untuk mengendur jika dia tahu saya akan memberinya istirahat.",
  ui_story_5037_50371201_119_dialog_content = "Bagi orang-orang seperti dia, satu-satunya cara untuk membuat mereka bekerja sama adalah dengan bersikap tegas tanpa ampun!",
  ui_story_5037_50371201_120_dialog_content = "B-baiklah!",
  ui_story_5037_50371201_121_dialog_content = "Saya akan mengirimnya kembali untuk pelatihan segera setelah dia bangun!",
  ui_story_5037_50371301_1_dialog_content = "Mengapa ini harus terjadi sekarang, setiap saat?",
  ui_story_5037_50371301_2_dialog_content = "Yah, saya tidak benar-benar melihat masalah di sini ...",
  ui_story_5037_50371301_3_dialog_content = "Hanya Guru yang tidak berguna seperti Anda yang akan mengatakan itu pada saat seperti ini!",
  ui_story_5037_50371301_4_dialog_content = "Apakah situasi ini benar-benar buruk?",
  ui_story_5037_50371301_5_dialog_content = "Sayangnya, kurasa begitu…",
  ui_story_5037_50371301_6_dialog_content = "Kami dalam masalah serius sekarang, semuanya!",
  ui_story_5037_50371301_7_dialog_content = "Sekeras apapun kita berusaha... Goldie dan kemajuan Vic mulai melambat!",
  ui_story_5037_50371301_8_dialog_content = "Inilah yang mereka sebut \"dataran tinggi\" yang ditakuti!",
  ui_story_5037_50371301_9_dialog_content = "Fia dan saya datang dengan solusi unik untuk masalah kami sehingga kami dapat mewujudkan potensi penuh kami sebelum konser kelulusan kami!",
  ui_story_5037_50371301_10_dialog_content = "Kami akan mengganti produsen!",
  ui_story_5037_50371301_11_dialog_content = "Hah?!",
  ui_story_5037_50371301_12_dialog_content = "Betul sekali! Anda akan melatih master saya yang tidak berguna, PlayerName! Sementara itu, saya akan bekerja dengan Goldie dalam pelatihannya!",
  ui_story_5037_50371301_13_dialog_content = "Bersiaplah untuk program pertukaran pelatihan satu hari yang sangat menarik!",
  ui_story_5037_50371301_14_dialog_content = "Dengan produser baru, rejimen pelatihan baru, dan lingkungan baru untuk semua orang yang terlibat... Saya yakin kita akan menemukan inspirasi baru dan menarik untuk menembus dataran tinggi kita!",
  ui_story_5037_50371301_15_dialog_content = "Jadi apakah ini berarti... Saya akan bertanggung jawab untuk melatih Vic?",
  ui_story_5037_50371301_16_dialog_content = "Ooh! Kedengarannya seperti ide yang bagus untuk saya! Mungkin aku akhirnya bisa santai sebentar...",
  ui_story_5037_50371301_17_dialog_content = "Aduh, aduh, aduh! Itu kakiku, Fia!",
  ui_story_5037_50371301_18_dialog_content = "Kami juga memikirkan itu, Guru. Ini dia, PlayerName; Kyllo akan menjadi asisten Anda untuk pertukaran pelatihan.",
  ui_story_5037_50371301_19_dialog_content = "Lihat!",
  ui_story_5037_50371301_20_dialog_content = "Dan jangan khawatir, Kyllo tahu persis apa yang harus dilakukan jika Guru melakukan kesalahan atau menolak untuk bangun dari tempat tidur... Benar, Kyllo?",
  ui_story_5037_50371301_21_dialog_content = "Kamu benar-benar memikirkan segalanya, Fia...",
  ui_story_5037_50371301_22_dialog_content = "Baiklah, maka sudah beres!",
  ui_story_5037_50371301_23_dialog_content = "Lakukan yang terbaik untuk membantu Vic seperti yang Anda lakukan dengan saya, oke PlayerName?",
  ui_story_5037_50371301_24_dialog_content = "Saya tahu Anda akan melakukannya dengan baik!",
  ui_story_5037_50371301_25_dialog_content = "Tentu, serahkan padaku.",
  ui_story_5037_50371301_26_dialog_content = "Kami akan pergi, kalau begitu! Semoga beruntung, kalian berdua!",
  ui_story_5037_50371301_27_dialog_content = "Sekarang untuk istirahat yang memang layak—",
  ui_story_5037_50371301_28_dialog_content = "Aduh!!!",
  ui_story_5037_50371301_29_dialog_content = "L-Lepaskan, Kyllo! Kakiku bukan untuk dimakan!!!",
  ui_story_5037_50371301_30_dialog_content = "Lihat!",
  ui_story_5037_50371301_31_dialog_content = "Wow... Kyllo bahkan tahu saat kau berpikir untuk bermalas-malasan, Vic. Cukup mengesankan.",
  ui_story_5037_50371301_32_dialog_content = "Sigh ... Fia benar-benar membuatmu menentangku, bukan, Kyllo?",
  ui_story_5037_50371301_33_dialog_content = "Lagipula aku juga melakukannya untukmu! Membesarkanmu sejak lahir, memberimu cara untuk bertahan hidup di dunia...",
  ui_story_5037_50371301_34_dialog_content = "Aduh!!!",
  ui_story_5037_50371301_35_dialog_content = "Sepertinya Kyllo serius, Vic... Kita harus mulai latihan.",
  ui_story_5037_50371301_36_dialog_content = "*Menangis* Mengapa selalu aku yang terluka...?",
  ui_story_5037_50371301_37_dialog_content = "Jangan khawatir, Vik. Saya menyeimbangkan pekerjaan dan istirahat dengan pelatihan saya, jadi Anda harus baik-baik saja.",
  ui_story_5037_50371301_38_dialog_content = "Agenda pertama hari ini adalah latihan vokal.",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371301_40_dialog_content = "♪ Ah, musim semi telah tiba, dan semuanya menjadi hidup kembali! ♪",
  ui_story_5037_50371301_41_dialog_content = "♪ Hewan bangkit dari liang dan sarang mereka ♪",
  ui_story_5037_50371301_42_dialog_content = "♪ Di hutan dan padang rumput ♪",
  ui_story_5037_50371301_43_dialog_content = "Baiklah, kamu bisa istirahat sekarang, Vic.",
  ui_story_5037_50371301_44_dialog_content = "Akhirnya! Akhirnya waktu istirahat!",
  ui_story_5037_50371301_45_dialog_content = "lihat...",
  ui_story_5037_50371301_46_dialog_content = "Aku tidak bermalas-malasan kali ini, Kyllo! Ini adalah istirahat yang nyata dan jujur!",
  ui_story_5037_50371301_47_dialog_content = "Hei, Vik? Aku ingin bertanya... Apa yang membuatmu ingin menjadi idola?",
  ui_story_5037_50371301_48_dialog_content = "Hah? Anda salah paham.",
  ui_story_5037_50371301_49_dialog_content = "Hah?",
  ui_story_5037_50371301_50_dialog_content = "Pertama-tama, saya bukan idola. Saya, dan akan selalu menjadi, seorang ahli ekstrozoologi!",
  ui_story_5037_50371301_51_dialog_content = "Jadi apa yang kamu lakukan di kompetisi ?!",
  ui_story_5037_50371301_52_dialog_content = "Untuk menghasilkan uang, jelas!",
  ui_story_5037_50371301_53_dialog_content = "Anda hanya di dalamnya ... untuk hadiah uang?",
  ui_story_5037_50371301_54_dialog_content = "Maksudku, aku tahu Lady Sheol menawarkan hadiah besar, dan aku tahu situasi keuanganmu biasanya cukup suram...",
  ui_story_5037_50371301_55_dialog_content = "Tapi mengapa Fia terlibat juga?",
  ui_story_5037_50371301_56_dialog_content = "Itu adalah ide Fia sejak awal! Dia melihat poster untuk kontes dan memutuskan untuk menyeret saya ke dalam rencananya...",
  ui_story_5037_50371301_57_dialog_content = "Kami kehabisan dana untuk merawat binatang buas kami yang menakjubkan...",
  ui_story_5037_50371301_58_dialog_content = "Seberapa rendah?",
  ui_story_5037_50371301_59_dialog_content = "Yah... Aku memang harus berhutang sedikit hanya untuk membeli snack Bica dan Drakolion...",
  ui_story_5037_50371301_60_dialog_content = "Seburuk itu?!",
  ui_story_5037_50371301_61_dialog_content = "Tunggu... Bukankah sebaiknya Anda memberikan makanan ringan untuk menghemat uang jika keadaan seburuk itu?",
  ui_story_5037_50371301_62_dialog_content = "Tidak ada kesempatan!",
  ui_story_5037_50371301_63_dialog_content = "Hewan-hewan menakjubkan itu adalah teman-temanku; Saya tidak bisa hidup dengan diri saya sendiri jika mereka harus pergi tanpa kenyamanan mereka!",
  ui_story_5037_50371301_64_dialog_content = "Biasanya, Fia dan Shira menghasilkan uang dengan melakukan pekerjaan serabutan di sela-sela proyek penelitian mereka, jadi kami tidak perlu khawatir akan berutang.",
  ui_story_5037_50371301_65_dialog_content = "Tetapi selama ekspedisi terakhir Fia, dia menghabiskan banyak waktu untuk menyelidiki binatang langka yang menakjubkan, hanya untuk kembali tanpa hasil yang berarti.",
  ui_story_5037_50371301_66_dialog_content = "Dan begitu saja, tabungan kami mengering dan saya harus meminjam banyak uang!",
  ui_story_5037_50371301_67_dialog_content = "... Bolehkah saya bertanya apa yang Anda lakukan saat dia pergi?",
  ui_story_5037_50371301_68_dialog_content = "Saya? Yah, tentu saja, aku merawat binatang yang luar biasa dan menghemat energiku dengan banyak tidur siang...",
  ui_story_5037_50371301_69_dialog_content = "Sepertinya Anda sama sekali tidak berusaha membantu!",
  ui_story_5037_50371301_70_dialog_content = "Tiba-tiba, aku merasa seperti aku mengerti Fia dan perjuangan Shira lebih banyak lagi...",
  ui_story_5037_50371301_71_dialog_content = "Nah, saya di sini menghasilkan uang sekarang, bukan? Saya bahkan menyetujui semua pertunjukan konyol ini!",
  ui_story_5037_50371301_72_dialog_content = "Aku telah bekerja sangat keras sampai sekarang!",
  ui_story_5037_50371301_73_dialog_content = "Aku tahu, aku tahu... Sejujurnya, aku berharap kamu menyerah di tengah jalan dan mencoba mencari jalan keluar dari ini.",
  ui_story_5037_50371301_74_dialog_content = "Saya tidak akan pernah melakukan hal seperti itu! Terutama ketika datang untuk memastikan bahwa binatang yang menakjubkan memiliki cukup makanan!",
  ui_story_5037_50371301_75_dialog_content = "Saya akan melakukan apa saja untuk orang-orang itu.",
  ui_story_5037_50371301_76_dialog_content = "Dan itulah mengapa saya dengan senang hati akan meminjamkan Anda murid saya, untuk apa pun yang mungkin Anda butuhkan! Selama Anda membayar, tentu saja.",
  ui_story_5037_50371301_77_dialog_content = "Lupakan saja, Vic! Jangan mempersulit hidup mereka berdua!",
  ui_story_5037_50371301_78_dialog_content = "Aku bersumpah, kadang-kadang rasanya kamu lebih peduli pada Bola Bulu Kecilmu daripada pada Fia dan Shira...",
  ui_story_5037_50371301_79_dialog_content = "Anda sangat salah! Kata-kata tidak dapat menggambarkan betapa bangganya saya terhadap murid-murid yang saya sayangi!",
  ui_story_5037_50371301_80_dialog_content = "Saya tidak hanya mewariskan semua keahlian ekstrozoologi saya kepada mereka... Mereka juga tahu cara menghasilkan uang dan bertahan hidup di dunia!",
  ui_story_5037_50371301_81_dialog_content = "Selain itu, tak satu pun dari mereka yang takut melawan Eclipsites!",
  ui_story_5037_50371301_82_dialog_content = "Suatu hari nanti, saya akan dapat mempercayakan mereka dengan semua proyek penelitian saya pada binatang buas Astra yang menakjubkan...",
  ui_story_5037_50371301_83_dialog_content = "Apa yang akan anda lakukan selanjutnya? Lebih banyak tidur siang?",
  ui_story_5037_50371301_84_dialog_content = "Bukan ide yang buruk! Saya pasti akan mempertimbangkannya!",
  ui_story_5037_50371301_85_dialog_content = "Tapi sebelum itu, saya masih memiliki banyak pekerjaan penting yang harus dilakukan.",
  ui_story_5037_50371301_86_dialog_content = "Saya yakin ada benua lain seperti Astra di dunia kita.",
  ui_story_5037_50371301_87_dialog_content = "Saya ingin melihat mereka semua, dan mempelajari segala sesuatu yang perlu diketahui tentang binatang menakjubkan yang mendiami tanah mereka!",
  ui_story_5037_50371301_88_dialog_content = "Aku tidak menyangka kau memiliki mimpi yang begitu indah...",
  ui_story_5037_50371301_89_dialog_content = "Tapi tentu saja! Lagipula, aku—",
  ui_story_5037_50371301_90_dialog_content = "Aduh!!!",
  ui_story_5037_50371301_91_dialog_content = "Apa ide besarnya, Kyllo?!",
  ui_story_5037_50371301_92_dialog_content = "Sepertinya Kyllo mengingatkanmu bahwa istirahatmu sudah berakhir, Vic. Kembali ke pelatihan!",
  ui_story_5037_50371301_93_dialog_content = "Fia benar-benar memberi pengaruh buruk padamu, bukan begitu Kyllo? Kau bahkan lebih keras dari dia sekarang!",
  ui_story_5037_50371301_94_dialog_content = "Tapi sejak PlayerName bertanggung jawab atas pelatihan saya hari ini, mungkin dia dapat memperpanjang waktu istirahat saya beberapa menit lagi, bagaimana menurut Anda?",
  ui_story_5037_50371301_95_dialog_content = "Hmm…",
  ui_story_5037_50371301_96_dialog_content = "Ayo! Aku bahkan akan membiarkanmu mengelus Little Furball untuk sementara!",
  ui_story_5037_50371301_97_dialog_content = "Nah, ketika Anda mengatakannya seperti itu, saya kira kita bisa...",
  ui_story_5037_50371301_98_option_content = "Berlatih dua kali lebih keras!",
  ui_story_5037_50371301_99_option_content = "Berlatih sepuluh kali lebih keras!",
  ui_story_5037_50371301_100_dialog_content = "Saya mengembangkan program pelatihan untuk membantu Goldie menembus dataran tinggi potensial.",
  ui_story_5037_50371301_101_dialog_content = "Saya tidak pernah mempraktikkannya karena sepertinya terlalu sulit, tetapi saya akan mencobanya terlebih dahulu pada Anda!",
  ui_story_5037_50371301_102_dialog_content = "Apa?!",
  ui_story_5037_50371301_103_dialog_content = "Jangan khawatir, ini hanya sebentar. Dengan begitu, saya dapat membuat beberapa penyesuaian sebelum menampilkannya Goldie.",
  ui_story_5037_50371301_104_dialog_content = "Secara alami, ini juga akan membantu Anda meningkat.",
  ui_story_5037_50371301_105_dialog_content = "Kami tidak bisa membiarkan semua kerja keras Fia sia-sia, jadi kami akan melatih hati kami! Kamu siap, Vic?",
  ui_story_5037_50371301_106_dialog_content = "Tidaaaak—!!!",
  ui_story_5037_50371401_1_dialog_content = "Tim PlayerNamerapat darurat, ambil satu! Tiga, dua, satu... Aksi!",
  ui_story_5037_50371401_2_dialog_content = "D-Apakah kita benar-benar harus memfilmkan ini juga?",
  ui_story_5037_50371401_3_dialog_content = "Duh! Sutradara yang hebat tidak pernah menyia-nyiakan kesempatan yang berharga!",
  ui_story_5037_50371401_4_dialog_content = "Baiklah...",
  ui_story_5037_50371401_5_dialog_content = "Kalau begitu mari kita mulai Lokakarya Kursus Singkat Produser pertama kita.",
  ui_story_5037_50371401_6_dialog_content = "...",
  ui_story_5037_50371401_7_dialog_content = "(Ada buku-buku yang tersebar di sekitar kantor...)",
  ui_story_5037_50371401_8_dialog_content = "(Apakah Vice dan Carleen benar-benar membawa semua ini ke bengkel?)",
  ui_story_5037_50371401_9_dialog_content = "(Mereka terlihat sangat serius... Aku punya firasat buruk tentang ini...)",
  ui_story_5037_50371401_10_dialog_content = "Um, kenapa kalian berdua terlihat sangat serius...?",
  ui_story_5037_50371401_11_dialog_content = "Karena ini serius, PlayerName. Ini akan mempengaruhi apakah Anda bisa menjadi produser yang sukses atau tidak.",
  ui_story_5037_50371401_12_dialog_content = "Memang. Dalam hal kesuksesan Anda, kami tidak boleh gegabah.",
  ui_story_5037_50371401_13_dialog_content = "Terima kasih atas perhatiannya, tapi aku yang bertanggung jawab untuk itu, bukan kalian berdua...",
  ui_story_5037_50371401_14_dialog_content = "Apa yang kamu bicarakan? Kita rekan, bukan? Kami akan selalu berada di sini untuk mendukung Anda!",
  ui_story_5037_50371401_15_dialog_content = "Dan untuk membantu Anda memahami profesi baru Anda sebanyak mungkin, Vice dan saya melakukan penelitian kami sendiri.",
  ui_story_5037_50371401_16_dialog_content = "Betul sekali! Segala sesuatu yang ingin Anda pelajari, dari menjadi idola hingga menjadi produser, ada di buku ini!",
  ui_story_5037_50371401_17_dialog_content = "Mulai hari ini, ini akan menjadi tempat Lokakarya Kursus Singkat Produser kami berlangsung!",
  ui_story_5037_50371401_18_dialog_content = "Tunggu sebentar... Ini semua catatan dan kliping artikel?!",
  ui_story_5037_50371401_19_dialog_content = "Ya! Carleen pergi ke perpustakaan dan mencatat setiap buku yang berhubungan dengan aturan pelatihan untuk penyanyi dan penari.",
  ui_story_5037_50371401_20_dialog_content = "Sementara itu, saya membeli salinan setiap surat kabar yang dicetak selama beberapa tahun terakhir dan memotong semua yang berhubungan dengan idola dan produser!",
  ui_story_5037_50371401_21_dialog_content = "Itu mengesankan menakutkan ...",
  ui_story_5037_50371401_22_dialog_content = "Pasti butuh berhari-hari untuk membaca semua buku itu dan menulis catatan ini...",
  ui_story_5037_50371401_23_dialog_content = "Ya, saya mendapat bantuan dari Chloe dan Keating selama penelitian saya.",
  ui_story_5037_50371401_24_dialog_content = "Keduanya tahu lebih banyak tentang musik daripada saya, jadi mereka menulis sebagian besar catatan ini.",
  ui_story_5037_50371401_25_dialog_content = "Dan saya mendapat bantuan dari Brandy!",
  ui_story_5037_50371401_26_dialog_content = "Sebagai reporter profesional, dia sangat akrab dengan segala macam berita dan acara!",
  ui_story_5037_50371401_27_dialog_content = "Ya, semua ini tidak akan mungkin terjadi tanpa bantuan semua orang.",
  ui_story_5037_50371401_28_dialog_content = "Tidak bercanda...",
  ui_story_5037_50371401_29_dialog_content = "Sepertinya saya tidak bisa mengendur! Semua orang berharap banyak dariku!",
  ui_story_5037_50371401_30_dialog_content = "Lalu mari kita mulai.",
  ui_story_5037_50371401_31_dialog_content = "Urutan bisnis kami berikutnya adalah memutuskan rencana pelatihan untuk Anda, PlayerName!",
  ui_story_5037_50371401_32_dialog_content = "Rencana pelatihan?",
  ui_story_5037_50371401_33_dialog_content = "Ya. Kami mengembangkan dua rencana pelatihan yang berbeda untuk Anda. Kami akan membiarkan Anda memutuskan mana yang lebih cocok.",
  ui_story_5037_50371401_34_dialog_content = "Yang ini disebut \"Produser: Dari Pemula hingga Pakar\".",
  ui_story_5037_50371401_35_dialog_content = "Ini sangat tebal!!",
  ui_story_5037_50371401_36_dialog_content = "Ini berisi pengetahuan yang berkisar dalam kompleksitas dari tingkat dasar hingga profesional. Namun, materinya padat dan akan membutuhkan lebih banyak waktu untuk mempelajarinya.",
  ui_story_5037_50371401_37_dialog_content = "Dan yang lainnya...?",
  ui_story_5037_50371401_38_dialog_content = "Yang ini disebut \"Teknik Produser Lanjutan\". Ini mencakup berbagai teknik manajemen waktu yang digunakan oleh para sarjana terkenal sepanjang zaman.",
  ui_story_5037_50371401_39_dialog_content = "Namun, rencana ini membutuhkan pengetahuan dasar industri agar dapat dipahami dengan cukup baik untuk digunakan.",
  ui_story_5037_50371401_40_dialog_content = "Lanjutkan, PlayerName! Pilih paket yang menurut Anda paling cocok untuk Anda!",
  ui_story_5037_50371401_41_dialog_content = "Rencana yang paling cocok untukku...",
  ui_story_5037_50371401_42_dialog_content = "Yah, aku masih belum berpengalaman sebagai produser, jadi kurasa yang ini cukup—",
  ui_story_5037_50371401_43_option_content = "\"Produser: Dari Pemula hingga Pakar\"",
  ui_story_5037_50371401_44_dialog_content = "Jika saya ingin memulai dengan dasar-dasarnya, rencana ini harus menjadi taruhan teraman saya!",
  ui_story_5037_50371401_45_dialog_content = "Aku setuju.",
  ui_story_5037_50371401_46_dialog_content = "Maka itu diselesaikan! Mulai hari ini, Anda akan menggunakan ini untuk membantu Anda mempelajari cara menjadi produser profesional!",
  ui_story_5037_50371401_47_dialog_content = "Akan kucoba semampuku!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371401_49_dialog_content = "Tanggung jawab utama seorang produser... Melacak kemajuan, mengembangkan jadwal...",
  ui_story_5037_50371401_50_dialog_content = "Apa lagi? Ugh, sepertinya aku sudah lupa...",
  ui_story_5037_50371401_51_dialog_content = "Mengapa kau tidak beristirahat dulu?",
  ui_story_5037_50371401_52_dialog_content = "Anda sudah banyak menghafal. Langkah Anda selanjutnya adalah mencoba dan mempraktikkan konsep-konsep itu.",
  ui_story_5037_50371401_53_option_content = "\"Teknik Produser Lanjutan\"",
  ui_story_5037_50371401_54_dialog_content = "Saya sudah memutuskan untuk menantang diri sendiri dengan melakukan ini, jadi mari kita mulai dengan hal yang sulit!",
  ui_story_5037_50371401_55_dialog_content = "Apa kamu yakin?!",
  ui_story_5037_50371401_56_dialog_content = "Jika ini adalah bagaimana Anda ingin melanjutkan, maka kami akan melakukan yang terbaik untuk mendukung Anda.",
  ui_story_5037_50371401_57_dialog_content = "A-aku harus baik-baik saja!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371401_59_dialog_content = "Ini terlalu sulit!",
  ui_story_5037_50371401_60_dialog_content = "Saya setuju, ini sepertinya agak sulit ...",
  ui_story_5037_50371401_61_dialog_content = "Saya merasakan hal yang sama ketika saya merancang rencana ini... Banyak topik rumit yang terlibat, semuanya saling berhubungan dalam satu atau lain cara.",
  ui_story_5037_50371401_62_dialog_content = "Sepertinya saya harus mengambil langkah demi langkah jika saya ingin mempelajari hal-hal yang benar.",
  ui_story_5037_50371401_63_dialog_content = "Ini sudah larut, meskipun. Mari kita berhenti di sini untuk hari ini.",
  ui_story_5037_50371401_64_dialog_content = "Kerja bagus, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "Bagus.",
  ui_story_5037_50371401_66_dialog_content = "Seharusnya aku yang mengatakan itu! Saya yakin tidak mudah untuk mengumpulkan semua materi ini...",
  ui_story_5037_50371401_67_dialog_content = "Kami berteman baik, tidak perlu formalitas.",
  ui_story_5037_50371401_68_dialog_content = "Pulanglah dan istirahatlah, oke?",
  ui_story_5037_50371401_69_dialog_content = "Ya, sama untuk kalian berdua!",
  ui_story_5037_50371401_70_dialog_content = "Kami masih memiliki beberapa hal yang harus diperhatikan sebelum kami kembali, jadi tidak perlu menunggu kami.",
  ui_story_5037_50371401_71_dialog_content = "Hah? Kemana kamu pergi?",
  ui_story_5037_50371401_72_dialog_content = "Kami menyiapkan beberapa wawancara dengan beberapa penyanyi Aurorian di kota. Kami ingin belajar teknik menyanyi dari mereka.",
  ui_story_5037_50371401_73_dialog_content = "Meskipun gaya dan latar belakang mereka berbeda, mereka tetap harus memiliki beberapa saran untuk ditawarkan.",
  ui_story_5037_50371401_74_dialog_content = "Jika kita dapat menunjukkan teknik mereka dan mempresentasikannya Goldie, Saya yakin itu akan sangat berguna baginya.",
  ui_story_5037_50371401_75_dialog_content = "Tapi Anda sudah melakukan begitu banyak hanya untuk membantu saya!",
  ui_story_5037_50371401_76_dialog_content = "Aku merasa jika ada yang butuh istirahat, itu kalian berdua...",
  ui_story_5037_50371401_77_dialog_content = "Jangan khawatirkan kami! Saya masih merasa bersemangat dan siap untuk pergi!",
  ui_story_5037_50371401_78_dialog_content = "Ini adalah pengalaman baru dan menyenangkan bagi kami berdua.",
  ui_story_5037_50371401_79_dialog_content = "Mungkin karena inilah kami tidak merasa lelah, terlepas dari semua pekerjaan yang telah kami lakukan.",
  ui_story_5037_50371401_80_dialog_content = "Tidakkah terkadang kau merasa seperti itu, PlayerName?",
  ui_story_5037_50371401_81_dialog_content = "saya lakukan, ya ...",
  ui_story_5037_50371401_82_dialog_content = "Sejak saya mulai bekerja sebagai produser, saya tidak berpikir sehari pun berlalu tanpa bekerja dari fajar hingga senja.",
  ui_story_5037_50371401_83_dialog_content = "Tetapi karena semua tantangan baru yang saya hadapi setiap hari, saya tidak merasa lelah seperti seharusnya!",
  ui_story_5037_50371401_84_dialog_content = "Rasanya seperti ketika saya pertama kali keluar dari bawah tanah dan bertemu kalian.",
  ui_story_5037_50371401_85_dialog_content = "Meskipun Eclipsites mengejar kami selama berhari-hari, saya tidak pernah merasa lelah atau putus asa.",
  ui_story_5037_50371401_86_dialog_content = "Itulah jenis kegembiraan yang dibawa oleh petualangan baru!",
  ui_story_5037_50371401_87_dialog_content = "Ya!",
  ui_story_5037_50371401_88_dialog_content = "Tapi meski begitu, aku tidak bisa diam saja saat kalian berdua sangat sibuk!",
  ui_story_5037_50371401_89_dialog_content = "Hah?",
  ui_story_5037_50371401_90_dialog_content = "Mengapa demikian?",
  ui_story_5037_50371401_91_dialog_content = "Karena kita semua bersama-sama, begitulah yang selalu terjadi.",
  ui_story_5037_50371401_92_dialog_content = "Tidak peduli berapa lama perjalanan atau betapa berbahayanya petualangan itu, kami bertiga selalu bersatu.",
  ui_story_5037_50371401_93_dialog_content = "Jadi itu sebabnya aku ikut denganmu!",
  ui_story_5037_50371401_94_dialog_content = "Tapi—",
  ui_story_5037_50371401_95_dialog_content = "Jangan khawatirkan aku! Kami semua akan melakukan yang terbaik, seperti yang selalu kami lakukan.",
  ui_story_5037_50371401_96_dialog_content = "Tentu! Seperti yang selalu kita lakukan!",
  ui_story_5037_50371501_1_dialog_content = "Tim PlayerNamepertemuan menit terakhir! Tiga, dua, satu... Aksi!",
  ui_story_5037_50371501_2_dialog_content = "Maaf saya terlambat!",
  ui_story_5037_50371501_3_dialog_content = "Tidak apa-apa. Setidaknya kamu berhasil!",
  ui_story_5037_50371501_4_dialog_content = "Hah? Di mana Goldie?",
  ui_story_5037_50371501_5_dialog_content = "Dia pergi untuk berbicara dengan Lady Sheol tentang rencananya yang akan datang, jadi dia tidak akan kembali untuk sementara waktu.",
  ui_story_5037_50371501_6_dialog_content = "Ah, benarkah? Sayang sekali...",
  ui_story_5037_50371501_7_dialog_content = "Mengapa demikian?",
  ui_story_5037_50371501_8_dialog_content = "Kami ingin mengucapkan selamat kepada kalian berdua karena mengadakan konser debut yang sukses.",
  ui_story_5037_50371501_9_dialog_content = "Kami menyiapkan beberapa minuman dan suguhan untuk Anda dan Goldie dikembalikan.",
  ui_story_5037_50371501_10_dialog_content = "Wow terima kasih! Dan jangan khawatir, saya pasti akan membawa kembali untuk Goldie.",
  ui_story_5037_50371501_11_dialog_content = "Saya hanya berharap dia bisa berada di sini untuk menikmatinya sekarang ...",
  ui_story_5037_50371501_12_dialog_content = "Saya menghabiskan begitu banyak waktu untuk memanggang kue ini, jadi saya ingin semua orang mencobanya selagi masih segar.",
  ui_story_5037_50371501_13_dialog_content = "Butuh banyak percobaan untuk mengetahui cara memanggangnya tanpa membakarnya juga.",
  ui_story_5037_50371501_14_dialog_content = "Sepertinya kamu benar-benar mencurahkan isi hatimu untuk ini, Vice...",
  ui_story_5037_50371501_15_dialog_content = "(Kue-kue ini akan terasa enak jika dia mengerjakannya sekeras ini... Benar?)",
  ui_story_5037_50371501_16_dialog_content = "Waktu berlalu, bukan? Aku tidak percaya konser debut sudah berakhir.",
  ui_story_5037_50371501_17_dialog_content = "Ya... Kami juga mengadakan begitu banyak Lokakarya Kursus Singkat Produser!",
  ui_story_5037_50371501_18_dialog_content = "Ketika kami pertama kali mulai membantu PlayerName menjadi produser, kami semua sangat sibuk...",
  ui_story_5037_50371501_19_dialog_content = "Tetapi semua upaya kami mulai membuahkan hasil! PlayerName berhasil membantu Goldie menyelenggarakan konser debut yang spektakuler!",
  ui_story_5037_50371501_20_dialog_content = "Dia memang menjadi produser yang bisa diandalkan.",
  ui_story_5037_50371501_21_dialog_content = "Tidak bercanda! Anda benar-benar telah menunjukkan banyak kemajuan!",
  ui_story_5037_50371501_22_dialog_content = "Hehehe... Kalian berdua akan membuatku malu! Akulah yang seharusnya berterima kasih padamu!",
  ui_story_5037_50371501_23_dialog_content = "Selamat!",
  ui_story_5037_50371501_24_dialog_content = "Selamat, PlayerName.",
  ui_story_5037_50371501_25_dialog_content = "Terima kasih!",
  ui_story_5037_50371501_26_dialog_content = "Baik, sekarang mari kita mulai pesta ini!",
  ui_story_5037_50371501_27_dialog_content = "Lebih lama lagi dan tehnya akan menjadi dingin!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>Kresek...</color>",
  ui_story_5037_50371501_29_dialog_content = "... Apa salah satu dari kalian baru saja mendengar suara aneh?",
  ui_story_5037_50371501_30_dialog_content = "Hmm? Tidak, saya tidak berpikir begitu?",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>Gemerisik, gemerisik——</color>",
  ui_story_5037_50371501_32_dialog_content = "Itu dia lagi. Kedengarannya seperti itu datang dari dekat alat musik.",
  ui_story_5037_50371501_33_dialog_content = "Mungkinkah itu hanya angin?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>Gemerisik, gemerisik——</color>",
  ui_story_5037_50371501_35_dialog_content = "...",
  ui_story_5037_50371501_36_dialog_content = "Saya pikir ada sesuatu yang bersembunyi di balik drum ...",
  ui_story_5037_50371501_37_dialog_content = "Mungkinkah ... sebuah Eclipsite?",
  ui_story_5037_50371501_38_dialog_content = "Aku akan melihat lebih dekat.",
  ui_story_5037_50371501_39_dialog_content = "Ice Blossom—",
  ui_story_5037_50371501_40_dialog_content = "Lihat! Lo, lo, lo!",
  ui_story_5037_50371501_41_dialog_content = "Apa...? Itu Kylo!",
  ui_story_5037_50371501_42_dialog_content = "Tapi apa yang dilakukan Kyllo di sini? Dimana Fia?",
  ui_story_5037_50371501_43_dialog_content = "Lo... (Terjemahan: Fia mengirimku ke misi rahasia untuk memata-matai PlayerName dan yang lainnya...)",
  ui_story_5037_50371501_44_dialog_content = "Lo, lo! (Terjemahan: Tapi saya tidak berharap menemukan begitu banyak orang di sini sekaligus!)",
  ui_story_5037_50371501_45_dialog_content = "Lo... Lo! (Terjemahan: Sepertinya penyamaranku terbongkar... Aku harus mencari jalan keluar dari sini, cepat!)",
  ui_story_5037_50371501_46_dialog_content = "Anda tidak akan memata-matai kami... Apakah Anda?",
  ui_story_5037_50371501_47_dialog_content = "L-Lo, lo!!",
  ui_story_5037_50371501_48_dialog_content = "Saya pikir itu mencoba untuk menyangkalnya.",
  ui_story_5037_50371501_49_dialog_content = "Masuk akal ... Mengingat perilaku Kyllo yang biasa, dugaan saya adalah tersesat saat mencari sesuatu untuk dimakan.",
  ui_story_5037_50371501_50_dialog_content = "Apakah Anda mungkin menyelinap ke sini karena Anda juga tidak tahan dengan pelatihan Fia, Kyllo?",
  ui_story_5037_50371501_51_dialog_content = "Lihat!",
  ui_story_5037_50371501_52_dialog_content = "Saya cukup yakin itu ya.",
  ui_story_5037_50371501_53_dialog_content = "Pria kecil yang malang. Menjaga Vic dalam barisan selama latihannya setiap hari pasti melelahkan...",
  ui_story_5037_50371501_54_dialog_content = "lihat...",
  ui_story_5037_50371501_55_dialog_content = "Itu bisa beristirahat di sini untuk sementara waktu. Kami punya banyak makanan ringan untuk dibagikan.",
  ui_story_5037_50371501_56_dialog_content = "Ya saya setuju! Aku akan mengembalikannya ke Fia setelah kita selesai.",
  ui_story_5037_50371501_57_dialog_content = "Lihat! Lihat! (Terjemahan: Hebat, sepertinya mereka tidak tahu alasan sebenarnya saya ada di sini!)",
  ui_story_5037_50371501_58_dialog_content = "Lihat! (Terjemahan: Saya ingin tahu makanan ringan apa yang mereka bicarakan?)",
  ui_story_5037_50371501_59_dialog_content = "Fia menyebutkan bahwa Kyllo suka makan kerupuk hewan, bukan?",
  ui_story_5037_50371501_60_dialog_content = "Saya tidak tahu apakah kue saya terasa enak seperti kerupuk yang Anda suka, tapi ...",
  ui_story_5037_50371501_61_dialog_content = "(Uh-oh... aku ingat perasaan ini!)",
  ui_story_5037_50371501_62_dialog_content = "(Itu sama seperti sebelumnya!)",
  ui_story_5037_50371501_63_dialog_content = "Lihat! (Terjemahan: T-Tunggu sebentar! Apakah ini bisa dimakan ?!)",
  ui_story_5037_50371501_64_dialog_content = "Ini, Kylo! Cobalah salah satu kue saya yang baru dipanggang!",
  ui_story_5037_50371501_65_dialog_content = "Saya tahu mereka tidak secantik yang ada di toko roti Lumopolis, tapi resepnya persis sama!",
  ui_story_5037_50371501_66_dialog_content = "Lihat! Lihat! (Terjemahan: S-Jauhi aku!)",
  ui_story_5037_50371501_67_dialog_content = "Katakan, ahhh—",
  ui_story_5037_50371501_68_dialog_content = "Lihat!!!",
  ui_story_5037_50371501_69_dialog_content = "Kyllo melarikan diri!",
  ui_story_5037_50371501_70_dialog_content = "Itu berlari menuju tumpukan buku kami!",
  ui_story_5037_50371501_71_dialog_content = "Raih sebelum membuat mereka berantakan!",
  ui_story_5037_50371501_72_dialog_content = "Datang ke sini, Kylo!",
  ui_story_5037_50371501_73_dialog_content = "Lihat!!!",
  ui_story_5037_50371501_74_dialog_content = "(Sial! Kyllo mencoba masuk ke tumpukan buku!)",
  ui_story_5037_50371501_75_option_content = "Lindungi buku-buku profesional",
  ui_story_5037_50371501_76_option_content = "Lindungi majalah",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>Memukul!</color>",
  ui_story_5037_50371501_78_dialog_content = "Aduh—!",
  ui_story_5037_50371501_79_dialog_content = "<size=45>Aduh!!!</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName?!",
  ui_story_5037_50371501_81_dialog_content = "Aku baik-baik saja... Itu hanya sedikit sakit, itu saja...",
  ui_story_5037_50371501_82_dialog_content = "lihat...",
  ui_story_5037_50371501_83_dialog_content = "Lo, lo, lo!",
  ui_story_5037_50371501_84_dialog_content = "Ini berjalan sangat cepat!",
  ui_story_5037_50371501_85_dialog_content = "Apakah buku-bukunya baik-baik saja?",
  ui_story_5037_50371501_86_dialog_content = "*Batuk* Ya... Yah, sebagian dari mereka...",
  ui_story_5037_50371501_87_dialog_content = "Saya berhasil menyimpan beberapa catatan dan kliping kami juga.",
  ui_story_5037_50371501_88_dialog_content = "Sisanya tampaknya benar-benar basah kuyup...",
  ui_story_5037_50371501_89_dialog_content = "Yah, tidak ada waktu untuk disia-siakan. Kita harus menghapus semua buku basah terlebih dahulu.",
  ui_story_5037_50371501_90_dialog_content = "Satu, dua...",
  ui_story_5037_50371501_91_dialog_content = "Saya pikir kita masih bisa membacanya jika kita berhasil mengeringkannya terlebih dahulu.",
  ui_story_5037_50371501_92_dialog_content = "Ini, di sisi lain... Tinta benar-benar tercoreng, jadi kita tidak bisa berbuat apa-apa untuk menyelamatkannya.",
  ui_story_5037_50371501_93_dialog_content = "Saya pikir ada beberapa buku di sana yang kami pinjam dari orang lain!",
  ui_story_5037_50371501_94_dialog_content = "Itu tidak bisa membantu. Kami harus memilahnya, mengembalikannya ke pemiliknya, dan menawarkan permintaan maaf kami serta kompensasi.",
  ui_story_5037_50371501_95_dialog_content = "Kira kita benar-benar tidak punya pilihan, ya?",
  ui_story_5037_50371501_96_dialog_content = "Saya tidak tahu apakah saya memiliki cukup Nightium untuk menutupi kerusakan, meskipun ...",
  ui_story_5037_50371501_97_dialog_content = "Aku juga bisa ikut.",
  ui_story_5037_50371501_98_dialog_content = "Begitu juga aku. Lagi pula, aku tidak bisa menghentikan Kyllo, jadi aku juga harus disalahkan.",
  ui_story_5037_50371501_99_dialog_content = "Jangan khawatir, PlayerName! Kami tidak akan membiarkan Anda kering!",
  ui_story_5037_50371501_100_dialog_content = "Terima kasih, Wakil. Terima kasih, Carleen.",
  ui_story_5037_50371501_101_dialog_content = "Itu hanya menyisakan satu hal terakhir yang harus dilakukan.",
  ui_story_5037_50371501_102_dialog_content = "Kita perlu menemukan Fia, dan pastikan dia mendisiplinkan Kyllo dengan benar.",
  ui_story_5037_50371601_1_dialog_content = "Tim PlayerNamepertemuan terakhir! Tiga, dua, satu... Aksi!",
  ui_story_5037_50371601_2_dialog_content = "Pertemuan terakhir, ya? Wow, waktu pasti terbang ...",
  ui_story_5037_50371601_3_dialog_content = "Saya tau? Ini akan menjadi waktu untuk konser kelulusan hanya dalam beberapa hari!",
  ui_story_5037_50371601_4_dialog_content = "Sepertinya baru kemarin kami memindahkan semua buku itu ke sini untuk mempersiapkan Lokakarya Kursus Singkat Produser pertama kami.",
  ui_story_5037_50371601_5_dialog_content = "Jadi apa rencananya hari ini?",
  ui_story_5037_50371601_6_dialog_content = "Kami hanya memiliki satu tugas penting untuk hari ini... dan itu adalah membersihkan tempat!",
  ui_story_5037_50371601_7_dialog_content = "Setelah menyelesaikan setiap bagian dari rencana pelatihan Anda, Anda telah menjadi produser yang berbakat dan terhormat, PlayerName!",
  ui_story_5037_50371601_8_dialog_content = "Yang berarti Lokakarya Kursus Singkat Produser kami telah resmi berakhir!",
  ui_story_5037_50371601_9_dialog_content = "Memang, kita harus mengumpulkan semua buku dan materi kita dan mengembalikannya ke tempat yang semestinya hari ini.",
  ui_story_5037_50371601_10_dialog_content = "Dengan begitu, kita juga bisa mengembalikan semua bahan yang kita pinjam dari orang lain untuk keperluan bengkel.",
  ui_story_5037_50371601_11_dialog_content = "Saya mengerti. Aku juga akan membantu!",
  ui_story_5037_50371601_12_dialog_content = "Ayo bereskan semuanya secepat mungkin!",
  ui_story_5037_50371601_13_dialog_content = "Ya!",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371601_15_dialog_content = "Di mana saya harus meletakkan salinan \"Membentuk Kebiasaan Baik: Panduan Pemula\" ini?",
  ui_story_5037_50371601_16_dialog_content = "Ini, berikan padaku.",
  ui_story_5037_50371601_17_dialog_content = "Petugas Vivian berbaik hati membiarkan kami meminjamnya. Dia bilang itu akan sempurna untuk latihanmu!",
  ui_story_5037_50371601_18_dialog_content = "Dia sendiri belajar manajemen waktu yang lebih baik setelah membacanya.",
  ui_story_5037_50371601_19_dialog_content = "Dia benar, ada banyak informasi berguna di dalamnya!",
  ui_story_5037_50371601_20_dialog_content = "PlayerName? Bisakah Anda memberi saya salinan \"300 Keterampilan Paduan Suara Penting\" di samping Anda?",
  ui_story_5037_50371601_21_dialog_content = "Tentu, ini dia.",
  ui_story_5037_50371601_22_dialog_content = "Biar kutebak... Keating meminjamkan buku itu pada kita, bukan?",
  ui_story_5037_50371601_23_dialog_content = "Kok kau tahu?",
  ui_story_5037_50371601_24_dialog_content = "Karena meskipun sampulnya terlihat sangat bersih... Ada berbagai macam coretan dan gambar di setiap nomor halaman.",
  ui_story_5037_50371601_25_dialog_content = "Bahkan ada gambar kasar saya di salah satu halaman, di mana mereka menggambar lingkaran hitam besar di sekitar mata saya!",
  ui_story_5037_50371601_26_dialog_content = "... Pfft.",
  ui_story_5037_50371601_27_dialog_content = "Kedengarannya seperti sesuatu yang akan mereka lakukan, ya.",
  ui_story_5037_50371601_28_dialog_content = "Jika itu benar-benar mengganggu Anda, saya akan meminta mereka menghapus semua gambar mereka di buku ini.",
  ui_story_5037_50371601_29_dialog_content = "Itu tidak benar-benar diperlukan ...",
  ui_story_5037_50371601_30_dialog_content = "Jika Anda membuat mereka melakukan itu, saya yakin mereka akan menemukan cara yang lebih buruk untuk mengolok-olok saya.",
  ui_story_5037_50371601_31_dialog_content = "Biarkan saja.",
  ui_story_5037_50371601_32_dialog_content = "Anak-anak itu benar-benar tahu bagaimana membuat semua orang gelisah.",
  ui_story_5037_50371601_33_dialog_content = "Sepertinya kita hampir selesai di sini, kan?",
  ui_story_5037_50371601_34_dialog_content = "Ya! Semuanya beres!",
  ui_story_5037_50371601_35_dialog_content = "Selain semua buku yang kami gunakan, ada juga tumpukan catatan yang sangat banyak.",
  ui_story_5037_50371601_36_dialog_content = "Kami mengumpulkan semua catatan ini selama beberapa hari terakhir.",
  ui_story_5037_50371601_37_dialog_content = "Benar, setiap halaman yang ditutupi catatan adalah bukti dari semua kerja keras kami!",
  ui_story_5037_50371601_38_dialog_content = "Ini benar-benar tumpukan besar, ya?",
  ui_story_5037_50371601_39_dialog_content = "Rasanya tidak seperti itu saat kami mengambilnya ...",
  ui_story_5037_50371601_40_dialog_content = "tapi saya tidak percaya kami membuat begitu banyak catatan!",
  ui_story_5037_50371601_41_dialog_content = "Ini adalah buah dari pengetahuan yang Anda peroleh.",
  ui_story_5037_50371601_42_dialog_content = "Harus kukatakan, sudah lama sejak aku menulis catatan sebanyak ini... Rasanya sangat mirip dengan waktu kita di akademi!",
  ui_story_5037_50371601_43_dialog_content = "Pergi ke kelas, membuat catatan, makan siang bersama... Itu adalah hari-hari yang damai, bukan, Carleen?",
  ui_story_5037_50371601_44_dialog_content = "Kecuali saat kita akan menghadapi ujian, tentu saja...",
  ui_story_5037_50371601_45_dialog_content = "Kehidupan siswa, ya? Cukup sulit bagi saya untuk membayangkannya.",
  ui_story_5037_50371601_46_dialog_content = "Lagi pula, saya belum pernah bersekolah sebelumnya, jadi saya tidak tahu seperti apa rasanya.",
  ui_story_5037_50371601_47_dialog_content = "Apakah Soroz selalu menjadi gurumu, PlayerName?",
  ui_story_5037_50371601_48_dialog_content = "Dalam hal ini, akan sangat sulit membayangkan belajar dengan orang lain.",
  ui_story_5037_50371601_49_dialog_content = "Ini sangat mirip dengan petualangan kita bersama. Minus Eclipsites, tentu saja.",
  ui_story_5037_50371601_50_dialog_content = "Kita harus mengunjungi Dawn Akademi saat kita mendapat kesempatan.",
  ui_story_5037_50371601_51_dialog_content = "Anda bisa merasakan hidup sebagai mahasiswa di sana, sama seperti Anda menjalani hidup sebagai produser di sini.",
  ui_story_5037_50371601_52_dialog_content = "Tentu, tapi... mungkin aku bisa melewatkan ujian.",
  ui_story_5037_50371601_53_dialog_content = "Kami sangat sibuk akhir-akhir ini, aku mulai merasa sedikit lelah...",
  ui_story_5037_50371601_54_dialog_content = "Saya tidak ingin berpikir tentang kontes atau ujian lagi. Saat ini, yang paling saya inginkan adalah istirahat yang layak!",
  ui_story_5037_50371601_55_option_content = "Tapi aku belum bisa istirahat!",
  ui_story_5037_50371601_56_dialog_content = "Saya masih memiliki banyak pekerjaan yang harus dilakukan untuk konser terakhir.",
  ui_story_5037_50371601_57_dialog_content = "Jika saya mulai santai sekarang, saya tidak akan bisa menyelesaikan apa yang saya mulai!",
  ui_story_5037_50371601_58_dialog_content = "Anda selalu menghadapi pengalaman baru dengan antusiasme seperti itu!",
  ui_story_5037_50371601_59_dialog_content = "Yah, ya... Lagipula, aku menghabiskan 17 tahun di bawah tanah...",
  ui_story_5037_50371601_60_dialog_content = "Jadi Anda ingin mengalami semuanya sendiri, ya?",
  ui_story_5037_50371601_61_dialog_content = "Benar sekali!",
  ui_story_5037_50371601_62_option_content = "Aku hanya ingin berbaring sekarang...",
  ui_story_5037_50371601_63_dialog_content = "Segalanya terasa begitu baru dan menyenangkan ketika saya pertama kali menjadi produser, tapi perlahan saya mulai terbiasa.",
  ui_story_5037_50371601_64_dialog_content = "Melakukan pekerjaan yang persis sama, hari demi hari... Aku sudah sangat terbiasa dengan pekerjaan itu, tapi terkadang aku merasa sedikit bosan...",
  ui_story_5037_50371601_65_dialog_content = "Aku tahu persis bagaimana perasaanmu...",
  ui_story_5037_50371601_66_dialog_content = "Bahkan hal yang paling menarik pun menjadi monoton setelah beberapa saat.",
  ui_story_5037_50371601_67_dialog_content = "Itulah sebabnya kita harus selalu menemukan cara baru untuk menantang diri kita sendiri.",
  ui_story_5037_50371601_68_dialog_content = "Namun, ini telah menjadi pengalaman yang berharga!",
  ui_story_5037_50371601_69_dialog_content = "Aku harus membantu Goldie mengadakan konser, dan saya harus belajar bersama kalian berdua.",
  ui_story_5037_50371601_70_dialog_content = "Saya tidak bisa meminta cara yang lebih baik untuk belajar dan tumbuh sebagai pribadi!",
  ui_story_5037_50371601_71_dialog_content = "Anda mungkin bisa membuat nama untuk diri sendiri jika Anda tinggal di sini dan tetap menjadi produser.",
  ui_story_5037_50371601_72_dialog_content = "Mana yang lebih kamu sukai? Menjadi produser atau menjadi petualang?",
  ui_story_5037_50371601_73_dialog_content = "Apakah kamu bercanda? Jawaban saya harus jelas seperti siang hari!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "Berpetualang dengan kalian adalah hal yang paling membuatku bahagia!",
  ui_story_5037_50371701_1_dialog_content = "Florin? Aku tidak mengharapkanmu di sini! Selamat datang, selamat datang!",
  ui_story_5037_50371701_2_dialog_content = "Jika Anda datang untuk mendengar Goldie bernyanyi, saya khawatir saya harus mengecewakan Anda. Konsernya tinggal beberapa hari lagi, dan dia masih di tengah pelatihan.",
  ui_story_5037_50371701_3_dialog_content = "Saya di sini bukan untuk menghadiri konser.",
  ui_story_5037_50371701_4_dialog_content = "Hah?",
  ui_story_5037_50371701_5_dialog_content = "Saya di sini untuk memberikan bantuan saya.",
  ui_story_5037_50371701_6_dialog_content = "Kudengar kau mencoba profesi baru? Seorang produser, saya percaya mereka menyebutnya.",
  ui_story_5037_50371701_7_dialog_content = "Aku datang sebagai temanmu untuk melihat bagaimana keadaanmu.",
  ui_story_5037_50371701_8_dialog_content = "Katakan padaku, Caelestite terakhir... Apakah ada yang bisa kulakukan untuk membantumu?",
  ui_story_5037_50371701_9_dialog_content = "Aku rasa tidak...",
  ui_story_5037_50371701_10_dialog_content = "Benarkah...?",
  ui_story_5037_50371701_11_dialog_content = "(Hah? Kenapa Florine terlihat sangat kecewa?)",
  ui_story_5037_50371701_12_dialog_content = "(Apakah karena aku tidak membutuhkan bantuannya sekarang...?)",
  ui_story_5037_50371701_13_dialog_content = "T-Tunggu! Ada sesuatu yang bisa kubantu!",
  ui_story_5037_50371701_14_dialog_content = "Ada apa?",
  ui_story_5037_50371701_15_dialog_content = "(Apa yang harus saya katakan padanya?)",
  ui_story_5037_50371701_16_dialog_content = "(Aku tidak ingin mengecewakannya, tapi aku juga tidak ingin mengganggunya...)",
  ui_story_5037_50371701_17_dialog_content = "(Tunggu, bukankah dia bilang dia pernah menjadi ketua OSIS? Kalau begitu...)",
  ui_story_5037_50371701_18_option_content = "Minta bantuan musik",
  ui_story_5037_50371701_19_dialog_content = "Goldie sedang dalam proses menulis lagu baru, tapi iringannya masih kurang. Mungkin Anda bisa membantunya dengan itu?",
  ui_story_5037_50371701_20_dialog_content = "Iringan musik? Maaf, tapi saya tidak terlalu paham dengan topiknya...",
  ui_story_5037_50371701_21_dialog_content = "Meskipun saya penggemar opera, jadi saya tahu sedikit. Aku akan melakukan yang terbaik!",
  ui_story_5037_50371701_22_dialog_content = "Bagus, terima kasih banyak!",
  ui_story_5037_50371701_23_option_content = "Minta bantuan untuk belajar",
  ui_story_5037_50371701_24_dialog_content = "Goldie ingin saya memberikan kritik konstruktif atas penampilannya, tetapi saya tidak begitu mengerti apa yang dia cari.",
  ui_story_5037_50371701_25_dialog_content = "Saya perlu belajar sebanyak mungkin tentang musik secepat mungkin, jadi saya bisa memberikan umpan balik yang dia butuhkan. Ada saran?",
  ui_story_5037_50371701_26_dialog_content = "Anda telah datang ke orang yang tepat! Saya tahu semua yang perlu diketahui tentang belajar mandiri yang sistematis, dan saya sangat ingin berbagi pengetahuan saya dengan Anda!",
  ui_story_5037_50371701_27_dialog_content = "Besar! Aku mengandalkan mu!",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>Suatu saat nanti</color>",
  ui_story_5037_50371701_29_dialog_content = "... Di sana! Saya telah berbagi semua yang saya tahu dengan Anda.",
  ui_story_5037_50371701_30_dialog_content = "T-Tunggu, aku masih belum menyelesaikan semuanya.",
  ui_story_5037_50371701_31_dialog_content = "Coba saya cek catatan saya...",
  ui_story_5037_50371701_32_dialog_content = "Anda menulis catatan yang sangat rinci, bukan? Itu kebiasaan yang sangat baik.",
  ui_story_5037_50371701_33_dialog_content = "Saya selalu lupa banyak hal, jadi saya membuat banyak catatan ketika saya belajar.",
  ui_story_5037_50371701_34_dialog_content = "Itu sebabnya saya menyimpan buku harian. Saya tidak pernah ingin melupakan semua hal penting yang terjadi dalam hidup saya, jadi saya menuliskannya juga.",
  ui_story_5037_50371701_35_dialog_content = "Saya kira bagi saya, buku catatan yang bagus bernilai ribuan kenangan.",
  ui_story_5037_50371701_36_dialog_content = "Maka saya berharap yang terbaik untuk Anda, Caelestite terakhir.",
  ui_story_5037_50371701_37_dialog_content = "Kerja keras dan dedikasi Anda akan membuka jalan menuju kesuksesan Anda.",
  ui_story_5037_50371701_38_dialog_content = "Terima kasih atas kata-kata penyemangatnya, Florine!",
  ui_story_5037_50371701_39_dialog_content = "Ini bukan sekadar kata-kata penyemangat.",
  ui_story_5037_50371701_40_dialog_content = "Mereka tidak...?",
  ui_story_5037_50371701_41_dialog_content = "Itu adalah puncak dari pengalaman saya sendiri sebagai siswa juga.",
  ui_story_5037_50371701_42_dialog_content = "Kerja keras dan dedikasi adalah cara orang biasa mencapai hal yang luar biasa... Jadi, jangan pernah meremehkan nilai kerja keras.",
  ui_story_5037_50371701_43_dialog_content = "Saya mengerti! Dan saya tidak akan!",
  ui_story_5037_50371701_44_dialog_content = "Ngomong-ngomong, kenapa kamu masih memakai semua barang jaman dulu itu? Apakah Anda tidak ingin mengubahnya?",
  ui_story_5037_50371701_45_dialog_content = "Tidak terlalu. Ini sangat ringan dan nyaman. Dan itu mengingatkanku pada masa-masa sekolahku.",
  ui_story_5037_50371701_46_dialog_content = "Memakainya berarti saya selalu diingatkan...",
  ui_story_5037_50371701_47_dialog_content = "menjadi lebih seperti mahasiswa. Untuk menjadi rendah hati, dan memiliki integritas. Selalu berusaha untuk perbaikan, dan menjadi individu yang bertanggung jawab.",
  ui_story_5037_50371701_48_dialog_content = "Anda bisa mencoba memakainya juga, PlayerName. Saya yakin itu akan menjadi inspirasi.",
  ui_story_5037_50371701_49_dialog_content = "Umm... Saya pikir saya akan lulus!",
  ui_story_5037_50371701_50_dialog_content = "Saya jauh lebih nyaman dengan pakaian saya sendiri.",
  ui_story_5037_50371701_51_dialog_content = "Kalau begitu, seperti yang Anda inginkan.",
  ui_story_5037_50371701_52_dialog_content = "Kamu akan baik-baik saja selama kamu selalu melakukan yang terbaik dan jangan malas.",
  ui_story_5037_50371701_53_dialog_content = "Yakin kamu tidak terlalu keras pada dirimu sendiri, Florine?",
  ui_story_5037_50371701_54_dialog_content = "Keras pada diriku sendiri? Saya kira tidak demikian.",
  ui_story_5037_50371701_55_dialog_content = "Saya hanya ingin bisa membantu semua orang, seperti Nona Hedy.",
  ui_story_5037_50371701_56_dialog_content = "Selama aku bisa diandalkan seperti dia, aku akan melakukan yang terbaik, tidak peduli kesulitan yang mungkin aku hadapi.",
  ui_story_5037_50371701_57_dialog_content = "Saya masih memiliki ruang untuk berkembang.",
  ui_story_5037_50371701_58_dialog_content = "Saya pikir Anda luar biasa seperti Anda sekarang!",
  ui_story_5037_50371701_59_dialog_content = "Mampu bertahan dengan gigih sepanjang waktu sungguh mengesankan.",
  ui_story_5037_50371701_60_dialog_content = "Saya ingin menjadi lebih seperti Anda.",
  ui_story_5037_50371701_61_dialog_content = "Baiklah, mari kita berdua bekerja keras untuk menjadi seperti yang kita inginkan.",
  ui_story_5037_50371701_62_dialog_content = "Setuju!",
  ui_story_5037_50371701_63_dialog_content = "Oh, satu hal lagi. Mengingatkan Goldie untuk tetap terhidrasi dan menjaga dirinya sendiri.",
  ui_story_5037_50371701_64_dialog_content = "Bernyanyi terlalu lama membuat tenggorokan tegang, jadi penting untuk minum banyak air untuk menghindari iritasi.",
  ui_story_5037_50371701_65_dialog_content = "Menari juga merupakan olahraga yang cukup kuat, jadi hidrasi teratur sangat penting.",
  ui_story_5037_50371701_66_dialog_content = "Jangan khawatir. Aku pasti akan mengingatkannya.",
  ui_story_5037_50371701_67_dialog_content = "Jangan lupa jaga diri juga ya Caelestite yang terakhir.",
  ui_story_5037_50371701_68_dialog_content = "Tidak peduli seberapa sibuknya pekerjaan, Anda harus menemukan waktu untuk mengurus diri sendiri.",
  ui_story_5037_50371701_69_dialog_content = "Baiklah…",
  ui_story_5037_50371701_70_dialog_content = "Semoga Dewa Cahaya memberkati Anda, dan memuluskan jalan usaha masa depan Anda.",
  ui_story_5037_50371701_71_dialog_content = "Iya!",
  ui_story_5037_50371801_1_dialog_content = "Oh, aku tidak boleh melewatkan ini! Cellulo, ambil gambar Goldie yang bagus, PlayerName, dan saya!",
  ui_story_5037_50371801_2_dialog_content = "3... 2... 1... Aksi!",
  ui_story_5037_50371801_3_dialog_content = "Hai kawan! Ini direktur pemberani Anda, Lilica!",
  ui_story_5037_50371801_4_dialog_content = "Hari ini saya berperan sebagai mentor dalam kolaborasi dengan Goldie dan produsernya PlayerName.",
  ui_story_5037_50371801_5_dialog_content = "Kami akan menjalani beberapa pelatihan seni pertunjukan!",
  ui_story_5037_50371801_6_dialog_content = "Sapa orang-orang yang menonton di rumah, Goldie, PlayerName!",
  ui_story_5037_50371801_7_dialog_content = "Hai untuk semua penggemarku yang menggemaskan di luar sana!",
  ui_story_5037_50371801_8_dialog_content = "H-hai, semuanya...",
  ui_story_5037_50371801_9_dialog_content = "(Mengetahui bahwa penampilan saya akan direkam dan ditonton oleh begitu banyak orang benar-benar mengerikan...)",
  ui_story_5037_50371801_10_dialog_content = "Saya menyiapkan permainan khusus untuk membantu kami dalam latihan hari ini!",
  ui_story_5037_50371801_11_dialog_content = "Permainan? Luar biasa, saya suka game!",
  ui_story_5037_50371801_12_dialog_content = "Permainan macam apa itu?",
  ui_story_5037_50371801_13_dialog_content = "Ini disebut \"Charades.\"",
  ui_story_5037_50371801_14_dialog_content = "Kostum, riasan, garis, dan ekspresi seseorang semuanya memengaruhi hasil penampilan seseorang.",
  ui_story_5037_50371801_15_dialog_content = "Apa yang dapat dilakukan seorang aktor adalah memperdalam pemahaman mereka tentang karakter tersebut sebanyak mungkin dan memastikan sikap dan dialog mereka sesuai!",
  ui_story_5037_50371801_16_dialog_content = "Kedengarannya benar!",
  ui_story_5037_50371801_17_dialog_content = "Saya mengamati banyak teman Anda dan menulis beberapa baris berdasarkan karakteristik masing-masing.",
  ui_story_5037_50371801_18_dialog_content = "Selama pertandingan, Goldie akan memilih salah satu dari mereka dan meniru tingkah laku mereka.",
  ui_story_5037_50371801_19_dialog_content = "Kemudian, PlayerName, Anda akan menebak siapa Goldie sedang meniru!",
  ui_story_5037_50371801_20_dialog_content = "Penampilannya akan dianggap sukses jika Anda berhasil melakukannya dengan benar!",
  ui_story_5037_50371801_21_dialog_content = "Terdengar menyenangkan!",
  ui_story_5037_50371801_22_dialog_content = "Oke!",
  ui_story_5037_50371801_23_dialog_content = "Karena Goldie adalah pendatang baru, kami akan membuat pilihan ganda. Anda hanya perlu memilih jawaban yang tepat.",
  ui_story_5037_50371801_24_dialog_content = "Bagaimanapun, saya yakin itu tidak akan terlalu sulit, jadi mari bersenang-senang!",
  ui_story_5037_50371801_25_dialog_content = "Baiklah!",
  ui_story_5037_50371801_26_dialog_content = "Tunggu saja penampilan saya!",
  ui_story_5037_50371801_27_dialog_content = "Goldie, pilih seseorang dari daftar ini. Maka panggung adalah milikmu.",
  ui_story_5037_50371801_28_dialog_content = "Oke... Yang ini!",
  ui_story_5037_50371801_29_dialog_content = "Aku akan mulai, PlayerName.",
  ui_story_5037_50371801_30_dialog_content = "\"Hei, Nak!\"",
  ui_story_5037_50371801_31_dialog_content = "(Nada itu terdengar sangat familiar...!)",
  ui_story_5037_50371801_32_dialog_content = "\"Siap pergi berburu sesuatu denganku?\"",
  ui_story_5037_50371801_33_dialog_content = "Siap menebak siapa yang ditiru Goldie, PlayerName?",
  ui_story_5037_50371801_34_option_content = "Rumah di luar kota?",
  ui_story_5037_50371801_35_dialog_content = "Ohhh, hampir saja tapi kurang tepat!",
  ui_story_5037_50371801_36_dialog_content = "Jawaban yang benar adalah... Sinsa!",
  ui_story_5037_50371801_37_dialog_content = "Aku tidak percaya aku salah.",
  ui_story_5037_50371801_38_dialog_content = "Apakah itu akting saya? Saya akan melakukan yang lebih baik lain kali!",
  ui_story_5037_50371801_39_option_content = "Sinsa?",
  ui_story_5037_50371801_40_dialog_content = "Benar!",
  ui_story_5037_50371801_41_dialog_content = "Sepertinya penampilan Goldie sangat meyakinkan!",
  ui_story_5037_50371801_42_dialog_content = "Itu benar-benar! Itu benar-benar seperti Sinsa!",
  ui_story_5037_50371801_43_dialog_content = "Aku berani bersumpah kau akan mengeluarkan kunci pas merah besar...",
  ui_story_5037_50371801_44_dialog_content = "Uh... Aku anggap itu sebagai pujian?",
  ui_story_5037_50371801_45_option_content = "Kleken?",
  ui_story_5037_50371801_46_dialog_content = "Itu... benar-benar salah!",
  ui_story_5037_50371801_47_dialog_content = "Jawaban yang benar adalah... Sinsa!",
  ui_story_5037_50371801_48_dialog_content = "Anda harus melihat kinerja Goldie lebih hati-hati, PlayerName!",
  ui_story_5037_50371801_49_dialog_content = "M-maaf…",
  ui_story_5037_50371801_50_dialog_content = "Aku juga harus berusaha lebih keras!",
  ui_story_5037_50371801_51_dialog_content = "Kami meningkatkan kesulitan untuk yang berikutnya!",
  ui_story_5037_50371801_52_dialog_content = "Goldie, mari kita lihat kamu meniru orang ini!",
  ui_story_5037_50371801_53_dialog_content = "Wow... Mereka sangat berbeda dariku, tapi aku akan mencoba yang terbaik!",
  ui_story_5037_50371801_54_dialog_content = "\"Apa yang kau lakukan, anak muda?\"",
  ui_story_5037_50371801_55_dialog_content = "(Siapa yang dia mainkan kali ini...?)",
  ui_story_5037_50371801_56_dialog_content = "\"Bisakah Anda membawa teh saya ke kamar saya jika Anda punya waktu sebentar? Saya terlalu malas untuk mengambilnya sendiri.\"",
  ui_story_5037_50371801_57_dialog_content = "Tebak lah, PlayerName!",
  ui_story_5037_50371801_58_option_content = "Migard?",
  ui_story_5037_50371801_59_dialog_content = "Benar!",
  ui_story_5037_50371801_60_dialog_content = "Itu benar-benar sangat sulit...",
  ui_story_5037_50371801_61_dialog_content = "Itu juga sulit bagi saya. Sikap dan tingkah lakunya cukup sulit untuk diungkapkan.",
  ui_story_5037_50371801_62_dialog_content = "Saya melakukannya dengan benar! Saya pikir itu menunjukkan kinerja Goldie sukses!",
  ui_story_5037_50371801_63_option_content = "Penguasa Kota?",
  ui_story_5037_50371801_64_dialog_content = "Yah, dari perspektif usia, dia pasti bisa memanggilmu anak muda...",
  ui_story_5037_50371801_65_dialog_content = "Tapi jawaban yang benar adalah Migard!",
  ui_story_5037_50371801_66_dialog_content = "aku harus berusaha lebih keras...",
  ui_story_5037_50371801_67_dialog_content = "Tidak, mungkin saya perlu lebih memperhatikan ...",
  ui_story_5037_50371801_68_option_content = "Tweety?",
  ui_story_5037_50371801_69_dialog_content = "Tidak! Bagaimana bisa Tweety memanggilmu anak muda padahal dia sendiri masih sangat muda?!",
  ui_story_5037_50371801_70_dialog_content = "Jawaban yang benar adalah Migard!",
  ui_story_5037_50371801_71_dialog_content = "Meskipun dia wanita cantik, dia masih memiliki banyak tingkah laku seorang lelaki tua ...",
  ui_story_5037_50371801_72_dialog_content = "I-Memang...",
  ui_story_5037_50371801_73_dialog_content = "Saya selalu merasa seperti sedang diteliti ketika saya melihatnya!",
  ui_story_5037_50371801_74_dialog_content = "Mari kita berusaha lebih keras untuk yang berikutnya, PlayerName!",
  ui_story_5037_50371801_75_dialog_content = "Selanjutnya, tantangan terakhir kita!",
  ui_story_5037_50371801_76_dialog_content = "Goldie, tolong jadilah orang ini!",
  ui_story_5037_50371801_77_dialog_content = "Hah?! I-apakah ini benar-benar baik-baik saja?",
  ui_story_5037_50371801_78_dialog_content = "Tentu saja! Anda bebas bertindak sesuai keinginan Anda!",
  ui_story_5037_50371801_79_dialog_content = "Baiklah... Ini dia!",
  ui_story_5037_50371801_80_dialog_content = "\"PlayerName...\"",
  ui_story_5037_50371801_81_dialog_content = "(Apakah dia sudah mulai ?!)",
  ui_story_5037_50371801_82_dialog_content = "\"Mari kita berikan semuanya hari ini juga!\"",
  ui_story_5037_50371801_83_dialog_content = "Baiklah, PlayerName. Apa tebakanmu?",
  ui_story_5037_50371801_84_option_content = "Lilika?",
  ui_story_5037_50371801_85_dialog_content = "Itu memang mirip Lilica! Tapi itu bukan dia.",
  ui_story_5037_50371801_86_dialog_content = "Ini bukan? Betulkah?",
  ui_story_5037_50371801_87_dialog_content = "Jawabannya ada tepat di depan mata Anda, PlayerName!",
  ui_story_5037_50371801_88_dialog_content = "Apakah Anda ... berakting sendiri ?!",
  ui_story_5037_50371801_89_dialog_content = "Benar!",
  ui_story_5037_50371801_90_option_content = "Goldie?",
  ui_story_5037_50371801_91_dialog_content = "Bingo!",
  ui_story_5037_50371801_92_dialog_content = "Saya benar-benar tidak berharap Anda melakukannya dengan benar!",
  ui_story_5037_50371801_93_dialog_content = "Kedengarannya sangat energik, seperti biasanya.",
  ui_story_5037_50371801_94_dialog_content = "Saya hanya sedikit bingung mengapa Anda menggunakan dia?",
  ui_story_5037_50371801_95_dialog_content = "Persepsi seorang produser terhadap penampilan aktor mereka akan mempengaruhi pelatihan mereka.",
  ui_story_5037_50371801_96_dialog_content = "Selain memahami peran, produser terbaik juga memiliki keahlian lain...",
  ui_story_5037_50371801_97_dialog_content = "Mereka tahu karakteristik dan kekuatan aktor mereka sendiri!",
  ui_story_5037_50371801_98_dialog_content = "Hanya ini yang memungkinkan pelatihan khusus dan terarah.",
  ui_story_5037_50371801_99_dialog_content = "Jadi tantangan terakhir itu sebenarnya dimaksudkan sebagai ujian untukmu!",
  ui_story_5037_50371801_100_dialog_content = "Jadi itulah masalahnya! Saya mengerti sekarang.",
  ui_story_5037_50371801_101_dialog_content = "Saya belajar banyak juga!",
  ui_story_5037_50371801_102_dialog_content = "Ada begitu banyak perbedaan antara masing-masing peran. Aku harus terus bekerja keras!",
  ui_story_5037_50371801_103_dialog_content = "Itu saja untuk pelatihan hari ini! Kami berharap yang terbaik untuk Anda berdua!",
  ui_story_5037_50371801_104_dialog_content = "Jangan lupa untuk mempraktikkan apa yang Anda pelajari hari ini!",
  ui_story_5037_50371801_105_dialog_content = "Siap!",
  ui_story_5037_50371801_106_dialog_content = "Ya, Direktur Lilica!",
  ui_story_5037_50371901_1_dialog_content = "Jadi, seperti apa sebenarnya pendeta Cloud Island itu?",
  ui_story_5037_50371901_2_dialog_content = "Saya mendengar bahwa para pendeta adalah penari yang luar biasa, anggun dan misterius, dan juga sangat ahli dalam Luminatics.",
  ui_story_5037_50371901_3_dialog_content = "Imajinasiku semakin liar!",
  ui_story_5037_50371901_4_dialog_content = "Anda akan segera melihat sendiri!",
  ui_story_5037_50371901_5_dialog_content = "Saya berhasil mengukir waktu untuk datang ke Colossus Anda hanya untuk pertemuan ini!",
  ui_story_5037_50371901_6_dialog_content = "Jantungku mulai berdegup kencang begitu aku mendengar bahwa aku memiliki kesempatan untuk meminta tips menari dari pendeta sungguhan!",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_8_dialog_content = "Saya minta maaf karena membuat Anda berdua menunggu.",
  ui_story_5037_50371901_9_dialog_content = "Sama sekali tidak! Saya sangat bersyukur Anda datang jauh-jauh dari Cloud Island untuk melatih kami!",
  ui_story_5037_50371901_10_dialog_content = "Anda pasti Goldie, bukan?",
  ui_story_5037_50371901_11_dialog_content = "Ya! Halo Rinne, Aku Goldie, seorang idola.",
  ui_story_5037_50371901_12_dialog_content = "Hai, Goldie. Saya Rinne, seorang pendeta dari Cloud Island.",
  ui_story_5037_50371901_13_dialog_content = "Apakah idol sama dengan penyanyi?",
  ui_story_5037_50371901_14_dialog_content = "Ada beberapa perbedaan. Selain menyanyi, saya juga perlu mempelajari keterampilan lain, seperti menari dan akting!",
  ui_story_5037_50371901_15_dialog_content = "Jadi begitu. Dan itulah mengapa Anda ingin mempelajari tarian kagura?",
  ui_story_5037_50371901_16_dialog_content = "Ya! Bisakah kamu mengajariku, Rinne?",
  ui_story_5037_50371901_17_dialog_content = "Tentu saja! Mengapa saya tidak menari untuk Anda sekarang, sebagai demonstrasi kecil?",
  ui_story_5037_50371901_18_dialog_content = "Benar-benar?! Oh ya! Aku tidak percaya aku benar-benar menyaksikan seorang pendeta melakukan tarian kagura!",
  ui_story_5037_50371901_19_dialog_content = "Hehe…",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_22_dialog_content = "Memukau...",
  ui_story_5037_50371901_23_dialog_content = "Suara lonceng dan pemandangan tarian Rinne membuatku tenang...",
  ui_story_5037_50371901_24_dialog_content = "Ini hanyalah beberapa langkah dasar kagura. Apakah Anda ingin pergi, Goldie?",
  ui_story_5037_50371901_25_dialog_content = "Ya!",
  ui_story_5037_50371901_26_dialog_content = "Apakah ini benar?",
  ui_story_5037_50371901_27_dialog_content = "Bagus sekali. Gerakan Anda turun dengan sempurna!",
  ui_story_5037_50371901_28_dialog_content = "Saya cukup percaya diri dengan keterampilan pencerminan saya!",
  ui_story_5037_50371901_29_dialog_content = "Tapi tetap saja, aku merasa kaguraku kehilangan sesuatu...",
  ui_story_5037_50371901_30_dialog_content = "Benar, itu tidak memberikan perasaan menenangkan yang sama seperti yang dirasakan Rinne.",
  ui_story_5037_50371901_31_dialog_content = "Merindukan Rinne, apakah Anda menggunakan semacam Luminatics khusus saat menari?",
  ui_story_5037_50371901_32_dialog_content = "Sama sekali tidak. Saya tidak menggunakan Luminatics. Ini hanya menari, tidak lebih.",
  ui_story_5037_50371901_33_dialog_content = "Jadi apa sebenarnya yang saya lakukan secara berbeda?",
  ui_story_5037_50371901_34_dialog_content = "May Saya bertanya apa yang Anda pikirkan saat menari?",
  ui_story_5037_50371901_35_dialog_content = "Apa yang saya pikirkan...?",
  ui_story_5037_50371901_36_dialog_content = "Banyak hal, seperti jika langkahku benar, dan apa yang terjadi selanjutnya...",
  ui_story_5037_50371901_37_dialog_content = "Ini adalah pertama kalinya aku menari kagura, jadi aku khawatir melakukannya dengan benar.",
  ui_story_5037_50371901_38_dialog_content = "Ahh... Mungkin itu sumber masalahnya.",
  ui_story_5037_50371901_39_dialog_content = "Kagura adalah tarian untuk para dewa. Saat Anda bergerak, pikiran Anda hanya boleh bersama yang ilahi.",
  ui_story_5037_50371901_40_dialog_content = "Hanya dengan begitu hatimu dapat diungkapkan melalui tarian.",
  ui_story_5037_50371901_41_dialog_content = "Oh...! Baiklah, saya pikir saya mengerti!",
  ui_story_5037_50371901_42_dialog_content = "Cepat sekali!",
  ui_story_5037_50371901_43_dialog_content = "Ini agak mirip dengan bagaimana saya biasanya tampil!",
  ui_story_5037_50371901_44_dialog_content = "Penggemar saya adalah satu-satunya hal yang saya pikirkan ketika saya bernyanyi atau menari, dan betapa saya berharap dapat membawa kegembiraan bagi mereka.",
  ui_story_5037_50371901_45_dialog_content = "Ketika saya berada di zona seperti itu, vokal dan gerakan saya tampak mengalir hampir tanpa usaha.",
  ui_story_5037_50371901_46_dialog_content = "Tariannya mungkin berbeda, tetapi beberapa hal sama.",
  ui_story_5037_50371901_47_dialog_content = "Apakah Anda akan mencoba menari lagi, mengingat semua itu?",
  ui_story_5037_50371901_48_dialog_content = "Ya!",
  ui_story_5037_50371901_49_dialog_content = "Pikirkan hanya penggemar saya ...",
  ui_story_5037_50371901_50_dialog_content = "(Luar biasa! Ini benar-benar getaran yang berbeda dibandingkan dengan yang pertama kali!)",
  ui_story_5037_50371901_51_dialog_content = "(Tapi sepertinya masih ada beberapa perbedaan antara tarian Goldie dan tarian Rinne.)",
  ui_story_5037_50371901_52_dialog_content = "Bagaimana menurutmu, Rin? PlayerName?",
  ui_story_5037_50371901_53_option_content = "Ini jauh lebih seperti Rinne!",
  ui_story_5037_50371901_54_dialog_content = "Benarkah? Baguslah kalau begitu!",
  ui_story_5037_50371901_55_dialog_content = "Hmm... Masih ada beberapa perbedaan.",
  ui_story_5037_50371901_56_dialog_content = "Oh?",
  ui_story_5037_50371901_57_option_content = "Versi tarian Anda memiliki daya tarik tersendiri!",
  ui_story_5037_50371901_58_dialog_content = "Oh?",
  ui_story_5037_50371901_59_dialog_content = "Tarianmu terasa sedikit lebih hidup, sedikit lebih ringan.",
  ui_story_5037_50371901_60_dialog_content = "Goldie dan saya menari untuk orang yang berbeda.",
  ui_story_5037_50371901_61_dialog_content = "Tarian Goldie ditujukan untuk penonton yang antusias dan bersemangat.",
  ui_story_5037_50371901_62_dialog_content = "Gerakan identik dapat menyampaikan emosi yang sangat berbeda menurut masing-masing individu.",
  ui_story_5037_50371901_63_dialog_content = "Ini bukan hal yang buruk dan sepenuhnya alami, jadi tidak perlu khawatir.",
  ui_story_5037_50371901_64_dialog_content = "Pikiran dan gerakan Anda adalah milik Anda sendiri.",
  ui_story_5037_50371901_65_dialog_content = "Oke!",
  ui_story_5037_50371901_66_dialog_content = "Terima kasih atas bimbingan Anda!",
  ui_story_5037_50372001_1_dialog_content = "Melihat kita berada di tempat lain hari ini, aku harus mulai syuting. Perhatikan ekspresi kalian, guys.",
  ui_story_5037_50372001_2_dialog_content = "3... 2... 1... Aksi!",
  ui_story_5037_50372001_3_dialog_content = "Apakah kita berguling? *Batuk*...",
  ui_story_5037_50372001_4_dialog_content = "Kelas vokal saya dimulai sekarang.",
  ui_story_5037_50372001_5_dialog_content = "Hai, Nina!",
  ui_story_5037_50372001_6_dialog_content = "Aku agak bingung...",
  ui_story_5037_50372001_7_dialog_content = "Bukankah kita seharusnya memiliki pelatihan vokal sekarang? Apa yang kita lakukan di aula konser?",
  ui_story_5037_50372001_8_dialog_content = "Sebuah pertanyaan yang sangat bagus, PlayerName.",
  ui_story_5037_50372001_9_dialog_content = "Pelajaran ini tidak akan aktif tetapi pasif. Hari ini kami mendengarkan.",
  ui_story_5037_50372001_10_dialog_content = "Mendengarkan...?",
  ui_story_5037_50372001_11_dialog_content = "Mendengarkan lagu artis lain adalah bagian penting dari pelatihan seorang idola!",
  ui_story_5037_50372001_12_dialog_content = "Kami perlu tahu apa yang disukai penggemar saat ini jika kami ingin membuat musik yang ingin didengar orang.",
  ui_story_5037_50372001_13_dialog_content = "Ya! Ketahui tren, ikuti tren, dan pimpin tren. Ini adalah sumber kehidupan industri!",
  ui_story_5037_50372001_14_dialog_content = "Jadi, hari ini kita akan mendengarkan musikal berjudul \"Phantom of the Theatre\".",
  ui_story_5037_50372001_15_dialog_content = "Ini menceritakan kisah aktor panggung abadi.",
  ui_story_5037_50372001_16_dialog_content = "Drama perubahan yang dilakukan memberikan garis besar yang menghubungkan setiap era Umbraton.",
  ui_story_5037_50372001_17_dialog_content = "Itu luar biasa!",
  ui_story_5037_50372001_18_dialog_content = "Budaya populer adalah cerminan dari zeitgeist!",
  ui_story_5037_50372001_19_dialog_content = "Luar biasa, sepuluh poin untuk Goldie.",
  ui_story_5037_50372001_20_dialog_content = "Tolong bagikan materinya, Minos.",
  ui_story_5037_50372001_21_dialog_content = "Ya, Nona.",
  ui_story_5037_50372001_22_dialog_content = "Apa ini...?",
  ui_story_5037_50372001_23_dialog_content = "Nona secara khusus menyiapkan ini sendiri. Ini mencantumkan semua lagu dan opera populer Umbraton selama dekade terakhir.",
  ui_story_5037_50372001_24_dialog_content = "Pastikan untuk menjaganya.",
  ui_story_5037_50372001_25_dialog_content = "B-baiklah…",
  ui_story_5037_50372001_26_dialog_content = "Di kelas ini, Anda akan mempelajari masing-masing lagu tersebut, serta tren di Umbraton selama sepuluh tahun terakhir.",
  ui_story_5037_50372001_27_dialog_content = "Ini akan menyempurnakan selera Anda, dan membantu Anda merekam lebih banyak lagu yang sedang tren.",
  ui_story_5037_50372001_28_dialog_content = "Nina, aku menghargai usahamu, tapi...",
  ui_story_5037_50372001_29_dialog_content = "Tentunya ini terlalu banyak ?!",
  ui_story_5037_50372001_30_dialog_content = "Anda tidak dapat mengharapkan kami untuk membaca semuanya hari ini?",
  ui_story_5037_50372001_31_dialog_content = "Baca semuanya? Tidak, tentu saja tidak! Saya tidak pernah menetapkan tugas yang mustahil seperti itu. Itu tidak masuk akal.",
  ui_story_5037_50372001_32_dialog_content = "Masing-masing lagu ini akan direferensikan dalam apa yang kita tonton hari ini.",
  ui_story_5037_50372001_33_dialog_content = "Anda dapat merujuk ke daftar lengkap yang saya kumpulkan, untuk mendapatkan pemahaman yang lebih dalam tentang perbedaan budaya pop di antara era.",
  ui_story_5037_50372001_34_dialog_content = "Terima kasih banyak!",
  ui_story_5037_50372001_35_dialog_content = "Kami akan mempelajarinya dengan cermat!",
  ui_story_5037_50372001_36_dialog_content = "Pertunjukan akan segera dimulai, jadi kita harus bergegas dan duduk.",
  ui_story_5037_50372001_37_dialog_content = "Dengan cara ini, semua orang.",
  ui_story_5037_50372001_38_dialog_content = "Nona dengan hormat menyediakan kursi VIP untuk Anda.",
  ui_story_5037_50372001_39_dialog_content = "Wow, sangat dekat dengan panggung! Kami mungkin memiliki tampilan terbaik dari pertunjukan di seluruh tempat!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>...</color>",
  ui_story_5037_50372001_41_dialog_content = "\"Saat-saat bahagia, musik yang indah... Semuanya cepat berlalu.\"",
  ui_story_5037_50372001_42_dialog_content = "\"Wanita cantik, bisakah kamu melakukan tarian kehormatan untukku?\"",
  ui_story_5037_50372001_43_dialog_content = "Ini adalah \"Kleo and Jessica\", salah satu drama paling awal Umbraton.",
  ui_story_5037_50372001_44_dialog_content = "Saya tahu yang ini! Saya mendengar ceritanya ketika saya masih kecil, diadaptasi dari drama!",
  ui_story_5037_50372001_45_dialog_content = "Ini menceritakan kisah tragis dua orang Aurorian dari keluarga saingan yang saling jatuh cinta.",
  ui_story_5037_50372001_46_dialog_content = "Itu benar. Seperti yang Anda lihat, selama ini budaya Umbraton sangat dipengaruhi oleh Lumopolis.",
  ui_story_5037_50372001_47_dialog_content = "Kita bisa belajar banyak tentang kehidupan dan kebiasaan Bangsawan Lumo kontemporer dari sini, seperti...",
  ui_story_5037_50372001_48_dialog_content = "(Nina Dan Goldie benar-benar naik.)",
  ui_story_5037_50372001_49_dialog_content = "(Dramanya bagus, tapi saya tidak begitu tahu banyak tentang sejarah Lumopolis atau Umbraton...)",
  ui_story_5037_50372001_50_dialog_content = "(Aku mengantuk... Aku tidak bisa menahannya, menonton sesuatu yang tidak begitu kumengerti hanya membuatku menguap...)",
  ui_story_5037_50372001_51_dialog_content = "(Tapi Nina bersusah payah untuk mengatur semua ini...)",
  ui_story_5037_50372001_52_option_content = "Jangan menyerah pada kelelahan.",
  ui_story_5037_50372001_53_dialog_content = "(Tidak, saya tidak bisa tidur. Saya harus menyelesaikan ini sampai akhir!)",
  ui_story_5037_50372001_54_dialog_content = "(Ini adalah bahan referensi yang tak ternilai harganya!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>Setelah susah payah tetap terjaga hingga akhir pertunjukan</color>",
  ui_story_5037_50372001_56_dialog_content = "Saya sama sekali tidak tahu betapa rumitnya perkembangan budaya Umbraton sampai sekarang!",
  ui_story_5037_50372001_57_dialog_content = "Saya belajar banyak juga!",
  ui_story_5037_50372001_58_dialog_content = "Meskipun saya tidak terlalu paham dengan isinya...",
  ui_story_5037_50372001_59_dialog_content = "Jangan khawatir! Saya sudah menyoroti poin-poin penting dalam materi.",
  ui_story_5037_50372001_60_dialog_content = "Anda dapat membolak-balik untuk menyegarkan ingatan Anda kapan pun Anda mau.",
  ui_story_5037_50372001_61_dialog_content = "Wow, sekali lagi terima kasih telah meluangkan waktu untuk melakukan ini untuk kami, Nina!",
  ui_story_5037_50372001_62_option_content = "Menyerah untuk tidur.",
  ui_story_5037_50372001_63_dialog_content = "(Harus tetap terjaga... Harus tetap... Zzzz...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>Siapa yang tahu berapa lama kemudian ...</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName? PlayerName!",
  ui_story_5037_50372001_66_dialog_content = "Biar kucoba, Nona Goldie.",
  ui_story_5037_50372001_67_dialog_content = "Maukah kamu bangun, PlayerName!",
  ui_story_5037_50372001_68_dialog_content = "Eh?!",
  ui_story_5037_50372001_69_dialog_content = "Kenapa kamu tidur? Pertunjukan sudah berakhir.",
  ui_story_5037_50372001_70_dialog_content = "Apa? Ini sudah berakhir?!",
  ui_story_5037_50372001_71_dialog_content = "Aku terlalu asyik untuk menjelaskan sesuatu Goldie bahwa aku bahkan tidak menyadari kau tertidur...",
  ui_story_5037_50372001_72_dialog_content = "Sangat menyinggung untuk menolak kebaikan Nona...",
  ui_story_5037_50372001_73_dialog_content = "M-maaf!",
  ui_story_5037_50372001_74_dialog_content = "Itu adalah kesalahanku...",
  ui_story_5037_50372001_75_dialog_content = "Tak apa.",
  ui_story_5037_50372001_76_dialog_content = "Sayang sekali Anda melewatkan kesempatan untuk menambah pengetahuan sambil menikmati pertunjukan.",
  ui_story_5037_50372001_77_dialog_content = "Tapi untungnya bagi Anda, saya sudah menyoroti poin-poin terkait dalam materi.",
  ui_story_5037_50372001_78_dialog_content = "Anda akan mengambil beberapa hal, asalkan Anda benar-benar meninjaunya.",
  ui_story_5037_50372001_79_dialog_content = "Saya akan membaca semuanya dengan sangat hati-hati! Dan tidak akan tertidur!",
  ui_story_5037_50372001_80_dialog_content = "Saya harap Anda semua mendapatkan sesuatu dari pertunjukan ini.",
  ui_story_5037_50372001_81_dialog_content = "Mengetahui apa yang diinginkan publik adalah kunci budaya populer. Anda tidak bisa begitu saja mengubur kepala Anda di pasir dan mengabaikannya.",
  ui_story_5037_50372001_82_dialog_content = "Ini semua bantuan yang bisa saya tawarkan kepada Anda. Mulai sekarang, terserah kalian berdua untuk berusaha.",
  ui_story_5037_50372001_83_dialog_content = "Terima kasih, Nona Nina, Minos!",
  ui_story_5037_50372001_84_dialog_content = "Ya terima kasih!",
  ui_story_5037_50372101_1_dialog_content = "Fleur, terima kasih telah membimbing Goldie dan aku—",
  ui_story_5037_50372101_2_dialog_content = "Ssst!",
  ui_story_5037_50372101_3_dialog_content = "Eh? Kenapa kau bersandar di pintu, Fleur?",
  ui_story_5037_50372101_4_dialog_content = "Silakan, PlayerName, Goldie... Aku harus menyusahkanmu untuk diam sebentar...",
  ui_story_5037_50372101_5_dialog_content = "...",
  ui_story_5037_50372101_6_dialog_content = "...",
  ui_story_5037_50372101_7_dialog_content = "Fiuh... Sepertinya orang-orang itu sudah pergi.",
  ui_story_5037_50372101_8_dialog_content = "Jangan bilang kau membuat masalah lagi?",
  ui_story_5037_50372101_9_dialog_content = "Hmm…",
  ui_story_5037_50372101_10_dialog_content = "Maksud saya, dalam perjalanan ke sini, saya menyapa beberapa orang yang sebelumnya saya bantu...",
  ui_story_5037_50372101_11_dialog_content = "Halo.",
  ui_story_5037_50372101_12_dialog_content = "Hah? Mengapa, jika bukan Fleur! Terima kasih banyak atas bantuan Anda tempo hari!",
  ui_story_5037_50372101_13_dialog_content = "Tapi kemudian, setelah mendengar namaku, semakin banyak orang datang...",
  ui_story_5037_50372101_14_dialog_content = "Apa? Fleur ada di sini? Aku benar-benar berutang budi padamu untuk terakhir kalinya!",
  ui_story_5037_50372101_15_dialog_content = "Fleur!! Saya penggemar berat!!!",
  ui_story_5037_50372101_16_dialog_content = "Butuh waktu lama bagi saya untuk melarikan diri dari kerumunan penggemar yang memujanya. Aku bahkan harus mengambil rute panjang hanya untuk memastikan tidak ada yang mengikutiku...",
  ui_story_5037_50372101_17_dialog_content = "Terkadang menjadi sangat populer itu merepotkan...",
  ui_story_5037_50372101_18_dialog_content = "Aku sangat cemburu, aku berharap aku sepopuler kamu!",
  ui_story_5037_50372101_19_dialog_content = "Benar-benar sangat menguras tenaga.",
  ui_story_5037_50372101_20_dialog_content = "Itu tidak akan mengganggu saya sama sekali!",
  ui_story_5037_50372101_21_dialog_content = "Sungguh luar biasa menarik lebih banyak penggemar untuk menikmati tarian dan nyanyian saya!",
  ui_story_5037_50372101_22_dialog_content = "Jika itu yang Anda inginkan, saya tidak keberatan.",
  ui_story_5037_50372101_23_dialog_content = "Hanya saja aku populer berkat konstitusi khususku.",
  ui_story_5037_50372101_24_dialog_content = "Ini bukan hanya sesuatu yang bisa diajarkan ...",
  ui_story_5037_50372101_25_dialog_content = "Sungguh?",
  ui_story_5037_50372101_26_dialog_content = "Dan sejujurnya, saya juga tidak tahu persis bagaimana seseorang menjadi populer.",
  ui_story_5037_50372101_27_dialog_content = "Berkat kekhasan saya, saya menghabiskan sebagian besar waktu saya mempelajari bagaimana menjadi tidak menarik atau bahkan tidak disukai.",
  ui_story_5037_50372101_28_dialog_content = "Sulit dipercaya…",
  ui_story_5037_50372101_29_dialog_content = "Lalu apa yang harus kita lakukan?",
  ui_story_5037_50372101_30_dialog_content = "Aku tahu!",
  ui_story_5037_50372101_31_dialog_content = "Apakah Anda datang dengan sesuatu?",
  ui_story_5037_50372101_32_dialog_content = "Nah, karena Fleur sudah berpikir panjang dan keras tentang bagaimana menjadi TIDAK populer, mengapa kita tidak melakukan kebalikannya saja?",
  ui_story_5037_50372101_33_dialog_content = "Maksudmu, meminta Fleur mengajarimu taktiknya, lalu membalikkannya?",
  ui_story_5037_50372101_34_dialog_content = "Jadi, jadikan metode ketidakpopuleran menjadi metode popularitas?",
  ui_story_5037_50372101_35_dialog_content = "Benar! Inilah mengapa Anda adalah produser saya, Anda memahaminya dengan sangat cepat!",
  ui_story_5037_50372101_36_dialog_content = "Apakah Anda benar-benar berpikir itu akan berhasil?",
  ui_story_5037_50372101_37_dialog_content = "Kita tidak akan pernah tahu jika kita tidak mencobanya, bukan? Maukah kau mengajariku, Fleur? Silahkan?",
  ui_story_5037_50372101_38_dialog_content = "Oke... Apakah kalian ingin belajar bagaimana menjadi tidak menarik perhatian, atau bagaimana menjadi tidak disukai secara aktif?",
  ui_story_5037_50372101_39_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5037_50372101_40_dialog_content = "(Karena kita akan membalikkannya, tentunya semakin banyak orang yang tidak menyukai Anda, semakin mereka akan menyukai Anda saat dibalik?)",
  ui_story_5037_50372101_41_option_content = "Bagaimana menjadi tidak mencolok",
  ui_story_5037_50372101_42_dialog_content = "Menjadi tidak mencolok sebenarnya cukup sederhana: triknya adalah menjadi seperti orang lain.",
  ui_story_5037_50372101_43_dialog_content = "Yang harus Anda lakukan adalah bertindak seperti orang lain sambil menyembunyikan fitur pembeda apa pun yang membuat Anda menonjol, dan hanya itu!",
  ui_story_5037_50372101_44_dialog_content = "Anda membuatnya terdengar mudah!",
  ui_story_5037_50372101_45_dialog_content = "Biasanya Anda tidak akan menarik perhatian jika Anda mengenakan pakaian biasa yang membosankan dan berjalan-jalan dengan kepala tertunduk.",
  ui_story_5037_50372101_46_dialog_content = "Beberapa orang bahkan memakai topi, yang dapat membantu menyembunyikan wajah mereka!",
  ui_story_5037_50372101_47_dialog_content = "Jadi kebalikan dari itu adalah... Berjalan-jalan dengan kepala terangkat tinggi, memamerkan nyanyian dan tarianku?",
  ui_story_5037_50372101_48_dialog_content = "Kedengarannya agak aneh, tapi karena kamu bernyanyi dan menari dengan sangat baik...",
  ui_story_5037_50372101_49_dialog_content = "Seharusnya cukup, bukan?",
  ui_story_5037_50372101_50_option_content = "Bagaimana menjadi tidak disukai",
  ui_story_5037_50372101_51_dialog_content = "Agak sulit untuk membuat orang secara aktif tidak menyukai Anda.",
  ui_story_5037_50372101_52_dialog_content = "Saya telah mencoba banyak hal berbeda, seperti menyelinap dengan curiga, berpakaian compang-camping, atau membuat wajah saya kotor.",
  ui_story_5037_50372101_53_dialog_content = "Saya berhasil, meskipun saya disalahartikan sebagai pencuri beberapa kali...",
  ui_story_5037_50372101_54_dialog_content = "Tetapi karena masalah khusus saya, begitu orang melihat siapa saya sebenarnya, tidak ada akal-akalan yang akan berhasil.",
  ui_story_5037_50372101_55_dialog_content = "Aku memahaminya.",
  ui_story_5037_50372101_56_dialog_content = "Jadi kebalikannya adalah memiliki postur tubuh yang bermartabat, berpakaian bagus, dan berpenampilan bagus, bukan?",
  ui_story_5037_50372101_57_dialog_content = "Dan selalu bersikap positif dan memancarkan senyum seorang idola ke mana pun saya pergi!",
  ui_story_5037_50372101_58_dialog_content = "Itu harus bekerja!",
  ui_story_5037_50372101_59_dialog_content = "Jangan lupa bahwa sikap Anda merupakan faktor penting dalam metode apa pun yang Anda gunakan.",
  ui_story_5037_50372101_60_dialog_content = "Kamu penari yang hebat, Goldie, jadi kamu seharusnya sudah tahu ini.",
  ui_story_5037_50372101_61_dialog_content = "Sama sekali! Bantalan dan postur sangat penting saat menari. Perbedaan antara berdiri tegak dan bungkuk saat menari sangat ekstrim.",
  ui_story_5037_50372101_62_dialog_content = "Bagaimanapun, terima kasih banyak, Fleur!",
  ui_story_5037_50372101_63_dialog_content = "Dengan senang hati. Jika ada hal lain yang dapat saya bantu, jangan ragu untuk memberi tahu saya.",
  ui_story_5037_50372101_64_dialog_content = "Saya yakin salah satu alasan mengapa Anda begitu populer adalah karena Anda selalu bersedia membantu orang.",
  ui_story_5037_50372101_65_dialog_content = "K-kau pikir??",
  ui_story_5037_50372101_66_dialog_content = "Tapi aku tidak bisa mengabaikan orang yang membutuhkan bantuan...",
  ui_story_5037_50372101_67_dialog_content = "Dan itu hal yang hebat, pasti jangan ubah itu!",
  ui_story_5037_50372101_68_dialog_content = "Baiklah. Terima kasih.",
  ui_story_5037_50372101_69_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5037_50372101_70_dialog_content = "Orang selalu menyukai mereka yang membantu orang lain, dan melakukan perbuatan baik!",
  ui_story_5037_50372101_71_dialog_content = "PlayerName, kita harus mencoba apa yang telah kita pelajari!",
  ui_story_5037_50372101_72_dialog_content = "Sekarang?!",
  ui_story_5037_50372101_73_dialog_content = "Kita harus menyerang selagi setrika masih panas! Ayo pergi-",
  ui_story_5037_50372101_74_dialog_content = "Tunggu sebentar, Goldie! Jangan buka pintunya dulu!",
  ui_story_5037_50372101_75_dialog_content = "Oh?",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>Berderak-</color>",
  ui_story_5037_50372101_77_dialog_content = "(Ada banyak orang di luar!)",
  ui_story_5037_50372101_78_dialog_content = "Dimana Fleur?",
  ui_story_5037_50372101_79_dialog_content = "Saya pikir saya baru saja mendengar seseorang meneriakkan namanya!",
  ui_story_5037_50372101_80_dialog_content = "Fleurrrrr! Kenapa kamu berlari?!",
  ui_story_5037_50372101_81_dialog_content = "Tolong, semuanya, tenanglah...",
  ui_story_5037_50372101_82_dialog_content = "KAMI MENCINTAI KAMU!!",
  ui_story_5037_50372101_83_dialog_content = "Wow! Anda benar-benar menarik mereka!",
  ui_story_5037_50372101_84_dialog_content = "Popularitas sepertinya bisa merepotkan...",
  ui_story_5037_50372201_1_dialog_content = "\"Di puncak sepi.\"",
  ui_story_5037_50372201_2_dialog_content = "\"Makan, minum, dan tidur sendirian... Inilah sumber seni mereka.\"",
  ui_story_5037_50372201_3_dialog_content = "\"Mengetahui ini, ketahuilah juga bahwa kesepian bukanlah musuh, melainkan teman, teman setia!\"",
  ui_story_5037_50372201_4_dialog_content = "Luar biasa!",
  ui_story_5037_50372201_5_dialog_content = "Bukankah itu kalimat dari \"Interview with the Famous\"?",
  ui_story_5037_50372201_6_dialog_content = "Terima kasih, nona muda. Bahwa Anda menikmati penampilan saya berbicara banyak tentang selera artistik Anda.",
  ui_story_5037_50372201_7_dialog_content = "Tunggu, Charon. Bisakah Anda menjelaskan sesuatu...?",
  ui_story_5037_50372201_8_dialog_content = "Bagaimana seluruh set Eraveil muncul di sini hanya dalam sepuluh menit setelah kita pergi?",
  ui_story_5037_50372201_9_dialog_content = "Anda seharusnya tidak terlalu terkejut, teman saya. Insinyur Illumina adalah yang terbaik di Astra.",
  ui_story_5037_50372201_10_dialog_content = "Saya tidak berpikir ini adalah apa yang seharusnya Anda gunakan untuk insinyur ...",
  ui_story_5037_50372201_11_dialog_content = "Ini adalah set yang sangat luar biasa! Ketika saya masuk, saya pikir entah bagaimana saya telah dipindahkan ke Eraveil!",
  ui_story_5037_50372201_12_dialog_content = "Tolong percaya padaku, teman-teman. Semua yang saya lakukan adalah untuk mendukung pengembangan bakat akting wanita muda ini.",
  ui_story_5037_50372201_13_dialog_content = "Sungguh?",
  ui_story_5037_50372201_14_dialog_content = "Pengetahuan sejati diperoleh melalui latihan. Seseorang harus mengalami akting, untuk mendapatkan pengalaman akting.",
  ui_story_5037_50372201_15_dialog_content = "Saya menyiapkan set dan naskah dengan harapan kalian berdua dapat merasakan keindahan pertunjukan.",
  ui_story_5037_50372201_16_dialog_content = "Luar biasa! Idol terkadang harus berakting dalam drama juga.",
  ui_story_5037_50372201_17_dialog_content = "Keterampilan akting saya pasti akan meningkat dengan bantuan dari seorang profesional yang terampil!",
  ui_story_5037_50372201_18_dialog_content = "Dalam hal ini, mari kita mulai sekaligus.",
  ui_story_5037_50372201_19_dialog_content = "Berikut script yang saya siapkan.",
  ui_story_5037_50372201_20_dialog_content = "Eh...",
  ui_story_5037_50372201_21_dialog_content = "Bukankah ini hanya \"Ada and the Colossus\", tetapi dengan beberapa baris yang diubah?",
  ui_story_5037_50372201_22_dialog_content = "Itu benar. Saya sengaja memilih lakon yang diadaptasi dari dongeng.",
  ui_story_5037_50372201_23_dialog_content = "Dongeng relatif sederhana, mudah dipahami, dan menghadirkan sedikit tantangan bagi aktor pemula.",
  ui_story_5037_50372201_24_dialog_content = "Anda memikirkan segalanya!",
  ui_story_5037_50372201_25_dialog_content = "Tapi tentu saja. Saya tahu bagaimana rasanya tumbuh dari aktor pemula menjadi aktor berbakat seperti saya hari ini!",
  ui_story_5037_50372201_26_dialog_content = "Haruskah kita menetapkan peran, PlayerName?",
  ui_story_5037_50372201_27_dialog_content = "Oke. Karena aku akrab dengan Colossi, aku bisa berperan sebagai Kaz.",
  ui_story_5037_50372201_28_dialog_content = "Aku akan memainkan Ada kalau begitu!",
  ui_story_5037_50372201_29_dialog_content = "Dia adalah karakter menggemaskan yang ingin tahu tentang segala hal dan penuh energi.",
  ui_story_5037_50372201_30_dialog_content = "Saya akan berperan sebagai narator dan bagian-bagian kecil lainnya.",
  ui_story_5037_50372201_31_dialog_content = "Karena itu semua sudah diputuskan, sebaiknya kita mulai saja.",
  ui_story_5037_50372201_32_dialog_content = "\"Dalam kebohongan Eraveil yang damai, Colossus bernama Kaz.\"",
  ui_story_5037_50372201_33_dialog_content = "\"Ia merindukan langit terbuka, namun tetap terperangkap di tanah tanpa seorang navigator.\"",
  ui_story_5037_50372201_34_dialog_content = "\"Namun Colossi dilahirkan untuk surga!\"",
  ui_story_5037_50372201_35_dialog_content = "\"Mungkin ada model yang diadaptasi untuk darat dan laut, tetapi langit tetap menjadi rumah sejati mereka!\"",
  ui_story_5037_50372201_36_dialog_content = "\"Aku ingin tahu bagaimana rasanya memiliki seorang navigator... Betapa hebatnya...\"",
  ui_story_5037_50372201_37_dialog_content = "\"Memiliki navigator pasti seperti memiliki sahabat...\"",
  ui_story_5037_50372201_38_dialog_content = "\"Hah? Siapa yang pergi ke sana? Kenapa kamu bisa berbicara denganku...?\"",
  ui_story_5037_50372201_39_dialog_content = "\"Apakah itu hantu? Lagi pula, tidak ada Caelestite yang berkeliaran di sekitar Colossus tua yang berkarat ini...\"",
  ui_story_5037_50372201_40_dialog_content = "\"Namun di sini sebelum Anda berdiri seorang Caelestite!\"",
  ui_story_5037_50372201_41_dialog_content = "\"Ada mendekati Kaz, mengamati bagaimana bunga yang tumbuh di atas kepalanya, dan mengulurkan tangan untuk menyentuhnya.\"",
  ui_story_5037_50372201_42_dialog_content = "(Tunggu, dia menyentuh kepalanya? Itu tidak ada dalam naskahku...)",
  ui_story_5037_50372201_43_dialog_content = "(Apa yang harus saya lakukan? Lanjutkan saja?)",
  ui_story_5037_50372201_44_option_content = "Lanjutkan kinerja",
  ui_story_5037_50372201_45_dialog_content = "\"Saya menyentuh...\"",
  ui_story_5037_50372201_46_dialog_content = "\"Heeeeey! Kamu pikir tidak apa-apa bagi orang Caelest untuk menguping pikiran pribadi seseorang, lalu berjalan dan menyentuhnya?\"",
  ui_story_5037_50372201_47_dialog_content = "\"Kepalaku yang cantik tidak bisa disentuh oleh sembarang orang!\"",
  ui_story_5037_50372201_48_dialog_content = "\"Tapi itu benar-benar cantik dan dihiasi dengan bunga-bunga kecil yang lucu!\"",
  ui_story_5037_50372201_48X1_dialog_content = "Memotong!",
  ui_story_5037_50372201_49_dialog_content = "Bagus sekali, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "Hah?",
  ui_story_5037_50372201_51_option_content = "Tanyakan sesuatu",
  ui_story_5037_50372201_52_dialog_content = "Tunggu sebentar, itu tidak ada dalam skrip.",
  ui_story_5037_50372201_52X1_dialog_content = "Memotong!",
  ui_story_5037_50372201_53_dialog_content = "Benar.",
  ui_story_5037_50372201_54_dialog_content = "Punyaku juga tidak punya...",
  ui_story_5037_50372201_55_dialog_content = "Ada apa dengan ini, Charon?",
  ui_story_5037_50372201_56_dialog_content = "Pertunjukan mungkin membutuhkan skrip, tetapi orang-orang memainkan peran.",
  ui_story_5037_50372201_57_dialog_content = "Peristiwa tak terduga dapat terjadi selama pertunjukan. Skrip tidak akan selalu diikuti dengan baik.",
  ui_story_5037_50372201_58_dialog_content = "Oleh karena itu, seorang aktor yang luar biasa harus mampu beradaptasi dan berimprovisasi dalam menghadapi keadaan yang berubah!",
  ui_story_5037_50372201_59_dialog_content = "Oke!",
  ui_story_5037_50372201_60_dialog_content = "Memang! Saya telah melihat beberapa drama di mana kalimat yang diucapkan di atas panggung berbeda dari yang tertulis di naskah.",
  ui_story_5037_50372201_61_dialog_content = "Namun improvisasi sang aktor sangat alami sehingga tidak ada yang tahu!",
  ui_story_5037_50372201_62_dialog_content = "Improvisasi adalah keterampilan penting bagi para aktor.",
  ui_story_5037_50372201_63_dialog_content = "Pertama-tama seseorang harus memahami karakternya, dan kemudian menjadi mereka. Hanya dengan begitu Anda dapat mengekspresikannya secara alami.",
  ui_story_5037_50372201_64_dialog_content = "Saya mengerti!",
  ui_story_5037_50372201_65_dialog_content = "Saya akan bekerja keras dalam hal ini, dan lebih menyempurnakan kemampuan akting saya!",
  ui_story_5037_50379901_1_dialog_content = "Ini aneh...",
  ui_story_5037_50379901_2_dialog_content = "Ini terlalu aneh!",
  ui_story_5037_50379901_3_dialog_content = "Mengapa Vice dan Carleen menghindariku selama beberapa hari terakhir?",
  ui_story_5037_50379901_4_dialog_content = "Apakah saya mengatakan sesuatu yang menyinggung perasaan mereka?",
  ui_story_5037_50379901_5_dialog_content = "Jangan bilang itu ada hubungannya dengan apa yang terjadi...",
  ui_story_5037_50379901_6_option_content = "Di jembatan",
  ui_story_5037_50379901_7_dialog_content = "Wow, sudah lama sejak saya mengenakan pakaian ini. Setidaknya masih muat!",
  ui_story_5037_50379901_8_dialog_content = "Bagaimana menurutmu, PlayerName? Antara ini dan seragam Illumina saya yang biasa, menurut Anda mana yang terlihat lebih baik?",
  ui_story_5037_50379901_9_dialog_content = "Hah? Ah, saya tidak tahu.",
  ui_story_5037_50379901_10_dialog_content = "...",
  ui_story_5037_50379901_11_dialog_content = "Saya seharusnya mengatakan mereka berdua terlihat bagus!",
  ui_story_5037_50379901_12_option_content = "Di ruang tunggu",
  ui_story_5037_50379901_13_dialog_content = "PlayerName?!",
  ui_story_5037_50379901_14_dialog_content = "A-Apa yang kau lakukan disini?! Berputar! Jangan lihat!",
  ui_story_5037_50379901_15_dialog_content = "Aku baru saja datang untuk minum...",
  ui_story_5037_50379901_16_dialog_content = "Apa yang baru saja kamu lihat...?",
  ui_story_5037_50379901_17_dialog_content = "Hah? Yah, aku melihatmu dengan piyamamu, menatap dirimu dengan gembira di cermin...",
  ui_story_5037_50379901_18_dialog_content = "Anda tidak melihat apa-apa!!!",
  ui_story_5037_50379901_19_dialog_content = "Aduh! Seharusnya aku tetap di tempat tidur malam itu!",
  ui_story_5037_50379901_20_dialog_content = "Tetap saja, kupikir kesalahan itu tidak cukup untuk membuat mereka mengabaikanku seperti ini...",
  ui_story_5037_50379901_21_dialog_content = "Aaaaaah! Apa sebenarnya yang saya lakukan salah? Ini membuatku gila!!",
  ui_story_5037_50379901_22_dialog_content = "Sudah hampir akhir tahun juga! Kita tidak bisa memasuki tahun baru dengan kecanggungan seperti ini di antara kita!",
  ui_story_5037_50379901_23_dialog_content = "M-Mungkin aku harus bertanya langsung pada mereka?",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  ui_story_5037_50379901_25_dialog_content = "Keburukan? Carleen? Kau disana...?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>Hah? I-itu PlayerName! Ugh... Apa yang dia lakukan di sini sekarang, sepanjang waktu?!</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>Buru-buru...!</size>",
  ui_story_5037_50379901_28_dialog_content = "hai, PlayerName! Anda datang tepat pada waktunya!",
  ui_story_5037_50379901_29_dialog_content = "Carleen dan aku baru saja akan pergi mencarimu. Masuk!",
  ui_story_5037_50379901_30_dialog_content = "Hah? Tapi kalian berdua telah menghindariku selama berhari-hari sekarang! Ada apa dengan perubahan sikap yang tiba-tiba?",
  ui_story_5037_50379901_31_dialog_content = "Anda akan tahu begitu Anda melangkah masuk!",
  ui_story_5037_50379901_32_dialog_content = "Uh... Kenapa semua lampu padam? Di sini sangat gelap... Agak menyeramkan.",
  ui_story_5037_50379901_33_dialog_content = "Anda hanya mengalami efek penuh jika lampu mati.",
  ui_story_5037_50379901_34_dialog_content = "I-Efek penuh dari apa?!",
  ui_story_5037_50379901_35_dialog_content = "Jauhkan mata Anda ke depan, itu mulai.",
  ui_story_5037_50379901_36_dialog_content = "Hah?",
  ui_story_5037_50379901_38_dialog_content = "Wow... Waktu benar-benar terbang bukan?",
  ui_story_5037_50379901_39_dialog_content = "Tanpa disadari, satu tahun lagi telah berlalu!",
  ui_story_5037_50379901_40_dialog_content = "Tetapi fakta bahwa itu terasa begitu cepat adalah hal yang baik.",
  ui_story_5037_50379901_41_dialog_content = "Itu berarti kami memiliki tahun yang sangat berarti.",
  ui_story_5037_50379901_42_dialog_content = "Haha, sejak kita mulai berpetualang bersama PlayerName, setiap hari terasa berarti!",
  ui_story_5037_50379901_43_dialog_content = "Apakah begitu? Kalau begitu mari kita bernostalgia, oke?",
  ui_story_5037_50379901_44_dialog_content = "Apakah Anda masih ingat semua tempat yang kita kunjungi tahun lalu?",
  ui_story_5037_50379901_45_dialog_content = "Hehe, tentu saja!",
  ui_story_5037_50379901_46_dialog_content = "Selama setahun terakhir, kami melewati badai dahsyat sebelum akhirnya tiba di Northland...",
  ui_story_5037_50379901_47_dialog_content = "Itu adalah pertama kalinya saya melihat aurora di atas Istana Musim Dingin dengan mata kepala sendiri!",
  ui_story_5037_50379901_48_dialog_content = "Itu juga pertama kalinya saya mencoba bakso goreng Northland dengan saus stroberi. Saya tidak tahu keduanya berjalan bersama dengan sangat sempurna!",
  ui_story_5037_50379901_49_dialog_content = "PlayerName menghabiskan banyak waktu di Danau Cermin selama perjalanan itu. Dia bilang dia melihat masa lalu ratu di dalam air...",
  ui_story_5037_50379901_50_dialog_content = "Saya bertanya-tanya penglihatan macam apa yang mengungkapkan dirinya kepadanya?",
  ui_story_5037_50379901_51_dialog_content = "Kemudian kami menghias pohon secercah dan menghitung mundur untuk tahun baru!",
  ui_story_5037_50379901_52_dialog_content = "Ah, ini benar-benar membawa kembali kenangan ...",
  ui_story_5037_50379901_53_dialog_content = "Dari apa, bakso goreng?",
  ui_story_5037_50379901_54_dialog_content = "Ehehehe...",
  ui_story_5037_50379901_55_dialog_content = "Dalam perjalanan kembali dari Northland, kami secara tidak sengaja mendarat di reruntuhan kota kuno bawah tanah.",
  ui_story_5037_50379901_56_dialog_content = "Untuk menghindari serangan droid kota, kami harus mengenakan pakaian orang-orang yang pernah tinggal di sana.",
  ui_story_5037_50379901_57_dialog_content = "Ha ha ha! Saya masih ingat raut wajah PlayerName ketika dia harus mengenakan gaun itu!",
  ui_story_5037_50379901_58_dialog_content = "Setelah itu, kami bertemu dengan sekelompok teman yang juga terjebak di kota.",
  ui_story_5037_50379901_59_dialog_content = "Pada awalnya, perbedaan kami hanya menyebabkan pertengkaran terus-menerus...",
  ui_story_5037_50379901_60_dialog_content = "Tapi ketika semua orang bekerja sama, kami akhirnya berhasil meyakinkan kedua gadis yang tinggal di kota kuno itu...",
  ui_story_5037_50379901_61_dialog_content = "Jadi kami semua berhasil keluar dari kota dengan selamat sebelum kota itu benar-benar hancur.",
  ui_story_5037_50379901_62_dialog_content = "PlayerName bahkan menerima pesan dari kota setelah kami kembali!",
  ui_story_5037_50379901_63_dialog_content = "Mungkin kita akan memiliki kesempatan untuk mengunjunginya lagi suatu hari nanti.",
  ui_story_5037_50379901_64_dialog_content = "Ya... Tapi itu harus menunggu! Kami masih memiliki hal-hal yang harus dilakukan!",
  ui_story_5037_50379901_65_dialog_content = "Petik bunga merah untuk gadis muda itu...",
  ui_story_5037_50379901_66_dialog_content = "Kelopak berguguran seperti butiran salju di atas sebongkah giok.",
  ui_story_5037_50379901_67_dialog_content = "Setelah tiba di Koufu-jou untuk mencari pekerjaan, kami bertemu dengan pendeta kota.",
  ui_story_5037_50379901_68_dialog_content = "Itu juga terjadi pada Festival Kasuga pada saat itu, jadi seluruh kota diselimuti oleh bunga sakura berwarna pink cerah!",
  ui_story_5037_50379901_69_dialog_content = "Tapi tak satu pun dari kami yang tahu bahwa di balik penampilan cantik Koufu-jou...",
  ui_story_5037_50379901_70_dialog_content = "Rencana pembunuhan sedang berlangsung.",
  ui_story_5037_50379901_71_dialog_content = "Balas dendam yang membara mengirim kedamaian dan kemakmuran masa lalu ke dalam kobaran api.",
  ui_story_5037_50379901_72_dialog_content = "Lagu duka apa...",
  ui_story_5037_50379901_73_dialog_content = "menunggu kota?",
  ui_story_5037_50379901_74_dialog_content = "Saya tidak ada di sana, jadi saya tidak punya cara untuk menjawab pertanyaan itu ...",
  ui_story_5037_50379901_75_dialog_content = "Hei, ya! Bukankah Anda kembali ke Lumopolis saat itu?",
  ui_story_5037_50379901_76_dialog_content = "T-Lain kali, Carleen! Saya berjanji kami akan ingat untuk mengundang Anda lain kali!",
  ui_story_5037_50379901_77_dialog_content = "Hei... Tunggu sebentar! Apakah itu sebabnya Anda tidak meminta saya untuk datang ketika Anda diundang PlayerName untuk melihat pertunjukan itu di Lumopolis?!",
  ui_story_5037_50379901_78_dialog_content = "Sudah kubilang, itu hanya untuk mencari Gretel.",
  ui_story_5037_50379901_79_dialog_content = "Kami mengikuti petunjuk sampai ke The Manor of Truth.",
  ui_story_5037_50379901_80_dialog_content = "Ironisnya, itu penuh dengan orang bodoh yang benar-benar tidak rasional.",
  ui_story_5037_50379901_81_dialog_content = "Percayalah padaku...",
  ui_story_5037_50379901_82_dialog_content = "Anda harus menganggap diri Anda beruntung karena Anda tidak harus menonton pertunjukan itu.",
  ui_story_5037_50379901_83_dialog_content = "Hmm, itu hanya membuatku semakin penasaran!",
  ui_story_5037_50379901_84_dialog_content = "Ngomong-ngomong, bukankah kita merasa seperti melupakan sesuatu?",
  ui_story_5037_50379901_85_dialog_content = "Maksudmu saat itu PlayerName pergi ke Gurun Rediesel? Anda berada di sana juga, bukan?",
  ui_story_5037_50379901_86_dialog_content = "Oh ya, Reli Berkobar! Saya benar-benar berpikir PlayerName telah diculik oleh Sinsa pada saat itu.",
  ui_story_5037_50379901_87_dialog_content = "Sayangnya, saya hanya berhasil mengejar ketinggalan di akhir reli.",
  ui_story_5037_50379901_88_dialog_content = "Adapun PlayerName, saya tidak tahu bagaimana dia berakhir di kursi penumpang mobil itu...",
  ui_story_5037_50379901_89_dialog_content = "Atau cerita macam apa dari masa lalu Azure yang dia ceritakan padanya, setelah kupikir-pikir...",
  ui_story_5037_50379901_90_dialog_content = "Saya tidak punya detailnya.",
  ui_story_5037_50379901_91_dialog_content = "Tapi satu hal yang saya yakini adalah barbekyu Gurun Rediesel benar-benar nikmat!",
  ui_story_5037_50379901_92_dialog_content = "Begitu... Sepertinya tahun ini penuh dengan pengalaman kuliner yang sangat berkesan untukmu, Vice.",
  ui_story_5037_50379901_93_dialog_content = "Anda juga berpikir begitu, Carleen?",
  ui_story_5037_50379901_94_dialog_content = "Saya tahu saya memiliki bakat khusus untuk memasak!",
  ui_story_5037_50379901_95_dialog_content = "PlayerName, kalian tunggu saja masakan baru yang akan saya racik!",
  ui_story_5037_50379901_96_dialog_content = "Kau tahu, kudengar dia menyewa kepala pelayan profesional saat kita tidak ada.",
  ui_story_5037_50379901_97_dialog_content = "Selama periode itu...",
  ui_story_5037_50379901_98_dialog_content = "PlayerName mungkin makan banyak makanan enak.",
  ui_story_5037_50379901_99_dialog_content = "Yeah... awalnya aku bertanya-tanya bagaimana dia bisa bertahan hidup tanpa kita di sisinya.",
  ui_story_5037_50379901_100_dialog_content = "Tapi dia benar-benar mampu memberi makan dirinya sendiri!",
  ui_story_5037_50379901_101_dialog_content = "Dia bahkan menjamu tamu sekarang di Cloud Gardens,",
  ui_story_5037_50379901_102_dialog_content = "yang dikelola dengan sangat cermat!",
  ui_story_5037_50379901_103_dialog_content = "Keterampilan manajemennya memang telah melihat banyak peningkatan.",
  ui_story_5037_50379901_104_dialog_content = "Tetapi jika Anda bertanya kepada saya, dia masih sangat membutuhkan orang di sisinya.",
  ui_story_5037_50379901_105_dialog_content = "Lagi pula, dia tipe orang yang membantu penculiknya menghitung uang tebusan mereka.",
  ui_story_5037_50379901_106_dialog_content = "Beruntung baginya, satu-satunya penculik yang dia temui hanyalah seorang pelatih binatang yang menakjubkan.",
  ui_story_5037_50379901_107_dialog_content = "Adapun apa yang sebenarnya terjadi selama petualangan kecil itu...",
  ui_story_5037_50379901_108_dialog_content = "Kita hanya bisa membacanya di \"The Adventures of the Extrozoologist\" sekarang.",
  ui_story_5037_50379901_109_dialog_content = "Sebenarnya, Fia menceritakan semua tentang petualangan mereka. Bahkan berkali-kali.",
  ui_story_5037_50379901_110_dialog_content = "Hah? Kapan?!",
  ui_story_5037_50379901_111_dialog_content = "Kita bertemu dengan Fia di Harbour City, ingat?",
  ui_story_5037_50379901_112_dialog_content = "Oh! Jadi saat itulah dia memberitahumu tentang itu!",
  ui_story_5037_50379901_113_dialog_content = "Saya ingat sekarang... Karnaval di Emerald sangat menyenangkan!",
  ui_story_5037_50379901_114_dialog_content = "Memang, tapi siapa sangka...",
  ui_story_5037_50379901_115_dialog_content = "bahwa di balik semua kesenangan dan kemeriahan itu, Lord Elvis merencanakan sesuatu yang sangat berbahaya.",
  ui_story_5037_50379901_116_dialog_content = "Meskipun menyadari sejauh mana penderitaannya setelah itu...",
  ui_story_5037_50379901_117_dialog_content = "Sebagai penguasa kota, ada tindakan tertentu yang tidak boleh dilakukan seseorang.",
  ui_story_5037_50379901_118_dialog_content = "Namun pada akhirnya, Elvis mengorbankan dirinya untuk menyelamatkan Harbour City dari kehancuran tertentu.",
  ui_story_5037_50379901_119_dialog_content = "Hari itu, menjadi sangat jelas bagi saya bahwa kita tidak dapat mendefinisikan seseorang sepenuhnya baik atau buruk.",
  ui_story_5037_50379901_120_dialog_content = "Kira-kira apakah Jeno pernah menemukan cara untuk membangunkan Elvis dari komanya?",
  ui_story_5037_50379901_121_dialog_content = "Jika Elvis terbangun dari komanya, saya pribadi akan mengantarnya kembali ke Lumopolis untuk diadili.",
  ui_story_5037_50379901_122_dialog_content = "Oh, eh... Benar...",
  ui_story_5037_50379901_123_dialog_content = "Setelah kembali dari Harbour City, PlayerName berlari ke Corax, yang sedang memburu seorang pembunuh berantai.",
  ui_story_5037_50379901_124_dialog_content = "Mereka mengikuti jejak si pembunuh sampai ke kota kecil bernama Euphoria.",
  ui_story_5037_50379901_125_dialog_content = "Meskipun orang pernah mengenalnya sebagai Negeri Ajaib, Euphoria kini benar-benar terperosok oleh kejahatan terorganisir dan kekerasan geng.",
  ui_story_5037_50379901_126_dialog_content = "Setiap hari, Anda mendengar tentang semua jenis pembunuhan, perampokan, dan pertikaian dalam geng lokal.",
  ui_story_5037_50379901_127_dialog_content = "Tetapi bahkan di tempat yang kotor dan berbahaya seperti Euphoria, hydrangea yang indah masih bermekaran di mana-mana.",
  ui_story_5037_50379901_128_dialog_content = "Saya percaya bahwa Euphoria akan menjadi Negeri Ajaib sejati lagi suatu saat nanti.",
  ui_story_5037_50379901_129_dialog_content = "Pokoknya, tidak lama setelah petualangan itu...",
  ui_story_5037_50379901_130_dialog_content = "PlayerName dan saya pergi untuk melihat pembukaan Rumah Hantu Andersen!",
  ui_story_5037_50379901_131_dialog_content = "Secara kebetulan, kami akhirnya menjadi bagian dari video investigasi supranatural.",
  ui_story_5037_50379901_132_dialog_content = "Kami hanya ingin bersenang-senang... Siapa sangka ada aktivitas paranormal yang sebenarnya terjadi di sana?!",
  ui_story_5037_50379901_133_dialog_content = "Jeritan yang kami dengar di dalam rumah hantu benar-benar nyata!",
  ui_story_5037_50379901_134_dialog_content = "Dan sutradara film horor favorit saya... Dia telah menggunakan Eclipsites dalam bidikannya selama ini!",
  ui_story_5037_50379901_135_dialog_content = "Alhamdulillah waktu itu saya ada urusan lain...",
  ui_story_5037_50379901_136_dialog_content = "Jangan beri tahu saya yang maha kuasa Carleen takut rumah hantu?",
  ui_story_5037_50379901_137_dialog_content = "Hmph. Aku hanya khawatir bahwa aku akan menakuti hantu perempuan itu sampai mati... Jadi bisa dikatakan begitu.",
  ui_story_5037_50379901_138_dialog_content = "Ha ha ha ha! Anda benar-benar berpikir Anda begitu menakutkan?",
  ui_story_5037_50379901_139_dialog_content = "...",
  ui_story_5037_50379901_140_dialog_content = "<size=45>Ah—Hantu!!!</size>",
  ui_story_5037_50379901_141_dialog_content = "Melihat? Itulah yang saya maksud.",
  ui_story_5037_50379901_142_dialog_content = "I-Itu kamu, Carleen?! Jangan bilang... Apa kau juga hantu?!",
  ui_story_5037_50379901_143_dialog_content = "Bukankah bermain peran di zaman sekarang? Semua orang melakukannya.",
  ui_story_5037_50379901_144_dialog_content = "Y-Ya, kamu benar...",
  ui_story_5037_50379901_145_dialog_content = "Ahem! Tapi cukup tentang itu! Kembali ke alasan sebenarnya kita di sini!",
  ui_story_5037_50379901_146_dialog_content = "Tahun akan segera berakhir, PlayerName.",
  ui_story_5037_50379901_147_dialog_content = "Kami mengumpulkan video ini untuk membantu Anda mengingat semua yang kami lakukan tahun ini!",
  ui_story_5037_50379901_148_dialog_content = "Di tahun mendatang Anda harus ingat ...",
  ui_story_5037_50379901_149_dialog_content = "untuk membawa kami bersama Anda dalam semua petualangan Anda yang akan datang!",
  ui_story_5037_50379901_151_dialog_content = "Kalian...",
  ui_story_5037_50379901_152_dialog_content = "Jadi ini kenapa akhir-akhir ini kau bersikap sangat tertutup? Karena Anda yang membuat video ini?",
  ui_story_5037_50379901_153_dialog_content = "Heehee! Kami ingin itu menjadi kejutan!",
  ui_story_5037_50379901_154_dialog_content = "Hari ini adalah hari terakhir tahun ini. Bagaimana mungkin kita tidak membuatnya istimewa?",
  ui_story_5037_50379901_155_dialog_content = "Anda bisa saja memberi tahu saya, Anda tahu ...",
  ui_story_5037_50379901_156_dialog_content = "Anda benar-benar tidak perlu bersusah payah merekam video dan semuanya!",
  ui_story_5037_50379901_157_dialog_content = "Yah, kami memang membayar Tourdog banyak uang untuk menemukan seniman untuk membuat semua seni ini...",
  ui_story_5037_50379901_158_dialog_content = "jadi kami harus berusaha sekuat tenaga untuk mendapatkan nilai uang kami!",
  ui_story_5037_50379901_159_dialog_content = "Cara yang sangat masuk akal untuk merayakan tahun baru, jika Anda bertanya kepada saya.",
